$Global:Orig = @{};
 $Global:AppliedKeys = @{}; $Global:OrigServices = @{}; $Global:OrigMisc = @{}; $Global:BackgroundJobs = [System.Collections.ArrayList]::new(); $Global:ActiveNetPreset = $null; $Global:ActiveGpuPreset = $null; $Global:SelectAllActive = $false
$Global:StateDir = Join-Path $env:LOCALAPPDATA "LessProject"; $Global:StateFile = Join-Path $Global:StateDir "state.json"
function Save-TweakState {
    try {
        if(-not(Test-Path $Global:StateDir)){New-Item -Path $Global:StateDir -ItemType Directory -Force|Out-Null}
        $json = @{Orig=$Global:Orig;AppliedKeys=$Global:AppliedKeys;TweakToggles=$Global:TweakToggles;OrigServices=$Global:OrigServices;OrigMisc=$Global:OrigMisc;ActiveNetPreset=$Global:ActiveNetPreset;ActiveGpuPreset=$Global:ActiveGpuPreset;SelectAllActive=$Global:SelectAllActive}|ConvertTo-Json -Depth 10
        
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($json)
        $encoded = [System.Convert]::ToBase64String($bytes)
        $protectedBuilder=New-Object System.Text.StringBuilder
        foreach($char in $encoded.ToCharArray()){ [void]$protectedBuilder.Append([char]([int]$char -bxor 0x13)) }
        $protected=$protectedBuilder.ToString()
        $protected | Set-Content -Path $Global:StateFile -Encoding UTF8 -EA Stop
    } catch {}
}
function ConvertTo-HashtableDeep($obj) { if($null -eq $obj){return $null}; if($obj -is [System.Collections.IDictionary]){$h=@{};foreach($k in $obj.Keys){$h[$k]=ConvertTo-HashtableDeep $obj[$k]};return $h}; if($obj -is [PSCustomObject]){$h=@{};foreach($p in $obj.PSObject.Properties){$h[$p.Name]=ConvertTo-HashtableDeep $p.Value};return $h}; if(($obj -is [System.Collections.IEnumerable]) -and ($obj -isnot [string])){return @($obj|ForEach-Object{ConvertTo-HashtableDeep $_})}; return $obj }
function Load-TweakState {
    try {
        if(Test-Path $Global:StateFile){
            $protected = Get-Content -Path $Global:StateFile -Raw -EA Stop
            $encodedBuilder=New-Object System.Text.StringBuilder
            foreach($char in $protected.ToCharArray()){ [void]$encodedBuilder.Append([char]([int]$char -bxor 0x13)) }
            $encoded=$encodedBuilder.ToString()
            $bytes = [System.Convert]::FromBase64String($encoded)
            $json = [System.Text.Encoding]::UTF8.GetString($bytes)
            $raw = $json | ConvertFrom-Json -EA Stop
            if($raw.Orig){$Global:Orig=ConvertTo-HashtableDeep $raw.Orig}
            if($raw.AppliedKeys){$Global:AppliedKeys=ConvertTo-HashtableDeep $raw.AppliedKeys}
            if($raw.TweakToggles){$Global:SavedTweakToggles=ConvertTo-HashtableDeep $raw.TweakToggles}
            if($raw.OrigServices){$Global:OrigServices=ConvertTo-HashtableDeep $raw.OrigServices}
            if($raw.OrigMisc){$Global:OrigMisc=ConvertTo-HashtableDeep $raw.OrigMisc}
            if($raw.ActiveNetPreset){$Global:ActiveNetPreset=$raw.ActiveNetPreset}
            if($raw.ActiveGpuPreset){$Global:ActiveGpuPreset=$raw.ActiveGpuPreset}
            if($null -ne $raw.SelectAllActive){$Global:SelectAllActive=[bool]$raw.SelectAllActive}
        }
    } catch {}
}
Load-TweakState

# --- Embedded FiveM Optimize (single-file, gzip+base64) ---
$Global:EmbeddedFiveMOptimizeB64 = @'

'@
function Invoke-EmbeddedFiveMOptimize {
    try {
        Add-Log "[FIVEM OPT] Expanding embedded profile..." "#FFFFFF"
        Set-CurrentTask "Loading FiveM Optimize..."
        try { Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue } catch {}
        $bytes = [Convert]::FromBase64String($Global:EmbeddedFiveMOptimizeB64)
        $ms = New-Object IO.MemoryStream(,$bytes)
        $gz = New-Object IO.Compression.GZipStream($ms, [IO.Compression.CompressionMode]::Decompress)
        $sr = New-Object IO.StreamReader($gz, [Text.Encoding]::UTF8)
        $code = $sr.ReadToEnd()
        $sr.Dispose(); $gz.Dispose(); $ms.Dispose()
        # Run in a new elevated process from temp so it has its own UI session cleanly
        $tmp = Join-Path $env:TEMP ("FiveM_Optimize_Embedded_" + [guid]::NewGuid().ToString("N") + ".ps1")
        Set-Content -LiteralPath $tmp -Value $code -Encoding UTF8
        Start-Process -FilePath "powershell.exe" -Verb RunAs -ArgumentList @(
            "-NoProfile","-ExecutionPolicy","Bypass","-File",("`"{0}`"" -f $tmp)
        ) | Out-Null
        Show-TweakToast -Label "FIVEM OPTIMIZE" -Enabled $true -OverrideText "FIVEM OPTIMIZE  /  LAUNCHED" -DurationMs 2200
        Add-Log "[FIVEM OPT] Launched embedded profile." "#FFFFFF"
        # Cleanup temp later (best-effort)
        Start-Job -ScriptBlock {
            param($p)
            Start-Sleep -Seconds 90
            Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue
        } -ArgumentList $tmp | Out-Null
    } catch {
        Add-Log "[FAIL] Embedded FiveM Optimize: $($_.Exception.Message)" "#D8D8D8"
        try {
            [System.Windows.MessageBox]::Show("Cannot launch FiveM Optimize:`n$($_.Exception.Message)","LESS PROJECT",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
        } catch {}
    }
}


# --- Embedded Kai Prime V2 (single-file, gzip+base64) ---
$Global:EmbeddedKaiPrimeB64 = @'

'@
function Invoke-EmbeddedKaiPrime {
    try {
        Add-Log "[KAI PRIME] Expanding embedded profile..." "#FFFFFF"
        Set-CurrentTask "Loading Kai Prime..."
        try { Add-Type -AssemblyName System.IO.Compression -ErrorAction SilentlyContinue } catch {}
        $bytes = [Convert]::FromBase64String($Global:EmbeddedKaiPrimeB64)
        $ms = New-Object IO.MemoryStream(,$bytes)
        $gz = New-Object IO.Compression.GZipStream($ms, [IO.Compression.CompressionMode]::Decompress)
        $sr = New-Object IO.StreamReader($gz, [Text.Encoding]::UTF8)
        $code = $sr.ReadToEnd()
        $sr.Dispose(); $gz.Dispose(); $ms.Dispose()
        $tmp = Join-Path $env:TEMP ("KaiPrime_Embedded_" + [guid]::NewGuid().ToString("N") + ".ps1")
        Set-Content -LiteralPath $tmp -Value $code -Encoding UTF8
        Start-Process -FilePath "powershell.exe" -Verb RunAs -ArgumentList @(
            "-NoProfile","-ExecutionPolicy","Bypass","-File",("`"{0}`"" -f $tmp)
        ) | Out-Null
        Show-TweakToast -Label "KAI PRIME" -Enabled $true -OverrideText "KAI PRIME  /  LAUNCHED" -DurationMs 2200
        Add-Log "[KAI PRIME] Launched embedded profile." "#FFFFFF"
        Start-Job -ScriptBlock {
            param($p)
            Start-Sleep -Seconds 120
            Remove-Item -LiteralPath $p -Force -ErrorAction SilentlyContinue
        } -ArgumentList $tmp | Out-Null
    } catch {
        Add-Log "[FAIL] Embedded Kai Prime: $($_.Exception.Message)" "#D8D8D8"
        try {
            [System.Windows.MessageBox]::Show("Cannot launch Kai Prime:`n$($_.Exception.Message)","LESS PROJECT",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
        } catch {}
    }
}

