$Global:TweakInfoByKey=@{}
$Global:TweakInfoByGroup=@{}
foreach($meta in @($Global:TweakInfo)){
    if($meta -and $meta.Key){
        $Global:TweakInfoByKey[[string]$meta.Key]=$meta
        $groupKey=[string]$meta.Group
        if(-not $Global:TweakInfoByGroup.ContainsKey($groupKey)){ $Global:TweakInfoByGroup[$groupKey]=New-Object System.Collections.ArrayList }
        [void]$Global:TweakInfoByGroup[$groupKey].Add($meta)
    }
}

function Get-SystemInfo {
    
    $info = @{OS="Windows"; CPU="Unknown CPU"; GPU="Unknown GPU"; RAM=16; RAMType="DDR4"; Adapter="No Adapter"; NetType="None"; RAMUsedPct=45}
    $os=$null; $ram=$null
    try {
        $os=Get-CimInstance Win32_OperatingSystem -EA Stop
        if($os){
            $cap=$os.Caption -replace "Microsoft\s*","" -replace "\s+"," "
            $cap=$cap.Trim()
            
            if($cap -match "^(Windows\s+\S+(\s+IoT)?(\s+Enterprise|\s+Pro|\s+Home)?)"){ $info.OS=$Matches[1].Trim() } else { $info.OS=$cap }
        }
    } catch { $info.OS="Windows" }
    try { $cpu=Get-CimInstance Win32_Processor -EA Stop|Select -First 1; if($cpu){$info.CPU=($cpu.Name -replace "\(R\)|\(TM\)|CPU|Processor","").Trim()} } catch {}
    try { $gpu=Get-CimInstance Win32_VideoController -EA Stop|Select -First 1; if($gpu){$info.GPU=$gpu.Name} } catch {}
    try { $ram=Get-CimInstance Win32_ComputerSystem -EA Stop; if($ram){$info.RAM=[math]::Round($ram.TotalPhysicalMemory/1GB)} } catch {}
    try { $net=Get-NetAdapter -EA Stop|Where-Object{$_.Status -eq "Up"}|Select -First 1; if($net){$info.Adapter=$net.InterfaceDescription; $info.NetType=if($net.InterfaceDescription -match "Wi-Fi|Wireless"){"Wi-Fi"}else{"Ethernet"}} } catch {}
    try {
        $freeRam=if($os){$os.FreePhysicalMemory}else{$null}
        $totalRam=if($ram){$ram.TotalPhysicalMemory/1KB}else{$null}
        if($freeRam -and $totalRam -and $totalRam -gt 0){$info.RAMUsedPct=[math]::Round((($totalRam-$freeRam)/$totalRam)*100)}
    } catch {}
    return $info
}


$Global:SysInfo = @{OS="Detecting..."; CPU="Detecting..."; GPU="Detecting..."; RAM=0; RAMType=""; Adapter="Detecting..."; NetType="Detecting..."; RAMUsedPct=0}
$Global:SystemInfoJob = $null
try {
    $Global:SystemInfoJob = Start-Job -ScriptBlock ${function:Get-SystemInfo} -ErrorAction Stop
} catch {
    
    
    try { $Global:SysInfo = Get-SystemInfo } catch {}
}
