    <Style x:Key="ToggleStyle" TargetType="CheckBox"><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="CheckBox"><Border x:Name="Track" Width="38" Height="20" CornerRadius="10" Background="#0A0A0A" BorderBrush="#101010" BorderThickness="1"><Border x:Name="Thumb" Width="14" Height="14" CornerRadius="7" Background="#999999" HorizontalAlignment="Left" Margin="2,0,0,0"/></Border><ControlTemplate.Triggers><Trigger Property="IsChecked" Value="True"><Setter TargetName="Track" Property="Background" Value="#363636"/><Setter TargetName="Track" Property="BorderBrush" Value="#FFFFFF"/><Setter TargetName="Thumb" Property="Background" Value="#FFFFFF"/><Setter TargetName="Thumb" Property="HorizontalAlignment" Value="Right"/><Setter TargetName="Thumb" Property="Margin" Value="0,0,2,0"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
  </Window.Resources>
  <Border BorderThickness="1" CornerRadius="18" BorderBrush="#191919">
    <Border.Effect><DropShadowEffect Color="#303030" BlurRadius="28" ShadowDepth="0" Opacity="0.35"/></Border.Effect>
    <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#0A0A0A" Offset="0"/><GradientStop Color="#010101" Offset="1"/></LinearGradientBrush></Border.Background>
    <Grid x:Name="RootGrid">
      <Grid.Clip><RectangleGeometry x:Name="RootClipGeom" Rect="0,0,1098,718" RadiusX="17" RadiusY="17"/></Grid.Clip>
      <Canvas IsHitTestVisible="False" x:Name="MainBgCanvas">
        <Ellipse Width="600" Height="300" Canvas.Left="-150" Canvas.Top="400" Opacity="0.07"><Ellipse.Fill><RadialGradientBrush><GradientStop Color="#303030" Offset="0"/><GradientStop Color="#00000000" Offset="1"/></RadialGradientBrush></Ellipse.Fill></Ellipse>
        <Ellipse Width="500" Height="280" Canvas.Left="750" Canvas.Top="420" Opacity="0.05"><Ellipse.Fill><RadialGradientBrush><GradientStop Color="#303030" Offset="0"/><GradientStop Color="#00000000" Offset="1"/></RadialGradientBrush></Ellipse.Fill></Ellipse>
      </Canvas>
      <Grid>
        <Grid.RowDefinitions><RowDefinition Height="56"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/></Grid.RowDefinitions>
        <Grid Grid.Row="0" Margin="18,0,14,0" x:Name="TopBar" Background="Transparent">
          <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
          <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center">
            <Border Width="32" Height="32" CornerRadius="10" Margin="0,0,10,0" BorderThickness="1" BorderBrush="#191919">
              <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#232323" Offset="0"/><GradientStop Color="#0A0A0A" Offset="1"/></LinearGradientBrush></Border.Background>
              <Border.Effect><DropShadowEffect Color="#303030" BlurRadius="10" ShadowDepth="0" Opacity="0.5"/></Border.Effect>
              <TextBlock Text="L" Foreground="#FFFFFF" FontSize="16" FontWeight="Black" HorizontalAlignment="Center" VerticalAlignment="Center"/>
            </Border>
            <StackPanel VerticalAlignment="Center">
              <StackPanel Orientation="Horizontal"><TextBlock Text="LESS" Foreground="#FFFFFF" FontSize="15" FontWeight="Black"/><TextBlock Text=" PROJECT" Foreground="#FFFFFF" FontSize="15" FontWeight="Black"/></StackPanel>
              <TextBlock Text="PERFORMANCE OPTIMIZER" FontSize="7" Foreground="#999999" FontWeight="SemiBold" Margin="0,-1,0,0"/>
            </StackPanel>
          </StackPanel>
                    <StackPanel Grid.Column="2" Orientation="Horizontal" HorizontalAlignment="Right" VerticalAlignment="Center">
            <Border Background="#111111" CornerRadius="18" Padding="12,5" Margin="0,0,14,0" BorderBrush="#232323" BorderThickness="1">
              <StackPanel Orientation="Horizontal"><Ellipse x:Name="StatusDotEllipse" Width="7" Height="7" Fill="#FFFFFF" VerticalAlignment="Center" Margin="0,0,7,0"/><TextBlock x:Name="StatusText" Text="READY" Foreground="#E7E7E7" FontSize="10" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel>
            </Border>
            <Button x:Name="BtnMin" Content="&#8212;" Width="28" Height="28" Background="Transparent" Foreground="#A0A0A0" BorderThickness="0" Margin="0,0,2,0" Cursor="Hand"/>
            <Button x:Name="BtnMax" Content="&#9633;" Width="28" Height="28" Background="Transparent" Foreground="#A0A0A0" FontSize="10" BorderThickness="0" Margin="0,0,2,0" Cursor="Hand"/>
            <Button x:Name="BtnClose" Content="&#10005;" Width="28" Height="28" Background="Transparent" Foreground="#A0A0A0" BorderThickness="0" Cursor="Hand"/>
          </StackPanel>
        </Grid>
        <Border Grid.Row="1" Margin="18,0,18,10" Height="1"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#00000000" Offset="0"/><GradientStop Color="#FFFFFF" Offset="0.4"/><GradientStop Color="#5A5A5A" Offset="0.6"/><GradientStop Color="#00000000" Offset="1"/></LinearGradientBrush></Border.Background></Border>
        <Grid Grid.Row="2" Margin="16,0,16,16">
          <Grid.ColumnDefinitions><ColumnDefinition Width="275"/><ColumnDefinition Width="10"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
          <Border Grid.Column="0" CornerRadius="16" BorderBrush="#232323" BorderThickness="1" Padding="14">
            <Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#111111" Offset="0"/><GradientStop Color="#0A0A0A" Offset="1"/></LinearGradientBrush></Border.Background>
            <DockPanel>
              <TextBlock DockPanel.Dock="Top" Text="CATEGORIES" Foreground="#999999" FontSize="8.5" FontWeight="Bold" Margin="2,0,0,12"/>
              <StackPanel DockPanel.Dock="Bottom">
                <Border Height="1" Margin="0,6,0,10"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#00000000" Offset="0"/><GradientStop Color="#191919" Offset="0.5"/><GradientStop Color="#00000000" Offset="1"/></LinearGradientBrush></Border.Background></Border>
                <TextBlock Text="PROGRESS" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,5"/>
                <Border Background="#111111" CornerRadius="6" Height="8" BorderBrush="#0A0A0A" BorderThickness="1" Margin="0,0,0,4"><Border x:Name="ProgressFill" CornerRadius="5" HorizontalAlignment="Left" Width="0"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#FFFFFF" Offset="0.5"/><GradientStop Color="#363636" Offset="1"/></LinearGradientBrush></Border.Background><Border.Effect><DropShadowEffect Color="#303030" BlurRadius="8" ShadowDepth="0" Opacity="0.7"/></Border.Effect></Border></Border>
                <TextBlock x:Name="ProgressPercent" Text="0%" Foreground="#999999" FontSize="9" Margin="0,0,0,12" FontWeight="Bold"/>
                <TextBlock Text="NETWORK" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,5"/>
                <Grid Margin="0,0,0,8"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="8"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                  <Button x:Name="NetPresetLan" Grid.Column="0" Height="32" Cursor="Hand" BorderThickness="0" ToolTip="Enable all wired LAN tweaks"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="8" Background="#111111" BorderBrush="#232323" BorderThickness="1"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"><TextBlock Text="&#9889; " FontSize="10" Foreground="#FFFFFF"/><TextBlock Text="LAN" Foreground="#D2D2D2" FontSize="10" FontWeight="Bold"/></StackPanel></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                  <Button x:Name="NetPresetWifi" Grid.Column="2" Height="32" Cursor="Hand" BorderThickness="0" ToolTip="Enable all Wi-Fi tweaks"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="8" Background="#111111" BorderBrush="#232323" BorderThickness="1"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"><TextBlock Text="&#9889; " FontSize="10" Foreground="#FFFFFF"/><TextBlock Text="WI-FI" Foreground="#D2D2D2" FontSize="10" FontWeight="Bold"/></StackPanel></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                </Grid>
                <Button x:Name="BtnNetTwakes" Height="32" Cursor="Hand" BorderThickness="0" Margin="0,0,0,10"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="8" Background="#111111" BorderBrush="#232323" BorderThickness="1"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"><TextBlock Text="&#9889; " FontSize="11" Foreground="#FFFFFF" VerticalAlignment="Center"/><TextBlock Text="Net Twakes" Foreground="#D2D2D2" FontSize="11" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                <TextBlock Text="GPU" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,5"/>
                <Grid Margin="0,0,0,10"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="8"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                  <Button x:Name="GpuPresetAmd" Grid.Column="0" Height="32" Cursor="Hand" BorderThickness="0"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="8" Background="#111111" BorderBrush="#232323" BorderThickness="1"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"><TextBlock Text="&#9670; " FontSize="10" Foreground="#FFFFFF"/><TextBlock Text="AMD" Foreground="#D2D2D2" FontSize="10" FontWeight="Bold"/></StackPanel></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                  <Button x:Name="GpuPresetNvidia" Grid.Column="2" Height="32" Cursor="Hand" BorderThickness="0"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="8" Background="#111111" BorderBrush="#232323" BorderThickness="1"><StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"><TextBlock Text="&#9670; " FontSize="10" Foreground="#363636"/><TextBlock Text="NVIDIA" Foreground="#D2D2D2" FontSize="10" FontWeight="Bold"/></StackPanel></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#363636"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                </Grid>
                <TextBlock Text="ONE CLICK" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,5"/>
                <Button x:Name="BtnPresetAllExceptGpuLan" Height="46" Cursor="Hand" BorderThickness="0" Margin="0,0,0,10" Padding="0" ToolTip="ONE CLICK LESS — ใช้ Gaming + Network Global + Advanced + background cleanup อัตโนมัติ; เลือกเฉพาะ LAN/WI-FI adapter และ NVIDIA/AMD GPU เอง; ระบบจะแสดง Review ก่อน Apply; ไม่ลบ Bloatware อัตโนมัติ"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="11" Background="#260606" BorderBrush="#D91616" BorderThickness="1.5" Padding="10,0"><Border.Effect><DropShadowEffect Color="#FF1E1E" BlurRadius="14" ShadowDepth="0" Opacity="0.62"/></Border.Effect><Grid VerticalAlignment="Center"><Grid.ColumnDefinitions><ColumnDefinition Width="30"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><Border Width="24" Height="24" CornerRadius="12" Background="#D91616" BorderBrush="#FF7272" BorderThickness="1" VerticalAlignment="Center"><TextBlock Text="1" Foreground="#FFFFFF" FontSize="13" FontWeight="Black" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><StackPanel Grid.Column="1" Margin="9,0,6,0" VerticalAlignment="Center"><TextBlock Text="ONE CLICK LESS" Foreground="#FFFFFF" FontSize="11.5" FontWeight="Black"/><TextBlock Text="MAX PERFORMANCE  /  REVIEW" Foreground="#FFB0B0" FontSize="6.5" FontWeight="Bold" Margin="0,2,0,0"/></StackPanel><TextBlock Grid.Column="2" Text=">" Foreground="#FF6B6B" FontSize="17" FontWeight="Bold" VerticalAlignment="Center" Margin="0,0,2,0"/></Grid></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#5A0B0B"/><Setter TargetName="Bd" Property="BorderBrush" Value="#FF4D4D"/><Setter TargetName="Bd" Property="Opacity" Value="1"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="Bd" Property="Background" Value="#8B1111"/><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/><Setter TargetName="Bd" Property="Opacity" Value="0.92"/></Trigger><Trigger Property="IsEnabled" Value="False"><Setter TargetName="Bd" Property="Opacity" Value="0.45"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                <Button x:Name="BtnRun" Height="48" FontSize="12" FontWeight="Black" Foreground="#FFFFFF" Cursor="Hand" BorderThickness="0" Margin="0,0,0,8"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="RunBorder" CornerRadius="12"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#181818" Offset="0"/><GradientStop Color="#5A5A5A" Offset="0.5"/><GradientStop Color="#FFFFFF" Offset="1"/></LinearGradientBrush></Border.Background><Border.Effect><DropShadowEffect Color="#303030" BlurRadius="18" ShadowDepth="0" Opacity="0.5"/></Border.Effect><StackPanel Orientation="Horizontal" HorizontalAlignment="Center" VerticalAlignment="Center"><TextBlock Text="&#x25B6;  " Foreground="#D8D8D8" FontSize="10" VerticalAlignment="Center"/><TextBlock Text="START LESS PROJECT" Foreground="#FFFFFF" FontSize="12" FontWeight="Black" VerticalAlignment="Center"/></StackPanel></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="RunBorder" Property="Opacity" Value="0.88"/></Trigger><Trigger Property="IsPressed" Value="True"><Setter TargetName="RunBorder" Property="Opacity" Value="0.70"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                <Button x:Name="BtnExit" Height="32" Cursor="Hand" BorderThickness="0" HorizontalAlignment="Stretch"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="9" Background="#111111" BorderBrush="#232323" BorderThickness="1"><TextBlock Text="EXIT" Foreground="#D8D8D8" FontSize="12" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#D8D8D8"/><Setter TargetName="Bd" Property="Background" Value="#0A0A0A"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
              </StackPanel>
              <ScrollViewer VerticalScrollBarVisibility="Auto" Margin="0,0,0,4" Padding="0,0,4,0"><StackPanel x:Name="StagesPanel" Margin="0,0,0,8"/></ScrollViewer>
            </DockPanel>
          </Border>
          <Grid Grid.Column="2">
            <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
            <Border Grid.Row="0" CornerRadius="16" BorderBrush="#232323" BorderThickness="1" Padding="20,16" Margin="0,0,0,10"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#111111" Offset="0"/><GradientStop Color="#0A0A0A" Offset="1"/></LinearGradientBrush></Border.Background>
              <StackPanel>
                <StackPanel Orientation="Horizontal" Margin="0,0,0,14"><Border Width="3" Height="14" CornerRadius="2" Margin="0,0,8,0"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#363636" Offset="1"/></LinearGradientBrush></Border.Background></Border><TextBlock Text="SYSTEM INFO" Foreground="#A2A2A2" FontSize="9" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel>
                <Grid Margin="0,0,0,12"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                  <StackPanel Grid.Column="0" Margin="0,0,8,0"><TextBlock Text="OS" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,4"/><TextBlock x:Name="InfoOS" Text="Windows" Foreground="#F1F1F1" FontSize="11" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/></StackPanel>
                  <StackPanel Grid.Column="1" Margin="0,0,8,0"><TextBlock Text="CPU" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,4"/><TextBlock x:Name="InfoCPU" Text="CPU" Foreground="#F1F1F1" FontSize="11" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/></StackPanel>
                  <StackPanel Grid.Column="2" Margin="0,0,8,0"><TextBlock Text="GPU" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,4"/><TextBlock x:Name="InfoGPU" Text="GPU" Foreground="#F1F1F1" FontSize="11" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/></StackPanel>
                  <StackPanel Grid.Column="3"><TextBlock Text="NET" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,4"/><TextBlock x:Name="InfoNET" Text="Ethernet" Foreground="#F1F1F1" FontSize="11" FontWeight="SemiBold"/></StackPanel>
                </Grid>
                <Grid Margin="0,0,0,14"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
                  <StackPanel Grid.Column="0" Margin="0,0,8,0"><TextBlock Text="RAM" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,4"/><TextBlock x:Name="InfoRAM" Text="16 GB" Foreground="#F1F1F1" FontSize="11" FontWeight="SemiBold"/></StackPanel>
                  <StackPanel Grid.Column="1"><TextBlock Text="ADAPTER" Foreground="#999999" FontSize="8" FontWeight="Bold" Margin="0,0,0,4"/><TextBlock x:Name="InfoAdapter" Text="Ethernet" Foreground="#F1F1F1" FontSize="11" FontWeight="SemiBold" TextTrimming="CharacterEllipsis"/></StackPanel>
                </Grid>
                <Grid><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                  <TextBlock Grid.Column="0" Text="RAM USAGE" Foreground="#999999" FontSize="8" FontWeight="Bold" VerticalAlignment="Center" Margin="0,0,12,0"/>
                  <Border Grid.Column="1" Background="#111111" CornerRadius="4" Height="6" VerticalAlignment="Center" BorderBrush="#0A0A0A" BorderThickness="1"><Border x:Name="RamUsageFill" CornerRadius="3" HorizontalAlignment="Left" Width="0"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#5A5A5A" Offset="1"/></LinearGradientBrush></Border.Background></Border></Border>
                  <TextBlock x:Name="RamUsageText" Grid.Column="2" Text="0%" Foreground="#999999" FontSize="9" FontWeight="Bold" VerticalAlignment="Center" Margin="10,0,0,0"/>
                </Grid>
              </StackPanel>
            </Border>
            <Border Grid.Row="1" CornerRadius="16" BorderBrush="#232323" BorderThickness="1" Padding="20,14" Margin="0,0,0,10"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#111111" Offset="0"/><GradientStop Color="#0A0A0A" Offset="1"/></LinearGradientBrush></Border.Background>
              <StackPanel>
                <StackPanel Orientation="Horizontal" Margin="0,0,0,12"><Border Width="3" Height="14" CornerRadius="2" Margin="0,0,8,0"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#363636" Offset="1"/></LinearGradientBrush></Border.Background></Border><TextBlock Text="QUICK TOOLS" Foreground="#A2A2A2" FontSize="9" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel>
                <StackPanel Orientation="Horizontal">
                  <Button x:Name="BtnTaskMgr" Height="34" Cursor="Hand" BorderThickness="0" Margin="0,0,8,0"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="9" Background="#111111" BorderBrush="#232323" BorderThickness="1" Padding="16,0"><TextBlock Text="Task Manager" Foreground="#D2D2D2" FontSize="11" FontWeight="SemiBold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/><Setter TargetName="Bd" Property="Background" Value="#111111"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                  <Button x:Name="BtnGpedit" Height="34" Cursor="Hand" BorderThickness="0" Margin="0,0,8,0"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="9" Background="#111111" BorderBrush="#232323" BorderThickness="1" Padding="16,0"><TextBlock Text="Group Policy" Foreground="#D2D2D2" FontSize="11" FontWeight="SemiBold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/><Setter TargetName="Bd" Property="Background" Value="#111111"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                  <Button x:Name="BtnClean" Height="34" Cursor="Hand" BorderThickness="0"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="9" Background="#111111" BorderBrush="#232323" BorderThickness="1" Padding="16,0"><TextBlock Text="Clean" Foreground="#D2D2D2" FontSize="11" FontWeight="SemiBold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/><Setter TargetName="Bd" Property="Background" Value="#111111"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                </StackPanel>
              </StackPanel>
            </Border>
            <Border Grid.Row="2" CornerRadius="16" BorderBrush="#232323" BorderThickness="1" Padding="20,16" Margin="0,0,0,10"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,1"><GradientStop Color="#111111" Offset="0"/><GradientStop Color="#0A0A0A" Offset="1"/></LinearGradientBrush></Border.Background>
              <DockPanel>
                <StackPanel DockPanel.Dock="Top" Orientation="Horizontal" Margin="0,0,0,12"><Border Width="3" Height="14" CornerRadius="2" Margin="0,0,8,0"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#363636" Offset="1"/></LinearGradientBrush></Border.Background></Border><TextBlock Text="OUTPUT LOG" Foreground="#A2A2A2" FontSize="9" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel>
                <ScrollViewer x:Name="LogScrollViewer" VerticalScrollBarVisibility="Auto"><TextBlock x:Name="LogBox" Foreground="#999999" FontSize="11" FontFamily="Consolas" TextWrapping="Wrap" LineHeight="19"/></ScrollViewer>
              </DockPanel>
            </Border>
            <Border Grid.Row="3" CornerRadius="12" BorderBrush="#232323" BorderThickness="1" Padding="20,10"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="1,0"><GradientStop Color="#111111" Offset="0"/><GradientStop Color="#111111" Offset="1"/></LinearGradientBrush></Border.Background>
              <StackPanel><TextBlock Text="CURRENT TASK" Foreground="#999999" FontSize="8" FontWeight="Bold"/><TextBlock x:Name="CurrentTaskText" Text="Waiting to start..." Foreground="#A2A2A2" FontSize="11" Margin="0,4,0,0"/></StackPanel>
            </Border>
            <Border x:Name="CategoryOverlay" Grid.Row="0" Grid.RowSpan="4" CornerRadius="16" BorderBrush="#191919" BorderThickness="1" Padding="24,20" Visibility="Collapsed"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#111111" Offset="0"/><GradientStop Color="#0A0A0A" Offset="1"/></LinearGradientBrush></Border.Background><Border.Effect><DropShadowEffect Color="#303030" BlurRadius="20" ShadowDepth="0" Opacity="0.2"/></Border.Effect>
              <Grid><Grid.Clip><RectangleGeometry x:Name="CatOverlayClipGeom" Rect="0,0,700,700" RadiusX="15" RadiusY="15"/></Grid.Clip>
                <Canvas x:Name="CatOverlayBgCanvas" IsHitTestVisible="False"/>
                <Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="*"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
                  <Grid Grid.Row="0" Margin="0,0,0,6"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions>
                    <StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center"><Border Width="4" Height="20" CornerRadius="2" Margin="0,0,10,0"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#FFFFFF" Offset="0"/><GradientStop Color="#363636" Offset="1"/></LinearGradientBrush></Border.Background></Border><TextBlock x:Name="CatOverlayTitle" Text="CATEGORY" FontSize="16" FontWeight="Black" Foreground="#FFFFFF" VerticalAlignment="Center"/></StackPanel>
                    <Button Grid.Column="1" x:Name="CatOverlayCloseX" Content="&#10005;" Width="28" Height="28" Background="Transparent" Foreground="#A0A0A0" FontSize="12" BorderThickness="0" Cursor="Hand"/>
                  </Grid>
                  <TextBlock Grid.Row="1" x:Name="CatOverlayDesc" Text="" Foreground="#A2A2A2" FontSize="11" TextWrapping="Wrap" Margin="14,0,0,18"/>
                  <ScrollViewer x:Name="CatOverlayItemsScroll" Grid.Row="2" VerticalScrollBarVisibility="Auto" HorizontalScrollBarVisibility="Disabled" VerticalContentAlignment="Top"><StackPanel x:Name="CatOverlayItems" HorizontalAlignment="Stretch" VerticalAlignment="Top"/></ScrollViewer>
                  <Button Grid.Row="3" x:Name="CatOverlayCloseBtn" Height="44" Margin="0,18,0,0" Cursor="Hand" BorderThickness="0"><Button.Template><ControlTemplate TargetType="Button"><Border x:Name="Bd" CornerRadius="10" Background="#0A0A0A" BorderBrush="#191919" BorderThickness="1"><TextBlock Text="CLOSE" Foreground="#FFFFFF" FontSize="12" FontWeight="Black" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><ControlTemplate.Triggers><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="BorderBrush" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Button.Template></Button>
                </Grid>
              </Grid>
            </Border>
          </Grid>
        </Grid>
      </Grid>
    </Grid>
  </Border>
</Window>

"@




function New-8BitBeepPlayer {
    param([double[]]$Frequencies,[int[]]$Durations,[double]$Volume=0.15)
    $sampleRate=44100
    $pcm=New-Object System.IO.MemoryStream
    $pcmWriter=New-Object System.IO.BinaryWriter($pcm)
    for($toneIndex=0;$toneIndex -lt $Frequencies.Count;$toneIndex++){
        $freq=[double]$Frequencies[$toneIndex]
        $durationMs=[int]$Durations[$toneIndex]
        $samples=[int]($sampleRate*$durationMs/1000)
        
        $attack=[math]::Max(1,[int]($sampleRate*0.006))
        $release=[math]::Max(1,[int]($sampleRate*0.022))
        for($i=0;$i -lt $samples;$i++){
            $envelope=[math]::Min(1.0,$i/[double]$attack)
            $envelope=[math]::Min($envelope,($samples-$i)/[double]$release)
            $phase=$i/[double]$sampleRate
            
            $wave=[math]::Sin(2*[math]::PI*$freq*$phase)+0.10*[math]::Sin(2*[math]::PI*($freq*2.01)*$phase)
            $pcmWriter.Write([int16]([math]::Round($Volume*32767*$envelope*$wave)))
        }
    }
    $pcmWriter.Flush()
    $data=[byte[]]$pcm.ToArray(); $pcm.Dispose()
    $dataLen=$data.Length
    $stream=New-Object System.IO.MemoryStream
    $writer=New-Object System.IO.BinaryWriter($stream)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("RIFF")); $writer.Write([int](36+$dataLen)); $writer.Write([System.Text.Encoding]::ASCII.GetBytes("WAVE"))
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("fmt ")); $writer.Write([int]16); $writer.Write([int16]1); $writer.Write([int16]1); $writer.Write([int]$sampleRate); $writer.Write([int]($sampleRate*2)); $writer.Write([int16]2); $writer.Write([int16]16)
    $writer.Write([System.Text.Encoding]::ASCII.GetBytes("data")); $writer.Write([int]$dataLen); $writer.Write($data)
    $writer.Flush(); $stream.Position=0
    $player=New-Object System.Media.SoundPlayer($stream); $player.Load()
    return ,@($player,$stream)
}
