function Get-LessProjectCSharpCompiler {
    $candidates=@()
    if($env:WINDIR){
        $candidates += (Join-Path $env:WINDIR "Microsoft.NET\Framework64\v4.0.30319\csc.exe")
        $candidates += (Join-Path $env:WINDIR "Microsoft.NET\Framework\v4.0.30319\csc.exe")
    }
    $command=Get-Command csc.exe -ErrorAction SilentlyContinue | Select-Object -First 1
    if($command){ $candidates += $command.Source }
    foreach($candidate in ($candidates | Where-Object {$_} | Select-Object -Unique)){
        if(Test-Path -LiteralPath $candidate -PathType Leaf){ return $candidate }
    }
    return $null
}
function Start-LessProjectReShadeCSharp {
    param([string]$ScriptRoot,[string]$GameFolder)
    if([string]::IsNullOrWhiteSpace($ScriptRoot)){ $ScriptRoot=$PSScriptRoot }
    if([string]::IsNullOrWhiteSpace($ScriptRoot) -and $PSCommandPath){ $ScriptRoot=Split-Path -Parent $PSCommandPath }
    if([string]::IsNullOrWhiteSpace($ScriptRoot)){ $ScriptRoot=(Get-Location).Path }
    if([string]::IsNullOrWhiteSpace($ScriptRoot)){ throw "Could not resolve the PowerShell script folder." }
    try { $scriptBase=[IO.Path]::GetFullPath([string]$ScriptRoot) } catch { throw "Could not resolve the PowerShell script folder: $ScriptRoot" }
    if([string]::IsNullOrWhiteSpace($scriptBase) -or -not (Test-Path -LiteralPath $scriptBase -PathType Container)){ throw "PowerShell script folder does not exist: $scriptBase" }

    
    

    $tempRoot=[IO.Path]::GetTempPath()
    if([string]::IsNullOrWhiteSpace($tempRoot)){ throw "Windows temporary folder could not be resolved." }
    $buildParent=Join-Path $tempRoot "LessProjectReShadeFiveM\csharp-build"
    New-Item -ItemType Directory -Path $buildParent -Force | Out-Null

    
    
    $runToken="run-" + [DateTime]::UtcNow.ToString("yyyyMMdd_HHmmss_fff") + "-" + ([Guid]::NewGuid().ToString("N").Substring(0,12))
    $buildRoot=Join-Path $buildParent $runToken
    New-Item -ItemType Directory -Path $buildRoot -Force | Out-Null

    
    
    $sourcePath=Join-Path $buildRoot "LessProjectReShadeFiveM_ModernUI.embedded.cs"
    $embeddedText=Get-LessProjectEmbeddedCSharpSource
    [System.IO.File]::WriteAllText($sourcePath,$embeddedText,(New-Object System.Text.UTF8Encoding($false)))
    if([string]::IsNullOrWhiteSpace($sourcePath) -or -not (Test-Path -LiteralPath $sourcePath -PathType Leaf)){ throw "Embedded C# source could not be prepared." }
    $iconPath=Join-Path $buildRoot "softstore_logo.ico"
    Get-LessProjectEmbeddedIcon -Destination $iconPath | Out-Null
    if([string]::IsNullOrWhiteSpace($iconPath) -or -not (Test-Path -LiteralPath $iconPath -PathType Leaf)){ throw "Embedded application icon could not be prepared." }

    $compiler=Get-LessProjectCSharpCompiler
    if([string]::IsNullOrWhiteSpace([string]$compiler) -or -not (Test-Path -LiteralPath $compiler -PathType Leaf)){
        try {
            if(-not $Global:LessProjectCSharpTypes){
                $referenceNames=@("System.dll","System.Core.dll","System.Drawing.dll","System.Windows.Forms.dll","System.IO.Compression.dll","System.IO.Compression.FileSystem.dll")
                $referencePaths=@()
                if($env:WINDIR){
                    $frameworkRoots=@(
                        (Join-Path $env:WINDIR "Microsoft.NET\Framework64\v4.0.30319"),
                        (Join-Path $env:WINDIR "Microsoft.NET\Framework\v4.0.30319")
                    )
                    foreach($referenceName in $referenceNames){
                        foreach($frameworkRoot in $frameworkRoots){
                            $referenceCandidate=Join-Path $frameworkRoot $referenceName
                            if(Test-Path -LiteralPath $referenceCandidate -PathType Leaf){ $referencePaths += $referenceCandidate; break }
                        }
                    }
                }
                if($referencePaths.Count -eq 0){ $referencePaths=$referenceNames }
                $sourceText=Get-Content -LiteralPath $sourcePath -Raw -ErrorAction Stop
                $Global:LessProjectCSharpTypes=@(Add-Type -TypeDefinition $sourceText -Language CSharp -ReferencedAssemblies $referencePaths -PassThru -ErrorAction Stop)
            }
            $assembly=$Global:LessProjectCSharpTypes[0].Assembly
            $programType=$assembly.GetType("LessProjectReShadeFiveMProgram",$true)
            $mainMethod=$programType.GetMethod("Main",[System.Reflection.BindingFlags]::Static -bor [System.Reflection.BindingFlags]::NonPublic)
            if(-not $mainMethod){ throw "C# entry point was not found." }
            $threadStart=[System.Threading.ParameterizedThreadStart]{
                param($typeInfo)
                $entry=$typeInfo.GetMethod("Main",[System.Reflection.BindingFlags]::Static -bor [System.Reflection.BindingFlags]::NonPublic)
                [void]$entry.Invoke($null,@([string[]]@()))
            }
            $uiThread=New-Object System.Threading.Thread($threadStart)
            $uiThread.SetApartmentState([System.Threading.ApartmentState]::STA)
            $uiThread.IsBackground=$false
            $uiThread.Start($programType)
            return "embedded-csharp-runtime"
        } catch {
            throw "Embedded C# runtime compilation failed: $($_.Exception.Message)"
        }
    }
    $exePath=Join-Path $buildRoot "LessProjectReShadeFiveM_ModernUI.exe"
    $logPath=Join-Path $buildRoot "compile.log"
    $compilerFullPath=[IO.Path]::GetFullPath([string]$compiler)
        $compilerDirectory=Split-Path -Parent $compilerFullPath
        if([string]::IsNullOrWhiteSpace($compilerDirectory) -or -not (Test-Path -LiteralPath $compilerDirectory -PathType Container)){ throw "C# compiler directory is invalid: $compilerFullPath" }
        $referenceNames=@("System.dll","System.Core.dll","System.Drawing.dll","System.Windows.Forms.dll","System.IO.Compression.dll","System.IO.Compression.FileSystem.dll")
        $referenceArgs=@()
        foreach($referenceName in $referenceNames){
            $referencePath=Join-Path $compilerDirectory $referenceName
            if(-not (Test-Path -LiteralPath $referencePath -PathType Leaf)){
                $referencePath=Join-Path (Split-Path -Parent $compilerDirectory) $referenceName
            }
            if(-not (Test-Path -LiteralPath $referencePath -PathType Leaf)){ throw "Required .NET reference was not found: $referenceName" }
            $referenceArgs += "/reference:$referencePath"
        }
        $compilerArgs=@(
            "/nologo",
            "/target:winexe",
            "/platform:anycpu",
            "/out:$exePath",
            "/win32icon:$iconPath"
        ) + $referenceArgs + @($sourcePath)
        $compileOutput=& $compilerFullPath @compilerArgs 2>&1 | Out-String
        [System.IO.File]::WriteAllText($logPath,$compileOutput)
        if($LASTEXITCODE -ne 0 -or -not (Test-Path -LiteralPath $exePath -PathType Leaf)){
            $detail=($compileOutput.Trim())
            if([string]::IsNullOrWhiteSpace($detail)){ $detail="No compiler output was returned." }
            throw "C# build failed: $detail`r`nLog: $logPath"
        }
    if(-not (Test-Path -LiteralPath $exePath -PathType Leaf)){ throw "The compiled ReShade program was not created." }
    $launchPath=[IO.Path]::GetFullPath($exePath)
    $launchArgs=$null
    if(-not [string]::IsNullOrWhiteSpace($GameFolder) -and (Test-Path -LiteralPath $GameFolder -PathType Container)){
        $safeFolder=([IO.Path]::GetFullPath($GameFolder)).Replace('"','\\"')
        $launchArgs='--folder "' + $safeFolder + '"'
    }
    if($launchArgs){
        Start-Process -FilePath $launchPath -ArgumentList $launchArgs -WorkingDirectory $buildRoot -ErrorAction Stop
    } else {
        Start-Process -FilePath $launchPath -WorkingDirectory $buildRoot -ErrorAction Stop
    }
    return $launchPath
}
$Global:LessProjectSettingsFile=Join-Path $env:APPDATA "LessProject\settings.json"
$Global:GameFolderPath=Join-Path $env:LOCALAPPDATA "FiveM"
$Global:SoundFxEnabled=$true


$Global:MainMotionProfile="Soft"

$Global:GalaxyStyle="Stars"
function Test-MainMotionEnabled {
    return ([string]$Global:MainMotionProfile -ne "Off")
}
function Get-MainMotionMs {
    param([double]$BaseMilliseconds)
    if(-not (Test-MainMotionEnabled)){ return 0 }
    $factor=switch([string]$Global:MainMotionProfile){
        "Fast" { 0.68; break }
        "Normal" { 1.0; break }
        default { 1.18; break }
    }
    return [math]::Max(18,[int][math]::Round($BaseMilliseconds*$factor))
}
function Load-LessProjectSettings {
    try {
        if(Test-Path -LiteralPath $Global:LessProjectSettingsFile -PathType Leaf){
            $saved=Get-Content -LiteralPath $Global:LessProjectSettingsFile -Raw -ErrorAction Stop | ConvertFrom-Json
            if($saved.GameFolderPath){ $Global:GameFolderPath=[string]$saved.GameFolderPath }
            if($null -ne $saved.SoundFxEnabled){ $Global:SoundFxEnabled=[bool]$saved.SoundFxEnabled }
            if($saved.MainMotionProfile -and @("Off","Soft","Normal","Fast") -contains [string]$saved.MainMotionProfile){ $Global:MainMotionProfile=[string]$saved.MainMotionProfile }
        }
    } catch {}
}
function Save-LessProjectSettings {
    try {
        $settingsFolder=Split-Path -Parent $Global:LessProjectSettingsFile
        New-Item -ItemType Directory -Path $settingsFolder -Force | Out-Null
        [ordered]@{ GameFolderPath=[string]$Global:GameFolderPath; SoundFxEnabled=[bool]$Global:SoundFxEnabled; MainMotionProfile=[string]$Global:MainMotionProfile } | ConvertTo-Json | Set-Content -LiteralPath $Global:LessProjectSettingsFile -Encoding UTF8
    } catch {}
}
Load-LessProjectSettings






function New-SplashAura {
    param(
        $Canvas,
        [double]$Width = 360,
        [double]$Height = 330,
        [double]$CenterX = 180,
        [double]$CenterY = 110,
        [int]$ParticleCount = 9,
        [ValidateSet("Stars","Constellation","Orbit")][string]$Style = "Stars"
    )
    try {
        if(-not $Canvas){ return }
        $Canvas.Children.Clear()
        $Canvas.ClipToBounds = $true
        $rnd = New-Object System.Random

        
        $space = New-Object System.Windows.Shapes.Rectangle
        $space.Width = $Width + 60
        $space.Height = $Height + 60
        $space.Fill = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(250,0,0,0))
        [System.Windows.Controls.Canvas]::SetLeft($space,-30)
        [System.Windows.Controls.Canvas]::SetTop($space,-30)
        [void]$Canvas.Children.Add($space)

        
        $nebulaBrush = New-Object System.Windows.Media.RadialGradientBrush
        [void]$nebulaBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb(28,170,170,170)),0.0))
        [void]$nebulaBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb(0,80,80,80)),1.0))
        $nebula = New-Object System.Windows.Shapes.Ellipse
        $nebula.Width=$Width*0.78; $nebula.Height=$Height*0.42; $nebula.Fill=$nebulaBrush
        [System.Windows.Controls.Canvas]::SetLeft($nebula,$CenterX-$nebula.Width/2)
        [System.Windows.Controls.Canvas]::SetTop($nebula,$CenterY-$nebula.Height/2)
        [void]$Canvas.Children.Add($nebula)

        
        if($Style -eq "Orbit"){
            foreach($ring in @(@{W=$Width*.52;H=$Height*.24;A=24;Speed=34},@{W=$Width*.76;H=$Height*.38;A=15;Speed=-42},@{W=$Width*.96;H=$Height*.52;A=9;Speed=52})){
                $ellipse=New-Object System.Windows.Shapes.Ellipse
                $ellipse.Width=$ring.W; $ellipse.Height=$ring.H
                $ellipse.Stroke=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb([byte]$ring.A,210,210,210))
                $ellipse.StrokeThickness=0.8; $ellipse.RenderTransformOrigin=New-Object System.Windows.Point -ArgumentList 0.5,0.5
                $rotate=New-Object System.Windows.Media.RotateTransform
                $ellipse.RenderTransform=$rotate
                [System.Windows.Controls.Canvas]::SetLeft($ellipse,$CenterX-$ellipse.Width/2)
                [System.Windows.Controls.Canvas]::SetTop($ellipse,$CenterY-$ellipse.Height/2)
                [void]$Canvas.Children.Add($ellipse)
                $ra=New-Object System.Windows.Media.Animation.DoubleAnimation
                $ra.From=0; $ra.To=$ring.Speed; $ra.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(26+[math]::Abs($ring.Speed)/4))
                $ra.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
                $ra.EasingFunction=New-Object System.Windows.Media.Animation.SineEase
                $rotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty,$ra)
            }
        }

        $nodes=New-Object System.Collections.ArrayList
        $count=[math]::Max(18,$ParticleCount)
        for($i=0;$i -lt $count;$i++){
            $x=$rnd.NextDouble()*$Width
            $y=$rnd.NextDouble()*$Height
            $size=0.65+$rnd.NextDouble()*2.2
            $bright=$rnd.NextDouble() -gt 0.80
            $alpha=if($bright){235}else{75+$rnd.Next(90)}

            
            
            $glowSize=if($bright){$size*7.0}else{$size*4.2}
            $glow=New-Object System.Windows.Shapes.Ellipse
            $glow.Width=$glowSize; $glow.Height=$glowSize
            $glowBrush=New-Object System.Windows.Media.RadialGradientBrush
            $glowCenterAlpha=if($bright){115}else{58}
            [void]$glowBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb([byte]$glowCenterAlpha,255,255,255)),0.0))
            [void]$glowBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb([byte]([math]::Round($glowCenterAlpha*0.34)),235,235,235)),0.28))
            [void]$glowBrush.GradientStops.Add((New-Object System.Windows.Media.GradientStop ([System.Windows.Media.Color]::FromArgb(0,255,255,255)),1.0))
            $glow.Fill=$glowBrush
            $glow.Opacity=if($bright){0.72}else{0.48}
            $glow.RenderTransformOrigin=New-Object System.Windows.Point -ArgumentList 0.5,0.5
            $move=New-Object System.Windows.Media.TranslateTransform
            $glow.RenderTransform=$move
            [System.Windows.Controls.Canvas]::SetLeft($glow,$x-$glowSize/2)
            [System.Windows.Controls.Canvas]::SetTop($glow,$y-$glowSize/2)
            [void]$Canvas.Children.Add($glow)

            $dot=New-Object System.Windows.Shapes.Ellipse
            $dot.Width=$size; $dot.Height=$size
            $dot.Fill=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb([byte]$alpha,255,255,255))
            $dot.Opacity=if($bright){0.72}else{0.40+$rnd.NextDouble()*0.26}
            $dot.RenderTransformOrigin=New-Object System.Windows.Point -ArgumentList 0.5,0.5
            $dot.RenderTransform=$move
            [System.Windows.Controls.Canvas]::SetLeft($dot,$x-$size/2)
            [System.Windows.Controls.Canvas]::SetTop($dot,$y-$size/2)
            [void]$Canvas.Children.Add($dot)
            [void]$nodes.Add([PSCustomObject]@{X=$x;Y=$y;Dot=$dot;Glow=$glow})

            
            $dx=($rnd.NextDouble()-0.5)*(18+$rnd.NextDouble()*30)
            $dy=($rnd.NextDouble()-0.5)*(10+$rnd.NextDouble()*20)
            $duration=16+$rnd.NextDouble()*18
            $ease=New-Object System.Windows.Media.Animation.SineEase
            $ease.EasingMode=[System.Windows.Media.Animation.EasingMode]::EaseInOut
            $ax=New-Object System.Windows.Media.Animation.DoubleAnimation
            $ax.From=-$dx; $ax.To=$dx; $ax.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration)); $ax.AutoReverse=$true; $ax.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever; $ax.EasingFunction=$ease
            $ay=New-Object System.Windows.Media.Animation.DoubleAnimation
            $ay.From=-$dy; $ay.To=$dy; $ay.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration*1.13)); $ay.AutoReverse=$true; $ay.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever; $ay.EasingFunction=$ease
            $ax.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4)
            $ay.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4)
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$ax)
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$ay)

            $tw=New-Object System.Windows.Media.Animation.DoubleAnimation
            $tw.From=if($bright){0.40}else{0.18}; $tw.To=if($bright){1.0}else{0.55}
            $tw.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(2.4+$rnd.NextDouble()*4.6)); $tw.AutoReverse=$true; $tw.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4); $tw.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
            $dot.BeginAnimation([System.Windows.Shapes.Ellipse]::OpacityProperty,$tw)
            $gw=New-Object System.Windows.Media.Animation.DoubleAnimation
            $gw.From=if($bright){0.30}else{0.12}; $gw.To=if($bright){0.78}else{0.36}
            $gw.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(2.8+$rnd.NextDouble()*4.8)); $gw.AutoReverse=$true; $gw.BeginTime=[TimeSpan]::FromSeconds($rnd.NextDouble()*4); $gw.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
            $glow.BeginAnimation([System.Windows.Shapes.Ellipse]::OpacityProperty,$gw)
        }

        if($Style -eq "Constellation"){
            
            for($a=0;$a -lt $nodes.Count;$a++){
                for($b=$a+1;$b -lt $nodes.Count;$b++){
                    $dx=$nodes[$a].X-$nodes[$b].X; $dy=$nodes[$a].Y-$nodes[$b].Y
                    $dist=[math]::Sqrt($dx*$dx+$dy*$dy)
                    if($dist -lt $Width*0.16 -and $rnd.NextDouble() -gt 0.48){
                        $line=New-Object System.Windows.Shapes.Line
                        $line.X1=$nodes[$a].X; $line.Y1=$nodes[$a].Y; $line.X2=$nodes[$b].X; $line.Y2=$nodes[$b].Y
                        $line.Stroke=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(22,210,210,210)); $line.StrokeThickness=0.55
                        [void]$Canvas.Children.Insert(2,$line)
                    }
                }
            }
        }
    } catch { }
}


function Add-ClickFX($btn) {
    if (-not $btn) { return }
    $btn.RenderTransformOrigin = New-Object -TypeName System.Windows.Point -ArgumentList 0.5,0.5
    $scaleT = New-Object System.Windows.Media.ScaleTransform
    $scaleT.ScaleX = 1; $scaleT.ScaleY = 1
    $btn.RenderTransform = $scaleT

    $btn.Add_PreviewMouseLeftButtonDown({
        $sender = $args[0]
        $down = New-Object System.Windows.Media.Animation.DoubleAnimation
        $down.To = 0.92
        $down.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(70))
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $down)
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $down)
    })
    $btn.Add_PreviewMouseLeftButtonUp({
        $sender = $args[0]
        $up = New-Object System.Windows.Media.Animation.DoubleAnimation
        $up.To = 1.0
        $up.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(150))
        $bounce = New-Object System.Windows.Media.Animation.BackEase
        $bounce.Amplitude = 0.5
        $up.EasingFunction = $bounce
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $up)
        $sender.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $up)
    })
}



function Add-BackgroundParallax {
    param(
        $TargetWindow,
        $Canvas,
        [double]$MaxOffset = 20,
        [double]$DurationX = 9,
        [double]$DurationY = 7
    )
    if (-not $Canvas) { return }
    $translate = New-Object System.Windows.Media.TranslateTransform
    $Canvas.RenderTransform = $translate

    $animX = New-Object System.Windows.Media.Animation.DoubleAnimation
    $animX.From = -$MaxOffset
    $animX.To = $MaxOffset
    $animX.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($DurationX))
    $animX.AutoReverse = $true
    $animX.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $animX.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $translate.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $animX)

    $animY = New-Object System.Windows.Media.Animation.DoubleAnimation
    $animY.From = -($MaxOffset * 0.6)
    $animY.To = ($MaxOffset * 0.6)
    $animY.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($DurationY))
    $animY.AutoReverse = $true
    $animY.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $animY.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $translate.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $animY)
}







$Global:KeyAuthConfig = [ordered]@{
    Name     = "Poomwyee's Application"
    OwnerId  = "6KdJ31higE"
    Version  = "1.0"
    Endpoint = "https://keyauth.win/api/1.3/"
}
$Global:KeyAuthSessionId = $null
$Global:KeyAuthUser = $null
$Global:KeyAuthValidationPowerShell = $null
$Global:KeyAuthValidationRunspace = $null
$Global:KeyAuthValidationAsync = $null
$Global:KeyAuthValidationStartedAt = $null

function Stop-LessProjectKeyAuthValidation {
    try {
        $ps = $Global:KeyAuthValidationPowerShell
        $async = $Global:KeyAuthValidationAsync
        if($ps -and $async -and -not $async.IsCompleted){ try { $ps.Stop() } catch {} }
        if($ps){ try { $ps.Dispose() } catch {} }
        $runspace = $Global:KeyAuthValidationRunspace
        if($runspace){ try { $runspace.Close() } catch {}; try { $runspace.Dispose() } catch {} }
    } catch {}
    $Global:KeyAuthValidationPowerShell = $null
    $Global:KeyAuthValidationRunspace = $null
    $Global:KeyAuthValidationAsync = $null
    $Global:KeyAuthValidationStartedAt = $null
}

function Start-LessProjectKeyAuthValidation {
    param(
        [Parameter(Mandatory=$true)][string]$LicenseKey,
        [Parameter(Mandatory=$true)][string]$HardwareId
    )
    
    
    
    try {
        $oldPs = $Global:KeyAuthValidationPowerShell
        $oldAsync = $Global:KeyAuthValidationAsync
        if($oldPs -and $oldAsync -and -not $oldAsync.IsCompleted){ try { $oldPs.Stop() } catch {} }
        if($oldPs){ try { $oldPs.Dispose() } catch {} }
        $oldRunspace = $Global:KeyAuthValidationRunspace
        if($oldRunspace){ try { $oldRunspace.Close() } catch {}; try { $oldRunspace.Dispose() } catch {} }
    } catch {}
    $Global:KeyAuthValidationPowerShell = $null
    $Global:KeyAuthValidationRunspace = $null
    $Global:KeyAuthValidationAsync = $null
    $Global:KeyAuthValidationStartedAt = $null
    $config = $Global:KeyAuthConfig
    $runspace = [runspacefactory]::CreateRunspace()
    $runspace.ApartmentState = 'MTA'
    $runspace.ThreadOptions = 'ReuseThread'
    $runspace.Open()
    $ps = [powershell]::Create()
    $ps.Runspace = $runspace
    [void]$ps.AddScript({
        param($Endpoint,$Name,$OwnerId,$Version,$LicenseKey,$HardwareId)
        $ErrorActionPreference = 'Stop'
        try { [Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12 } catch {}
        function Invoke-KeyAuthRequest {
            param([hashtable]$Body)
            Invoke-RestMethod -Uri $Endpoint -Method Post -Body $Body -ContentType 'application/x-www-form-urlencoded' -TimeoutSec 12 -Headers @{ 'User-Agent' = 'LESS-PROJECT/1.0' } -ErrorAction Stop
        }
        try {
            $init = Invoke-KeyAuthRequest @{ type='init'; ver=$Version; name=$Name; ownerid=$OwnerId; hash='' }
            if(-not [bool]$init.success){
                [pscustomobject]@{ Success=$false; Stage='init'; Message=([string]$init.message) }
                return
            }
            $sessionId = [string]$init.sessionid
            if([string]::IsNullOrWhiteSpace($sessionId)){ throw 'KeyAuth did not return a session.' }
            $license = Invoke-KeyAuthRequest @{ type='license'; key=$LicenseKey; hwid=$HardwareId; sessionid=$sessionId; name=$Name; ownerid=$OwnerId; code='' }
            if([bool]$license.success){
                $userName = ''
                try { $userName = [string]$license.info.username } catch {}
                [pscustomobject]@{ Success=$true; Stage='license'; Message=([string]$license.message); SessionId=$sessionId; User=$userName }
            } else {
                [pscustomobject]@{ Success=$false; Stage='license'; Message=([string]$license.message) }
            }
        } catch {
            [pscustomobject]@{ Success=$false; Stage='network'; Message=('KeyAuth connection failed: ' + $_.Exception.Message) }
        }
    }).AddArgument([string]$config.Endpoint).AddArgument([string]$config.Name).AddArgument([string]$config.OwnerId).AddArgument([string]$config.Version).AddArgument($LicenseKey.Trim()).AddArgument($HardwareId)
    try {
        $async = $ps.BeginInvoke()
        $Global:KeyAuthValidationPowerShell = $ps
        $Global:KeyAuthValidationRunspace = $runspace
        $Global:KeyAuthValidationAsync = $async
        $Global:KeyAuthValidationStartedAt = [DateTime]::UtcNow
        return $async
    } catch {
        try { $ps.Dispose() } catch {}
        try { $runspace.Close(); $runspace.Dispose() } catch {}
        throw
    }
}

function Get-LessProjectHardwareId {
    [OutputType([string])]
    param()
    $cachePath = Join-Path $Global:StateDir "hwid.txt"
    try {
        if(Test-Path -LiteralPath $cachePath -PathType Leaf){
            $cached = ([IO.File]::ReadAllText($cachePath)).Trim()
            if($cached -match '^LP-[A-F0-9]{40}$'){ return $cached }
        }
    } catch {}
    $parts = New-Object System.Collections.Generic.List[string]
    $sources = @(
        @{ Class = "Win32_ComputerSystemProduct"; Properties = @("UUID") },
        @{ Class = "Win32_BIOS"; Properties = @("SerialNumber") },
        @{ Class = "Win32_BaseBoard"; Properties = @("SerialNumber","Product") },
        @{ Class = "Win32_Processor"; Properties = @("ProcessorId") }
    )
    foreach($source in $sources){
        $items = $null
        try { $items = @(Get-CimInstance -ClassName $source.Class -OperationTimeoutSec 2 -ErrorAction Stop) } catch { $items = @() }
        foreach($item in $items){
            foreach($propertyName in $source.Properties){
                try {
                    $value = [string]$item.PSObject.Properties[$propertyName].Value
                    $value = $value.Trim()
                    if($value -and $value -notmatch '^(None|Default string|To be filled by O\.E\.M\.)$'){
                        [void]$parts.Add(($source.Class + ":" + $propertyName + "=" + $value))
                    }
                } catch {}
            }
        }
    }
    try {
        $machineGuid = [string](Get-ItemProperty -LiteralPath "HKLM:\SOFTWARE\Microsoft\Cryptography" -Name MachineGuid -ErrorAction Stop).MachineGuid
        if($machineGuid){ [void]$parts.Add("MachineGuid=" + $machineGuid.Trim()) }
    } catch {}
    if($parts.Count -eq 0){ [void]$parts.Add("ComputerName=" + [string]$env:COMPUTERNAME) }
    $canonical = (($parts | ForEach-Object { [string]$_ }) -join "|").ToUpperInvariant()
    $sha = $null
    try {
        $sha = [System.Security.Cryptography.SHA256]::Create()
        $bytes = [System.Text.Encoding]::UTF8.GetBytes($canonical)
        $hash = $sha.ComputeHash($bytes)
        $hex = New-Object System.Text.StringBuilder
        foreach($byte in $hash){ [void]$hex.Append($byte.ToString("X2")) }
                $hardwareId = "LP-" + $hex.ToString().Substring(0,40)
                try {
                    if(-not (Test-Path -LiteralPath $Global:StateDir)){ New-Item -Path $Global:StateDir -ItemType Directory -Force -ErrorAction SilentlyContinue | Out-Null }
                    [IO.File]::WriteAllText($cachePath,$hardwareId,(New-Object Text.UTF8Encoding($false)))
                } catch {}
                return $hardwareId
    } catch {
        return "LP-UNAVAILABLE"
    } finally {
        try { if($sha){ $sha.Dispose() } } catch {}
    }
}


function New-HwidMovingMonochromeBackground {
    param(
        $Canvas,
        [double]$Width = 470,
        [double]$Height = 500,
        [int]$Count = 48
    )
    try {
        if(-not $Canvas){ return }
        $Canvas.Children.Clear()
        $Canvas.ClipToBounds = $true
        $rnd = New-Object System.Random 8421

        $space = New-Object System.Windows.Shapes.Rectangle
        $space.Width = $Width + 40
        $space.Height = $Height + 40
        $space.Fill = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromArgb(250,0,0,0))
        [System.Windows.Controls.Canvas]::SetLeft($space,-20)
        [System.Windows.Controls.Canvas]::SetTop($space,-20)
        [void]$Canvas.Children.Add($space)

        for($i = 0; $i -lt [math]::Max(8,$Count); $i++){
            $dot = New-Object System.Windows.Shapes.Ellipse
            $size = 0.8 + ($rnd.NextDouble() * 1.8)
            $dot.Width = $size
            $dot.Height = $size
            $dot.Fill = [System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(190,190,190))
            $dot.Opacity = 0.78
            $dot.IsHitTestVisible = $false
            $dot.RenderTransformOrigin = New-Object System.Windows.Point -ArgumentList 0.5,0.5
            $move = New-Object System.Windows.Media.TranslateTransform
            $dot.RenderTransform = $move
            [System.Windows.Controls.Canvas]::SetLeft($dot, $rnd.NextDouble() * $Width)
            [System.Windows.Controls.Canvas]::SetTop($dot, $rnd.NextDouble() * $Height)
            [void]$Canvas.Children.Add($dot)

            $dx = ($rnd.NextDouble() - 0.5) * (32 + $rnd.NextDouble() * 58)
            $dy = ($rnd.NextDouble() - 0.5) * (20 + $rnd.NextDouble() * 40)
            $ease = New-Object System.Windows.Media.Animation.SineEase
            $ease.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
            $duration = 10 + ($rnd.NextDouble() * 12)
            $ax = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ax.From = -$dx; $ax.To = $dx
            $ax.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration))
            $ax.AutoReverse = $true
            $ax.BeginTime = [TimeSpan]::FromSeconds($rnd.NextDouble() * 2.5)
            $ax.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $ax.EasingFunction = $ease
            $ay = New-Object System.Windows.Media.Animation.DoubleAnimation
            $ay.From = -$dy; $ay.To = $dy
            $ay.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds($duration * 1.17))
            $ay.AutoReverse = $true
            $ay.BeginTime = [TimeSpan]::FromSeconds($rnd.NextDouble() * 2.5)
            $ay.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
            $ay.EasingFunction = $ease
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$ax)
            $move.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$ay)
        }
    } catch {}
}
