        $hwidBg = $hwidWindow.FindName("HwidBgCanvas")
        $hwidValueBox = $hwidWindow.FindName("HwidValueBox")
        $hwidKeyBox = $hwidWindow.FindName("HwidKeyBox")
        $hwidStatus = $hwidWindow.FindName("HwidStatus")
        $hwidContinue = $hwidWindow.FindName("HwidContinueButton")
        $hwidClose = $hwidWindow.FindName("HwidClose")
        $hwidMinimize = $hwidWindow.FindName("HwidMinimize")
        
        
        
        $startKeyAuthAction = (${function:Start-LessProjectKeyAuthValidation}).GetNewClosure()
        $stopKeyAuthAction = (${function:Stop-LessProjectKeyAuthValidation}).GetNewClosure()
        $hwidSoundAction = (${function:Play-HwidButtonSound}).GetNewClosure()
        if($hwidValueBox){ $hwidValueBox.Text = [string]$HardwareId }
        try {
            
            
            
            
            New-HwidMovingMonochromeBackground -Canvas $hwidBg -Width 400 -Height 420 -Count 8
        } catch {}
        $Global:LessProjectHwidPassed = $false
        $Global:LessProjectHwidCancelled = $false
        $hwidAuthTimer = New-Object System.Windows.Threading.DispatcherTimer
        $hwidAuthTimer.Interval = [TimeSpan]::FromMilliseconds(180)
        $hwidAuthTimer.Add_Tick({
            try {
                $async = $Global:KeyAuthValidationAsync
                if(-not $async){ return }
                if(-not $async.IsCompleted){
                    $started = $Global:KeyAuthValidationStartedAt
                    if($started -and (([DateTime]::UtcNow - $started).TotalSeconds -ge 25)){
                        try { & $stopKeyAuthAction } catch {}
                        $hwidAuthTimer.Stop()
                        $hwidContinue.IsEnabled = $true
                        $hwidStatus.Text = "LOGIN FAILED — KEYAUTH REQUEST TIMED OUT"
                        $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFB4B4")
                    }
                    return
                }
                $result = @()
                try {
                    $worker = $Global:KeyAuthValidationPowerShell
                    if($worker){ $result = @($worker.EndInvoke($async) | Select-Object -Last 1) }
                } catch {
                    $result = @([pscustomobject]@{ Success=$false; Message=('KeyAuth worker failed: ' + $_.Exception.Message) })
                }
                try { & $stopKeyAuthAction } catch {}
                $hwidAuthTimer.Stop()
                $hwidContinue.IsEnabled = $true
                if($result.Count -gt 0 -and [bool]$result[0].Success){
                    $Global:KeyAuthSessionId = [string]$result[0].SessionId
                    $Global:KeyAuthUser = [string]$result[0].User
                    $hwidStatus.Text = "LOGIN SUCCESS — OPENING LESS PROJECT"
                    $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#D5FFD5")
                    $Global:LessProjectHwidPassed = $true
                    $hwidWindow.Close()
                } else {
                    $message = if($result.Count -gt 0){ [string]$result[0].Message }else{ "No response from KeyAuth." }
                    if([string]::IsNullOrWhiteSpace($message)){ $message = "License was rejected." }
                    $hwidStatus.Text = "LOGIN FAILED — $message"
                    $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFB4B4")
                }
            } catch {
                try { $hwidAuthTimer.Stop() } catch {}
                try { & $stopKeyAuthAction } catch {}
                $hwidContinue.IsEnabled = $true
                $hwidStatus.Text = "LOGIN FAILED — $($_.Exception.Message)"
                $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFB4B4")
            }
        }.GetNewClosure())
        $hwidContinue.Add_Click({
            
            
            try { & $hwidSoundAction -Kind "Login" } catch {}
            $enteredKey = ""
            try { $enteredKey = [string]$hwidKeyBox.Password } catch {}
            if([string]::IsNullOrWhiteSpace($enteredKey)){
                $hwidStatus.Text = "LICENSE KEY REQUIRED"
                $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFB4B4")
                return
            }
            $hwidContinue.IsEnabled = $false
            $hwidStatus.Text = "CHECKING LICENSE WITH KEYAUTH..."
            $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#D8D8D8")
            try {
                & $startKeyAuthAction -LicenseKey $enteredKey -HardwareId $HardwareId | Out-Null
                $hwidAuthTimer.Start()
            } catch {
                $hwidContinue.IsEnabled = $true
                $hwidStatus.Text = "LOGIN FAILED — $($_.Exception.Message)"
                $hwidStatus.Foreground = [System.Windows.Media.BrushConverter]::new().ConvertFromString("#FFB4B4")
            }
        }.GetNewClosure())
        $hwidKeyBox.Add_KeyDown({
            param($sender,$eventArgs)
            if($eventArgs.Key -eq [System.Windows.Input.Key]::Enter){
                $hwidContinue.RaiseEvent((New-Object System.Windows.RoutedEventArgs([System.Windows.Controls.Button]::ClickEvent)))
                $eventArgs.Handled = $true
            }
        }.GetNewClosure())
        $hwidKeyBox.Add_PreviewMouseLeftButtonDown({
            try {
                [void]$hwidKeyBox.Focus()
                [System.Windows.Input.Keyboard]::Focus($hwidKeyBox) | Out-Null
            } catch {}
        }.GetNewClosure())
        $hwidClose.Add_Click({ $Global:LessProjectHwidCancelled = $true; try { $hwidAuthTimer.Stop() } catch {}; try { & $stopKeyAuthAction } catch {}; try { $hwidWindow.Close() } catch {} }.GetNewClosure())
        $hwidMinimize.Add_Click({ $hwidWindow.WindowState = [System.Windows.WindowState]::Minimized }.GetNewClosure())
        $hwidWindow.Add_PreviewMouseLeftButtonDown({
            param($sender,$eventArgs)
            $source = $eventArgs.OriginalSource -as [System.Windows.DependencyObject]
            $interactive = $false
            while($source){
                if($source -is [System.Windows.Controls.Primitives.ButtonBase] -or
                   $source -is [System.Windows.Controls.Primitives.TextBoxBase] -or
                   $source -is [System.Windows.Controls.PasswordBox] -or
                   $source -is [System.Windows.Controls.Primitives.Selector]){ $interactive = $true; break }
                try { $source = [System.Windows.Media.VisualTreeHelper]::GetParent($source) } catch { $source = $null }
            }
            if(-not $interactive -and $hwidWindow.WindowState -ne [System.Windows.WindowState]::Maximized){
                try { $eventArgs.Handled = $true; $hwidWindow.DragMove() } catch {}
            }
        }.GetNewClosure())
        $hwidWindow.Add_Closed({ try { $hwidAuthTimer.Stop() } catch {}; try { & $stopKeyAuthAction } catch {} }.GetNewClosure())
        $hwidWindow.Add_ContentRendered({
            try {
                [void]$hwidKeyBox.Focus()
                [System.Windows.Input.Keyboard]::Focus($hwidKeyBox) | Out-Null
            } catch {}
        }.GetNewClosure())
        $hwidWindow.ShowDialog() | Out-Null
        return ($Global:LessProjectHwidPassed -eq $true)
    } catch {
        try { Add-Content -LiteralPath $Global:UiErrorLogPath -Value ("$(Get-Date -Format o) HWID UI: $($_.Exception.ToString())") -Encoding UTF8 } catch {}
        try { Stop-LessProjectKeyAuthValidation } catch {}
        return $false
    }
}

