        <StackPanel x:Name="SplashLoadingWrap"><TextBlock Text="INITIALIZING PROFILE ENGINE" Foreground="#FFFFFF" FontSize="14" FontWeight="Bold" HorizontalAlignment="Center"/><TextBlock Foreground="#9D9D9D" FontSize="11" HorizontalAlignment="Center" Margin="0,8,0,0"><Run Text="SYNCING MODULES"/><Run x:Name="SplashConnectingDots" Text="..."/></TextBlock></StackPanel>
        <StackPanel x:Name="SplashStripeWrap" Width="300" Margin="0,22,0,0"><Border Height="5" Background="#0A0A0A" CornerRadius="3"><Border x:Name="SplashLoadingFill" Width="0" HorizontalAlignment="Left" Background="#FFFFFF" CornerRadius="3"/></Border></StackPanel>
