function Set-ExternalStaticUiBackground {
    param($TargetImage)
    try {
        if(-not $TargetImage){ return }
        $bgPath = Join-Path ([string]$Global:LessProjectScriptRoot) "lessproject_bg_static.png"
        if(-not (Test-Path -LiteralPath $bgPath -PathType Leaf)){ return }
        $stream = [System.IO.File]::OpenRead($bgPath)
        $bitmap = New-Object System.Windows.Media.Imaging.BitmapImage
        $bitmap.BeginInit()
        $bitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $bitmap.StreamSource = $stream
        $bitmap.EndInit()
        $stream.Dispose()
        $bitmap.Freeze()
        $TargetImage.Source = $bitmap
        $TargetImage.Visibility = [System.Windows.Visibility]::Visible
        $TargetImage.Opacity = 1.0
        $TargetImage.Stretch = [System.Windows.Media.Stretch]::UniformToFill
    } catch {}
}
function Get-LessProjectEmbeddedUiGifBytes {
    
    $roots=@()
    try {
        if($Global:LessProjectScriptRoot){ $roots += [string]$Global:LessProjectScriptRoot }
        if($PSScriptRoot){ $roots += [string]$PSScriptRoot }
        if($PSCommandPath){ $roots += (Split-Path -Parent $PSCommandPath) }
        $roots += (Get-Location).Path
        $candidates=@($roots | Where-Object {$_} | Select-Object -Unique | ForEach-Object { Join-Path $_ "giphy.gif" })
        foreach($candidate in $candidates){
            if(Test-Path -LiteralPath $candidate -PathType Leaf){
                $bytes=[System.IO.File]::ReadAllBytes($candidate)
                if($bytes -and $bytes.Length -gt 16 -and $bytes[0] -eq 0x47 -and $bytes[1] -eq 0x49 -and $bytes[2] -eq 0x46){
                    $Global:GifBackgroundLastPath=$candidate
                    return $bytes
                }
            }
        }
        $Global:GifBackgroundLastError="giphy.gif was not found. Expected beside the script: $(Join-Path $Global:LessProjectScriptRoot 'giphy.gif')"
    } catch { $Global:GifBackgroundLastError="Could not locate giphy.gif: $($_.Exception.Message)" }
    return $null
}
function Start-EmbeddedGifBackground {
    param($TargetImage,[string]$ScopeName,[int]$IntervalMs=33)
    if(-not $TargetImage -or [string]::IsNullOrWhiteSpace($ScopeName)) { return }
    try {
        if(-not $Global:EmbeddedGifStates) { $Global:EmbeddedGifStates=@{} }
        if($Global:EmbeddedGifStates.ContainsKey($ScopeName)) { Stop-EmbeddedGifBackground -ScopeName $ScopeName }
        $gifBytes=Get-LessProjectEmbeddedUiGifBytes
        $gifPath=[string]$Global:GifBackgroundLastPath
        if(-not $gifBytes -or $gifBytes.Length -lt 16 -or [string]::IsNullOrWhiteSpace($gifPath) -or -not (Test-Path -LiteralPath $gifPath -PathType Leaf)) {
            throw "giphy.gif is missing beside the PS1 file."
        }
        $TargetImage.Visibility=[System.Windows.Visibility]::Visible
        $TargetImage.Opacity=1.0
        $TargetImage.Stretch=[System.Windows.Media.Stretch]::UniformToFill
        $TargetImage.SetValue([System.Windows.Controls.Panel]::ZIndexProperty,0)
        
        
        $bgHosts=@()
        $bgNode=$TargetImage
        for($depth=0; $bgNode -and $depth -lt 5; $depth++) {
            if($bgNode.PSObject.Properties['Background']) { $bgHosts += $bgNode }
            try { $bgNode=$bgNode.Parent } catch { $bgNode=$null }
        }
        $bgBrushes=@()
        
        
        
        $staticBitmap=$null
        $fallbackPngPath=Join-Path (Split-Path -Parent $gifPath) "giphy_background.png"
        try {
            if(Test-Path -LiteralPath $fallbackPngPath -PathType Leaf) {
                $staticBitmap=New-Object System.Windows.Media.Imaging.BitmapImage
                $staticBitmap.BeginInit()
                $staticBitmap.CacheOption=[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $staticBitmap.UriSource=[System.Uri]::new($fallbackPngPath,[System.UriKind]::Absolute)
                $staticBitmap.EndInit()
                $staticBitmap.Freeze()
            } else {
                Add-Type -AssemblyName System.Drawing
                $gdImage=[System.Drawing.Image]::FromFile($gifPath)
                $gdGuid=$gdImage.FrameDimensionsList[0]
                $gdDimension=New-Object System.Drawing.Imaging.FrameDimension($gdGuid)
                $gdCount=$gdImage.GetFrameCount($gdDimension)
                $gdImage.SelectActiveFrame($gdDimension,[math]::Min(133,$gdCount-1))|Out-Null
                $gdStream=New-Object System.IO.MemoryStream
                $gdImage.Save($gdStream,[System.Drawing.Imaging.ImageFormat]::Png)
                $gdImage.Dispose()
                $gdStream.Position=0
                $staticBitmap=New-Object System.Windows.Media.Imaging.BitmapImage
                $staticBitmap.BeginInit()
                $staticBitmap.CacheOption=[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
                $staticBitmap.StreamSource=$gdStream
                $staticBitmap.EndInit()
                $staticBitmap.Freeze()
                $gdStream.Dispose()
            }
            $TargetImage.Source=$staticBitmap
            foreach($bgHost in $bgHosts) {
                $brush=New-Object System.Windows.Media.ImageBrush
                $brush.Stretch=[System.Windows.Media.Stretch]::UniformToFill
                $brush.ImageSource=$staticBitmap
                $bgHost.Background=$brush
                $bgBrushes += $brush
            }
        } catch {
            $Global:GifBackgroundLastError="Static GIF frame could not be painted for ${ScopeName}: $($_.Exception.Message)"
        }
        
        
        $stream=[System.IO.FileStream]::new($gifPath,[System.IO.FileMode]::Open,[System.IO.FileAccess]::Read,[System.IO.FileShare]::ReadWrite)
        $decoder=[System.Windows.Media.Imaging.GifBitmapDecoder]::new($stream,[System.Windows.Media.Imaging.BitmapCreateOptions]::PreservePixelFormat,[System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad)
        $frames=@($decoder.Frames)
        if(-not $frames -or $frames.Count -lt 1) { $stream.Dispose(); throw "giphy.gif contains no decodable frames for ${ScopeName}." }
        foreach($frame in $frames){ try { if($frame.CanFreeze){$frame.Freeze()} } catch {} }
        $startFrameIndex=[math]::Min(133,$frames.Count-1)
        
        
        $bgHosts=@()
        $bgNode=$TargetImage
        for($depth=0; $bgNode -and $depth -lt 5; $depth++) {
            if($bgNode.PSObject.Properties['Background']) { $bgHosts += $bgNode }
            try { $bgNode=$bgNode.Parent } catch { $bgNode=$null }
        }
        $bgBrushes=@()
        foreach($bgHost in $bgHosts) {
            $brush=New-Object System.Windows.Media.ImageBrush
            $brush.Stretch=[System.Windows.Media.Stretch]::UniformToFill
            $brush.ImageSource=$frames[$startFrameIndex]
            $bgHost.Background=$brush
            $bgBrushes += $brush
        }
        $TargetImage.Source=$frames[$startFrameIndex]
        $state=@{ Target=$TargetImage; Frames=$frames; Index=$startFrameIndex; Stream=$stream; Timer=$null; Brushes=$bgBrushes }
        $timer=New-Object System.Windows.Threading.DispatcherTimer
        $timer.Interval=[TimeSpan]::FromMilliseconds([math]::Max(20,$IntervalMs))
        $timer.Add_Tick({
            try {
                if(-not $state.Frames -or $state.Frames.Count -lt 2) { return }
                $state.Index=($state.Index+1) % $state.Frames.Count
                $frame=$state.Frames[$state.Index]
                if($state.Target) { $state.Target.Source=$frame }
                foreach($brush in @($state.Brushes)){ if($brush){ $brush.ImageSource=$frame } }
            } catch {
                $Global:GifBackgroundLastError="GIF frame update failed for ${ScopeName}: $($_.Exception.Message)"
            }
        }.GetNewClosure())
        $state.Timer=$timer
        $Global:EmbeddedGifStates[$ScopeName]=$state
        $Global:GifBackgroundLastError=$null
        $timer.Start()
        if($ScopeName -eq "Splash"){ $Global:SplashGifAnimationRunning=$true }
    } catch {
        $Global:GifBackgroundLastError="GIF background failed for ${ScopeName}: $($_.Exception.Message)"
        try { Add-Content -LiteralPath $Global:UiErrorLogPath -Value ("$(Get-Date -Format o) GIF ${ScopeName}: $($Global:GifBackgroundLastError)") -Encoding UTF8 } catch {}
        try { $TargetImage.Visibility=[System.Windows.Visibility]::Visible; $TargetImage.Opacity=1.0 } catch {}
    }
}
function Stop-EmbeddedGifBackground {
    param([string]$ScopeName)
    try {
        if($Global:EmbeddedGifStates -and $Global:EmbeddedGifStates.ContainsKey($ScopeName)) {
            $state=$Global:EmbeddedGifStates[$ScopeName]
            if($state.Timer) { $state.Timer.Stop() }
            if($state.Stream) { $state.Stream.Dispose() }
            $Global:EmbeddedGifStates.Remove($ScopeName)
        }
    } catch {}
}

