$glowMotion = @(
    @{ Name="SplashGlowA"; X=-22; Y=16; Seconds=10; MinOpacity=0.17; MaxOpacity=0.28 },
    @{ Name="SplashGlowB"; X=20; Y=-14; Seconds=13; MinOpacity=0.13; MaxOpacity=0.23 },
    @{ Name="SplashGlowC"; X=-15; Y=-18; Seconds=9; MinOpacity=0.09; MaxOpacity=0.16 }
)
foreach($g in $glowMotion){
    try {
        $glow = $splashWindow.FindName($g.Name)
        if(-not $glow){ continue }
        $glowTransform = New-Object System.Windows.Media.TranslateTransform
        $glow.RenderTransform = $glowTransform

        $gx = New-Object System.Windows.Media.Animation.DoubleAnimation
        $gx.From = -[double]$g.X; $gx.To = [double]$g.X
        $gx.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds([double]$g.Seconds))
        $gx.AutoReverse = $true; $gx.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $gx.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
        $glowTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty, $gx)

        $gy = $gx.Clone()
        $gy.From = -[double]$g.Y; $gy.To = [double]$g.Y
        $gy.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(([double]$g.Seconds) * 0.82))
        $glowTransform.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty, $gy)

        $go = New-Object System.Windows.Media.Animation.DoubleAnimation
        $go.From = [double]$g.MinOpacity; $go.To = [double]$g.MaxOpacity
        $go.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(([double]$g.Seconds) * 0.68))
        $go.AutoReverse = $true; $go.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
        $go.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
        $glow.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $go)
    } catch {}
}



$Global:SplashClosedByX = $false






function Start-SplashLoading {
    $BtnSplashStart.IsEnabled = $false
    $BtnSplashStart.Content = "LOADING"
    $SplashLoadingFill.Width = 0
    $SplashRingPercentText.Text = "0%"

    
    
    $Global:SplashRingThickness = 6.0
    $Global:SplashRingCircumference = [math]::PI * (112 - $Global:SplashRingThickness)
    $Global:SplashRingDashUnits = $Global:SplashRingCircumference / $Global:SplashRingThickness
    $initialDashArray = New-Object System.Windows.Media.DoubleCollection
    [void]$initialDashArray.Add(0)
    [void]$initialDashArray.Add([double]($Global:SplashRingDashUnits * 3))
    $SplashRingProgress.StrokeDashArray = $initialDashArray

    
    
    $ambientRotate = New-Object System.Windows.Media.Animation.DoubleAnimation
    $ambientRotate.From = -90; $ambientRotate.To = 270
    $ambientRotate.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(6.0))
    $ambientRotate.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $ambientRotate.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $ambientRotate.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    if($SplashRingAmbientRotate){
        $SplashRingAmbientRotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $ambientRotate)
    }

    
    $breatheX = New-Object System.Windows.Media.Animation.DoubleAnimation
    $breatheX.From = 1.0; $breatheX.To = 1.08
    $breatheX.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(1.6))
    $breatheX.AutoReverse = $true
    $breatheX.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $breatheX.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $breatheX.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $breatheY = $breatheX.Clone()
    if($SplashLogoBreathe){
        $SplashLogoBreathe.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty, $breatheX)
        $SplashLogoBreathe.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty, $breatheY)
    }

    
    
    $barPulse = New-Object System.Windows.Media.Animation.DoubleAnimation
    $barPulse.From = 0.72; $barPulse.To = 1.0
    $barPulse.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(1.8))
    $barPulse.AutoReverse = $true
    $barPulse.RepeatBehavior = [System.Windows.Media.Animation.RepeatBehavior]::Forever
    $barPulse.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $barPulse.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    if($SplashLoadingFill){
        $SplashLoadingFill.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $barPulse)
    }

    
    $Global:SplashDotsFrames = @(".", "..", "...")
    $Global:SplashDotsIndex = 2
    $Global:SplashDotsTimer = New-Object System.Windows.Threading.DispatcherTimer
    $Global:SplashDotsTimer.Interval = [TimeSpan]::FromMilliseconds(360)
    $Global:SplashDotsTimer.Add_Tick({
        $Global:SplashDotsIndex = ($Global:SplashDotsIndex + 1) % $Global:SplashDotsFrames.Count
        if($SplashConnectingDots){ $SplashConnectingDots.Text = $Global:SplashDotsFrames[$Global:SplashDotsIndex] }
    })
    $Global:SplashDotsTimer.Start()

    $splashFadeOut = New-Object System.Windows.Media.Animation.DoubleAnimation
    $splashFadeOut.From = 1
    $splashFadeOut.To = 0
    $splashFadeOut.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(260))
    $splashFadeOut.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $splashFadeOut.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $SplashStartGroup.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $splashFadeOut)
    $SplashStartGroup.IsHitTestVisible = $false

    $splashFadeIn = New-Object System.Windows.Media.Animation.DoubleAnimation
    $splashFadeIn.From = 0
    $splashFadeIn.To = 1
    $splashFadeIn.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(300))
    $splashFadeIn.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $splashFadeIn.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $SplashLoadingGroup.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $splashFadeIn)

    
    $Global:SplashLoadFullWidth = 300 - 4
    $Global:SplashLoadPct = 0

    $Global:SplashLoadTimer = New-Object System.Windows.Threading.DispatcherTimer
    
    
    
    $Global:SplashLoadTimer.Interval = [TimeSpan]::FromMilliseconds(70)
    $Global:SplashLoadTimer.Add_Tick({
        $Global:SplashLoadPct += 4
        if ($Global:SplashLoadPct -ge 100) {
            $Global:SplashLoadPct = 100
        }
        $fillWidthNow = [double]$Global:SplashLoadFullWidth * ($Global:SplashLoadPct / 100.0)
        if($SplashLoadingFill){ $SplashLoadingFill.Width = $fillWidthNow }
        if($SplashRingPercentText){ $SplashRingPercentText.Text = "$($Global:SplashLoadPct)%" }

        $ringDash = $Global:SplashRingDashUnits * ($Global:SplashLoadPct / 100.0)
        $ringGap  = $Global:SplashRingDashUnits * 3
        $ringDashArray = New-Object System.Windows.Media.DoubleCollection
        [void]$ringDashArray.Add([double]$ringDash)
        [void]$ringDashArray.Add([double]$ringGap)
        if($SplashRingProgress){ $SplashRingProgress.StrokeDashArray = $ringDashArray }

        if ($Global:SplashLoadPct -ge 100) {
            if($Global:SplashLoadTimer){ $Global:SplashLoadTimer.Stop() }
            if($Global:SplashDotsTimer){ $Global:SplashDotsTimer.Stop() }
            try {
                if($SplashRingAmbientRotate){ $SplashRingAmbientRotate.BeginAnimation([System.Windows.Media.RotateTransform]::AngleProperty, $null) }
                if($SplashLoadingFill){ $SplashLoadingFill.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $null); $SplashLoadingFill.Opacity = 1 }
            } catch {}
            if($splashWindow){
                
                $handoffFade = New-Object System.Windows.Media.Animation.DoubleAnimation
                $handoffFade.From = 1; $handoffFade.To = 0
                $handoffFade.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(260))
                $handoffFade.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
                $handoffFade.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
                $splashWindow.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $handoffFade)
                $Global:SplashCloseTimer = New-Object System.Windows.Threading.DispatcherTimer
                $Global:SplashCloseTimer.Interval = [TimeSpan]::FromMilliseconds(150)
                $Global:SplashCloseTimer.Add_Tick({
                    $Global:SplashCloseTimer.Stop()
                    try { if($splashWindow){ $splashWindow.Close() } } catch {}
                }.GetNewClosure())
                $Global:SplashCloseTimer.Start()
            }
        }
    })
    $Global:SplashLoadTimer.Start()
}

