$splashWindow.Add_PreviewMouseLeftButtonDown({
    param($sender, $eventArgs)
    $source = $eventArgs.OriginalSource -as [System.Windows.DependencyObject]
    $isInteractive = $false
    while ($source) {
        if ($source -is [System.Windows.Controls.Primitives.ButtonBase] -or
            $source -is [System.Windows.Controls.TextBox] -or
            $source -is [System.Windows.Controls.Primitives.ScrollBar]) {
            $isInteractive = $true
            break
        }
        try { $source = [System.Windows.Media.VisualTreeHelper]::GetParent($source) } catch { $source = $null }
    }
    if (-not $isInteractive -and $splashWindow.WindowState -ne [System.Windows.WindowState]::Maximized) {
        try {
            $eventArgs.Handled = $true
            $splashWindow.DragMove()
        } catch {}
    }
})

