  <Style x:Key="ToggleStyle" TargetType="CheckBox"><Setter Property="Cursor" Value="Hand"/><Setter Property="Template"><Setter.Value><ControlTemplate TargetType="CheckBox"><Border x:Name="toggleTrack" Width="43" Height="22" CornerRadius="11" Background="#141414" BorderBrush="#3E3E3E" BorderThickness="1"><Border x:Name="toggleThumb" Width="14" Height="14" CornerRadius="7" Background="#8C8C8C" HorizontalAlignment="Left" Margin="3,0,0,0"/></Border><ControlTemplate.Triggers><Trigger Property="IsChecked" Value="True"><Setter TargetName="toggleTrack" Property="Background" Value="#181818"/><Setter TargetName="toggleTrack" Property="BorderBrush" Value="#FFFFFF"/><Setter TargetName="toggleThumb" Property="Background" Value="#FFFFFF"/><Setter TargetName="toggleThumb" Property="HorizontalAlignment" Value="Right"/><Setter TargetName="toggleThumb" Property="Margin" Value="0,0,3,0"/></Trigger><Trigger Property="IsMouseOver" Value="True"><Setter TargetName="toggleTrack" Property="BorderBrush" Value="#FFFFFF"/></Trigger></ControlTemplate.Triggers></ControlTemplate></Setter.Value></Setter></Style>
 </Window.Resources>
