Border Grid.Column="2" Background="#252525" BorderBrush="#626262" BorderThickness="1" CornerRadius="8" Padding="9,7"><StackPanel><TextBlock Text="RESTORE POINT" Foreground="#D8D8D8" FontSize="8" FontWeight="Bold"/><TextBlock x:Name="RecoveryRestorePointText" Text="SKIPPED" Foreground="#D2D2D2" FontSize="9" Margin="0,3,0,0"/></StackPanel></Border></Grid><Grid Grid.Row="2" Margin="0,0,0,9"><Grid.RowDefinitions><RowDefinition Height="62"/><RowDefinition Height="62"/><RowDefinition Height="62"/></Grid.RowDefinitions><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="8"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Button x:Name="RecoveryRestore" Tag="restore" Grid.Column="0" Style="{StaticResource QuietButton}" Height="56" HorizontalContentAlignment="Stretch" Margin="0,0,0,6"><TextBlock Text="RESTORE SAVED SETTINGS" Foreground="#F5F5F5" FontSize="8.5" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Button><Button x:Name="RecoveryNetwork" Tag="network" Grid.Column="2" Style="{StaticResource QuietButton}" Height="56" HorizontalContentAlignment="Stretch" Margin="0,0,0,6"><TextBlock Text="NETWORK REPAIR" Foreground="#F5F5F5" FontSize="8.5" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Button><Button x:Name="RecoveryWindows" Tag="windows" Grid.Row="1" Grid.Column="0" Style="{StaticResource QuietButton}" Height="56" HorizontalContentAlignment="Stretch" Margin="0,0,0,6"><TextBlock Text="WINDOWS FILE REPAIR" Foreground="#F5F5F5" FontSize="8.5" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Button><Button x:Name="RecoveryServices" Tag="services" Grid.Row="1" Grid.Column="2" Style="{StaticResource QuietButton}" Height="56" HorizontalContentAlignment="Stretch" Margin="0,0,0,6"><TextBlock Text="SERVICES &amp; TASKS" Foreground="#F5F5F5" FontSize="8.5" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Button><Button x:Name="RecoveryPower" Tag="power" Grid.Row="2" Grid.Column="0" Style="{StaticResource QuietButton}" Height="56" HorizontalContentAlignment="Stretch" Margin="0,0,0,6"><TextBlock Text="POWER / BCD RESET" Foreground="#F5F5F5" FontSize="8.5" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Button><Button x:Name="RecoveryDiagnostics" Tag="diagnostics" Grid.Row="2" Grid.Column="2" Style="{StaticResource QuietButton}" Height="56" HorizontalContentAlignment="Stretch" Margin="0,0,0,6"><TextBlock Text="EXPORT DIAGNOSTICS" Foreground="#F5F5F5" FontSize="8.5" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Button></Grid><Border Grid.Row="3" Background="#181818" BorderBrush="#626262" BorderThickness="1" CornerRadius="8" Padding="9,7" Margin="0,0,0,11"><TextBlock Text="&#9888; Only changes tracked by LESS PROJECT can be restored." Foreground="#D2D2D2" FontSize="8" TextWrapping="Wrap"/></Border><Grid Grid.Row="4"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="8"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Button x:Name="RecoveryClose" Grid.Column="0" Content="CLOSE" Style="{StaticResource QuietButton}" Height="30"/><Button x:Name="RecoveryRun" Grid.Column="2" Content="RUN SELECTED" Style="{StaticResource QuietButton}" Height="30" Foreground="#FFFFFF" IsEnabled="False"/></Grid></Grid></Border></Border><Border x:Name="InstallModalOverlay" Background="#D9000000" Visibility="Collapsed" Panel.ZIndex="80"><Border x:Name="InstallModalPanel" Width="520" Background="#121212" BorderBrush="#777777" BorderThickness="1" CornerRadius="16" Padding="20" HorizontalAlignment="Center" VerticalAlignment="Center"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><Grid Grid.Row="0" Margin="0,0,0,15"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="INSTALL RESHADE" Foreground="#FFFFFF" FontSize="16" FontWeight="Black"/><TextBlock x:Name="InstallModalState" Text="PREPARING INSTALLATION" Foreground="#9A9A9A" FontSize="8.5" FontWeight="Bold" Margin="0,4,0,0"/></StackPanel><Border Grid.Column="1" Background="#252525" BorderBrush="#BDBDBD" BorderThickness="1" CornerRadius="8" Padding="8,5" VerticalAlignment="Center"><TextBlock x:Name="InstallModalPercent" Text="0%" Foreground="#FFFFFF" FontSize="10" FontWeight="Black"/></Border></Grid><Border Grid.Row="1" Height="8" Background="#202020" BorderBrush="#4A4A4A" BorderThickness="1" CornerRadius="4" Margin="0,0,0,10"><Border x:Name="InstallModalProgressFill" Width="0" HorizontalAlignment="Left" Background="#FFFFFF" CornerRadius="3"/></Border><TextBlock x:Name="InstallModalDetail" Grid.Row="2" Text="Waiting for the installer..." Foreground="#C6C6C6" FontSize="9" TextWrapping="Wrap" Margin="0,0,0,14"/><Border x:Name="InstallModalSuccessBadge" Grid.Row="3" Background="#1E1E1E" BorderBrush="#FFFFFF" BorderThickness="1" CornerRadius="9" Padding="10,8" Visibility="Collapsed" Margin="0,0,0,14"><StackPanel Orientation="Horizontal"><TextBlock Text="✓" Foreground="#FFFFFF" FontSize="14" FontWeight="Bold" Margin="0,0,8,0"/><TextBlock x:Name="InstallModalSuccessText" Text="INSTALLATION COMPLETE" Foreground="#FFFFFF" FontSize="9" FontWeight="Bold" VerticalAlignment="Center"/></StackPanel></Border><Button x:Name="InstallModalClose" Grid.Row="4" Content="CLOSE" Style="{StaticResource QuietButton}" Height="32" Foreground="#FFFFFF" IsEnabled="False"/></Grid></Border></Border></Grid></Border></Grid><Border Grid.Column="4" x:Name="SystemInfoPanel" Visibility="Visible" MinWidth="208" HorizontalAlignment="Stretch" VerticalAlignment="Stretch" BorderBrush="#515151" BorderThickness="1" CornerRadius="14" Padding="12"><Border.Background><LinearGradientBrush StartPoint="0,0" EndPoint="0,1"><GradientStop Color="#141414" Offset="0"/><GradientStop Color="#0F0F0F" Offset="1"/></LinearGradientBrush></Border.Background><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="18" ShadowDepth="0" Opacity="0.58"/></Border.Effect><StackPanel><Grid Margin="0,0,0,9"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel><TextBlock Text="SYSTEM INFO" Foreground="#FFFFFF" FontSize="14" FontWeight="Black" Margin="0,0,0,2"/></StackPanel><Border Grid.Column="1" Background="#252525" BorderBrush="#A8A8A8" BorderThickness="1" CornerRadius="8" Padding="6,4"><StackPanel Orientation="Horizontal"><Ellipse Width="5" Height="5" Fill="#E6E6E6" Margin="0,0,4,0"/><TextBlock Text="READY" Foreground="#FFFFFF" FontSize="6.5" FontWeight="Bold"/></StackPanel></Border></Grid><Border Height="1" Background="#343434" Margin="0,0,0,11"/><TextBlock Text="NETWORK PROFILE" Foreground="#B5B5B5" FontSize="7.2" FontWeight="Bold" Margin="1,0,0,6"/><Grid Margin="0,0,0,7"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="6"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Button x:Name="NetPresetLan" Grid.Column="0" Content="LAN" Style="{StaticResource QuietButton}" Height="30" Background="#161616" BorderBrush="#696969" Foreground="#FAFAFA" FontSize="8.2" FontWeight="SemiBold"/><Button x:Name="NetPresetWifi" Grid.Column="2" Content="WI-FI" Style="{StaticResource QuietButton}" Height="30" Background="#161616" BorderBrush="#696969" Foreground="#FAFAFA" FontSize="8.2" FontWeight="SemiBold"/></Grid><TextBlock Text="GRAPHICS PROFILE" Foreground="#B5B5B5" FontSize="7.2" FontWeight="Bold" Margin="1,3,0,6"/><Grid Margin="0,0,0,7"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="6"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Button x:Name="GpuPresetNvidia" Grid.Column="0" Content="NVIDIA" Style="{StaticResource QuietButton}" Height="30" Background="#161616" BorderBrush="#696969" Foreground="#FAFAFA" FontSize="8.2" FontWeight="SemiBold"/><Button x:Name="GpuPresetAmd" Grid.Column="2" Content="AMD" Style="{StaticResource QuietButton}" Height="30" Background="#161616" BorderBrush="#696969" Foreground="#FAFAFA" FontSize="8.2" FontWeight="SemiBold"/></Grid><Button x:Name="BtnPresetAllExceptGpuLan" Content="ONE CLICK LESS" Style="{StaticResource QuietButton}" Height="30" Foreground="#FFFFFF" Background="#262626" BorderBrush="#BDBDBD" FontSize="8.2" FontWeight="Bold" Margin="0,0,0,12"/><Grid Margin="0,0,0,9"><Grid.ColumnDefinitions><ColumnDefinition Width="*"/><ColumnDefinition Width="6"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border Background="#222222" BorderBrush="#5A5A5A" BorderThickness="1" CornerRadius="9" Padding="8,7"><StackPanel><TextBlock Text="ACTIVE TWEAKS" Foreground="#B5B5B5" FontSize="6.5" FontWeight="Bold"/><TextBlock x:Name="ActiveTweakCount" Text="0 ACTIVE" Foreground="#FFFFFF" FontSize="11" FontWeight="Black" Margin="0,3,0,0"/></StackPanel></Border><Border Grid.Column="2" Background="#252525" BorderBrush="#626262" BorderThickness="1" CornerRadius="8" Padding="7,6"><StackPanel><TextBlock Text="BACKUPS" Foreground="#B5B5B5" FontSize="6.5" FontWeight="Bold"/><TextBlock Text="TRACKED" Foreground="#F5F5F5" FontSize="9" FontWeight="Bold" Margin="0,4,0,0"/></StackPanel></Border></Grid><TextBlock Text="HARDWARE" Foreground="#E6E6E6" FontSize="8" FontWeight="Bold" Margin="1,1,0,6"/><Border Background="#141414" BorderBrush="#3F3F3F" BorderThickness="1" CornerRadius="9" Padding="9,8"><Grid><Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions><Grid.ColumnDefinitions><ColumnDefinition Width="45"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><TextBlock Text="CPU" Style="{StaticResource MetricLabel}"/><TextBlock x:Name="InfoCPU" Grid.Column="1" Style="{StaticResource MetricValue}" Text="Detecting..." TextTrimming="CharacterEllipsis" Margin="0,0,0,5"/><TextBlock Text="GPU" Grid.Row="1" Style="{StaticResource MetricLabel}"/><TextBlock x:Name="InfoGPU" Grid.Row="1" Grid.Column="1" Style="{StaticResource MetricValue}" Text="Detecting..." TextTrimming="CharacterEllipsis" Margin="0,0,0,5"/><TextBlock Text="RAM" Grid.Row="2" Style="{StaticResource MetricLabel}"/><TextBlock x:Name="InfoRAM" Grid.Row="2" Grid.Column="1" Style="{StaticResource MetricValue}" Text="Detecting..." Margin="0,0,0,5"/><TextBlock Text="OS" Grid.Row="3" Style="{StaticResource MetricLabel}"/><TextBlock x:Name="InfoOS" Grid.Row="3" Grid.Column="1" Style="{StaticResource MetricValue}" Text="Detecting..." TextTrimming="CharacterEllipsis" Margin="0,0,0,5"/><TextBlock Text="NET" Grid.Row="4" Style="{StaticResource MetricLabel}"/><TextBlock x:Name="InfoNET" Grid.Row="4" Grid.Column="1" Style="{StaticResource MetricValue}" Text="Detecting..." Margin="0,0,0,5"/><TextBlock Text="ADAPTER" Grid.Row="5" Style="{StaticResource MetricLabel}"/><TextBlock x:Name="InfoAdapter" Grid.Row="5" Grid.Column="1" Style="{StaticResource MetricValue}" Text="Detecting..." TextTrimming="CharacterEllipsis"/></Grid></Border><Grid Margin="0,10,0,0"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><TextBlock Text="RAM" Style="{StaticResource MetricLabel}" VerticalAlignment="Center" Margin="0,0,5,0"/><Border Grid.Column="1" Height="5" Background="#141414" BorderBrush="#4A4A4A" BorderThickness="1" CornerRadius="3" VerticalAlignment="Center"><Border x:Name="RamUsageFill" Width="0" HorizontalAlignment="Left" Background="#FFFFFF" CornerRadius="3"/></Border><TextBlock x:Name="RamUsageText" Grid.Column="2" Text="0%" Foreground="#FFFFFF" FontSize="7.5" FontWeight="Bold" VerticalAlignment="Center" Margin="5,0,0,0"/></Grid><Button x:Name="BtnRamCleaner" Content="RAMMAP CLEAN" ToolTip="RAMMap-style cleanup: purge low-priority and standby memory without closing working apps" Style="{StaticResource QuietButton}" Height="32" Background="#1F1F1F" BorderBrush="#B0B0B0" Foreground="#FFFFFF" FontSize="8.5" FontWeight="Bold" Margin="0,12,0,0"/><Button x:Name="BtnClearCaches" Content="AUTO FIVEM CACHE" ToolTip="Auto-detect and clear safe FiveM cache folders" Style="{StaticResource QuietButton}" Height="32" Background="#242424" BorderBrush="#E0E0E0" Foreground="#FAFAFA" FontSize="8.5" FontWeight="Bold" Margin="0,8,0,0"/><Button x:Name="BtnJunkCleaner" Content="CLEAN JUNK FILES" Style="{StaticResource QuietButton}" Height="32" Background="#202020" BorderBrush="#BDBDBD" Foreground="#EEEEEE" FontSize="8.5" FontWeight="Bold" Margin="0,8,0,0"/><Button x:Name="BtnCitizenFX" Content="CITIZENFX" ToolTip="Update and open CitizenFX.ini" Style="{StaticResource QuietButton}" Height="32" Background="#202020" BorderBrush="#D2D2D2" Foreground="#FAFAFA" FontSize="8.2" FontWeight="Bold" Margin="0,8,0,0"/></StackPanel></Border></Grid>
    <Grid Grid.Row="2" Margin="18,0,18,0"><Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/><ColumnDefinition Width="Auto"/></Grid.ColumnDefinitions><StackPanel Grid.Column="0" Orientation="Horizontal" VerticalAlignment="Center"><StackPanel x:Name="BottomActions" Orientation="Horizontal" VerticalAlignment="Center"><Button x:Name="BtnExit" Content="EXIT" Visibility="Collapsed" Style="{StaticResource QuietButton}" Width="1" Height="1"/></StackPanel></StackPanel><TextBlock Grid.Column="2" Text="LESS PROJECT" Foreground="#626262" FontSize="7" VerticalAlignment="Center"/><StackPanel x:Name="HiddenLegacyControls" Grid.Column="1" Visibility="Collapsed"><TextBlock x:Name="CurrentTaskText" Text="Ready when you are."/><Ellipse x:Name="FooterNoticeDot" Width="6" Height="6"/><TextBlock x:Name="FooterNoticeText" Text="READY"/><Button x:Name="BtnTaskMgr"/><Button x:Name="BtnGpedit"/><Button x:Name="BtnClean"/><StackPanel x:Name="StagesPanel"/><Border x:Name="ProgressHost" Height="5"><Border x:Name="ProgressFill" Width="0"/></Border><TextBlock x:Name="ProgressPercent" Text="0%"/><ScrollViewer x:Name="LogScrollViewer"><TextBlock x:Name="LogBox"/></ScrollViewer></StackPanel></Grid>
   </Grid>
   <Grid x:Name="TweakToastHost" IsHitTestVisible="False" Panel.ZIndex="500" HorizontalAlignment="Stretch" VerticalAlignment="Stretch"><Border x:Name="TweakToastBanner" MinWidth="300" MaxWidth="520" HorizontalAlignment="Center" VerticalAlignment="Center" RenderTransformOrigin="0.5,0.5" Visibility="Collapsed" Opacity="0" Background="#141414" BorderBrush="#A8A8A8" BorderThickness="1" CornerRadius="12" Padding="16,12"><Border.Effect><DropShadowEffect Color="#000000" BlurRadius="26" ShadowDepth="0" Opacity="0.7"/></Border.Effect><Border.RenderTransform><TransformGroup><ScaleTransform x:Name="TweakToastScale" ScaleX="0.88" ScaleY="0.88"/><TranslateTransform x:Name="TweakToastTranslate" Y="8"/></TransformGroup></Border.RenderTransform><Grid><Grid.ColumnDefinitions><ColumnDefinition Width="28"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions><Border Width="20" Height="20" CornerRadius="10" Background="#242424" BorderBrush="#8E8E8E" BorderThickness="1" VerticalAlignment="Center"><TextBlock x:Name="TweakToastIcon" Text="✓" Foreground="#FFFFFF" FontFamily="Segoe UI Symbol" FontSize="12" FontWeight="Bold" HorizontalAlignment="Center" VerticalAlignment="Center"/></Border><TextBlock x:Name="TweakToastText" Grid.Column="1" Text="เปิด System Responsiveness" Foreground="#FAFAFA" FontSize="11" FontWeight="SemiBold" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" TextWrapping="Wrap" Margin="8,0,0,0"/></Grid></Border></Grid>
  </Grid>
 </Border>
</Window>







"@
[xml]$xaml = $mainXamlStr
$reader = New-Object System.Xml.XmlNodeReader $xaml
$window = [Windows.Markup.XamlReader]::Load($reader)
$BrandLogoImage = $window.FindName("BrandLogoImage")
if($BrandLogoImage -and $Global:HeaderLogoBase64){
    try {
        $headerLogoBytes = [Convert]::FromBase64String($Global:HeaderLogoBase64)
        $headerLogoStream = New-Object System.IO.MemoryStream(,$headerLogoBytes)
        $headerLogoBitmap = New-Object System.Windows.Media.Imaging.BitmapImage
        $headerLogoBitmap.BeginInit()
        $headerLogoBitmap.CacheOption = [System.Windows.Media.Imaging.BitmapCacheOption]::OnLoad
        $headerLogoBitmap.StreamSource = $headerLogoStream
        $headerLogoBitmap.EndInit()
        $headerLogoBitmap.Freeze()
        $BrandLogoImage.Source = $headerLogoBitmap
        $headerLogoStream.Dispose()
    } catch { }
}

$MainBgCanvas = $window.FindName("MainBgCanvas")
$RootGrid = $window.FindName("RootGrid")
$RootClipGeom = $window.FindName("RootClipGeom")
$MainGifBackground = $window.FindName("MainGifBackground")
try {
    
    $MainGifBackground.Visibility=[System.Windows.Visibility]::Collapsed
    New-SplashAura -Canvas $MainBgCanvas -Width 1160 -Height 760 -CenterX 580 -CenterY 380 -ParticleCount 190 -Style $Global:GalaxyStyle
    Add-BackgroundParallax -TargetWindow $window -Canvas $MainBgCanvas -MaxOffset 22 -DurationX 20 -DurationY 16
} catch {}
$window.Add_ContentRendered({
    try {
        
    } catch {}
})
$SystemInfoPanel=$window.FindName("SystemInfoPanel")
$MainContentGrid=$window.FindName("MainContentGrid")
try {
    $SystemInfoPanel.Visibility="Visible"
    $SystemInfoPanel.Width=[double]::NaN
    $SystemInfoPanel.MinWidth=208
    $SystemInfoPanel.HorizontalAlignment="Stretch"
    $SystemInfoPanel.VerticalAlignment="Stretch"
} catch {}
try {
    
    $bgMotion = @(
        @{ Name="BgOrbA"; XFrom=-40; XTo=70; YFrom=18; YTo=-45; Duration=16; Delay=0.0; OpacityMin=0.018; OpacityMax=0.055 },
        @{ Name="BgOrbB"; XFrom=55; XTo=-85; YFrom=-20; YTo=65; Duration=21; Delay=3.5; OpacityMin=0.012; OpacityMax=0.040 },
        @{ Name="BgOrbC"; XFrom=-25; XTo=45; YFrom=35; YTo=-30; Duration=15; Delay=6.5; OpacityMin=0.010; OpacityMax=0.032 }
    )
    foreach($spec in $bgMotion){
        $child=$window.FindName($spec.Name)
        if($child){
            $translate=New-Object System.Windows.Media.TranslateTransform
            $child.RenderTransform=$translate
            $duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds([double]$spec.Duration))
            $easeX=New-Object System.Windows.Media.Animation.SineEase
            $easeX.EasingMode=[System.Windows.Media.Animation.EasingMode]::EaseInOut
            $easeY=New-Object System.Windows.Media.Animation.SineEase
            $easeY.EasingMode=[System.Windows.Media.Animation.EasingMode]::EaseInOut
            $easePulse=New-Object System.Windows.Media.Animation.SineEase
            $easePulse.EasingMode=[System.Windows.Media.Animation.EasingMode]::EaseInOut
            $begin=[TimeSpan]::FromSeconds([double]$spec.Delay)

            $moveX=New-Object System.Windows.Media.Animation.DoubleAnimation
            $moveX.From=[double]$spec.XFrom; $moveX.To=[double]$spec.XTo
            $moveX.Duration=$duration; $moveX.AutoReverse=$true; $moveX.EasingFunction=$easeX; $moveX.BeginTime=$begin; $moveX.FillBehavior=[System.Windows.Media.Animation.FillBehavior]::HoldEnd
            $moveX.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
            $translate.BeginAnimation([System.Windows.Media.TranslateTransform]::XProperty,$moveX)

            $moveY=New-Object System.Windows.Media.Animation.DoubleAnimation
            $moveY.From=[double]$spec.YFrom; $moveY.To=[double]$spec.YTo
            $moveY.Duration=$duration; $moveY.AutoReverse=$true; $moveY.EasingFunction=$easeY; $moveY.BeginTime=$begin; $moveY.FillBehavior=[System.Windows.Media.Animation.FillBehavior]::HoldEnd
            $moveY.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
            $translate.BeginAnimation([System.Windows.Media.TranslateTransform]::YProperty,$moveY)

            $pulse=New-Object System.Windows.Media.Animation.DoubleAnimation
            $pulse.From=[double]$spec.OpacityMin; $pulse.To=[double]$spec.OpacityMax
            $pulse.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromSeconds(([double]$spec.Duration)*0.60))
            $pulse.AutoReverse=$true; $pulse.EasingFunction=$easePulse; $pulse.BeginTime=$begin; $pulse.FillBehavior=[System.Windows.Media.Animation.FillBehavior]::HoldEnd
            $pulse.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
            $child.BeginAnimation([System.Windows.UIElement]::OpacityProperty,$pulse)
        }
    }
} catch {}
$MainLogoWatermark
try { if ($splashLogoBitmap) { $MainLogoWatermark.Source = $splashLogoBitmap } } catch {}
$TopBar=$window.FindName("TopBar")
$StatusText=$window.FindName("StatusText"); $StatusDotE=$window.FindName("StatusDotEllipse")
$BtnMin=$window.FindName("BtnMin"); $BtnMax=$window.FindName("BtnMax"); $BtnClose=$window.FindName("BtnClose")
$StagesPanel=$window.FindName("StagesPanel")
$ProgressFill=$window.FindName("ProgressFill"); $ProgressPct=$window.FindName("ProgressPercent")
$BtnRun=$window.FindName("BtnRun")
$BtnRamCleaner=$window.FindName("BtnRamCleaner")
$BtnClearCaches=$window.FindName("BtnClearCaches")
$BtnJunkCleaner=$window.FindName("BtnJunkCleaner")
$BtnCitizenFX=$window.FindName("BtnCitizenFX")
$NetPresetLan=$window.FindName("NetPresetLan"); $NetPresetWifi=$window.FindName("NetPresetWifi")
$BtnNetTwakes=$window.FindName("BtnNetTwakes")
$GpuPresetAmd=$window.FindName("GpuPresetAmd"); $GpuPresetNvidia=$window.FindName("GpuPresetNvidia")
$BtnPresetAllExceptGpuLan=$window.FindName("BtnPresetAllExceptGpuLan")
$BtnExit=$window.FindName("BtnExit")
