function Update-SystemInfoUi {
    try {
        $InfoOS.Text=$Global:SysInfo.OS; $InfoCPU.Text=$Global:SysInfo.CPU; $InfoGPU.Text=$Global:SysInfo.GPU
        $InfoNET.Text=$Global:SysInfo.NetType; $InfoRAM.Text=if([int]$Global:SysInfo.RAM -gt 0){"$($Global:SysInfo.RAM) GB"}{"Detecting..."}
        $InfoAdapter.Text=$Global:SysInfo.Adapter
        $maxW=$RamUsageFill.Parent.ActualWidth; if($maxW -le 0){$maxW=400}
        $pct=[int]$Global:SysInfo.RAMUsedPct; $RamUsageFill.Width=[math]::Max(0,($pct/100.0)*$maxW); $RamUsageText.Text="$pct%"
    } catch {}
}
Update-SystemInfoUi
$Global:SystemInfoTimer = New-Object System.Windows.Threading.DispatcherTimer
$Global:SystemInfoTimer.Interval = [TimeSpan]::FromMilliseconds(700)
$Global:SystemInfoTimer.Add_Tick({
    try {
        if(-not $Global:SystemInfoJob){ $Global:SystemInfoTimer.Stop(); return }
        if($Global:SystemInfoJob.State -in @("Completed","Failed","Stopped")){
            if($Global:SystemInfoJob.State -eq "Completed"){
                $result=Receive-Job -Job $Global:SystemInfoJob -ErrorAction SilentlyContinue | Select-Object -Last 1
                if($result){ $Global:SysInfo=$result; Update-SystemInfoUi }
            }
            Remove-Job -Job $Global:SystemInfoJob -Force -ErrorAction SilentlyContinue
            $Global:SystemInfoJob=$null; $Global:SystemInfoTimer.Stop()
        }
    } catch { try { $Global:SystemInfoTimer.Stop() } catch {} }
})
$Global:SystemInfoTimer.Start()

$window.Add_Loaded({
    
    $window.Opacity = 0
    $mainFadeIn = New-Object System.Windows.Media.Animation.DoubleAnimation
    $mainFadeIn.From = 0; $mainFadeIn.To = 1
    $mainFadeIn.Duration = New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(420))
    $mainFadeIn.EasingFunction = New-Object System.Windows.Media.Animation.SineEase
    $mainFadeIn.EasingFunction.EasingMode = [System.Windows.Media.Animation.EasingMode]::EaseInOut
    $window.BeginAnimation([System.Windows.UIElement]::OpacityProperty, $mainFadeIn)
    Update-SystemInfoUi
    $maxW=$RamUsageFill.Parent.ActualWidth; if($maxW -le 0){$maxW=400}
    $pct=$Global:SysInfo.RAMUsedPct; $RamUsageFill.Width=[math]::Max(0,($pct/100.0)*$maxW); $RamUsageText.Text="$pct%"
})
