$Global:LogLines=[System.Collections.Generic.List[string]]::new()
function Add-Log {
    param([string]$msg,[string]$color="#A0A0A0")
    [void]$Global:LogLines.Add($msg)
    try {
        $window.Dispatcher.Invoke([Action]{
            if($CurrentTask) { $CurrentTask.Text=$msg }; if($FooterNoticeText) { $FooterNoticeText.Text=$msg }
            if($LogBox -and $LogScrollV){
                $run=New-Object System.Windows.Documents.Run; $run.Text="> $msg`n"
                try{$run.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($color)}catch{}
                [void]$LogBox.Inlines.Add($run); $LogScrollV.ScrollToEnd()
            }
        })
    } catch {}
}
