$Global:ReviewTweakKeys = @(
    "BcdTimer","ADV_HPET","PWR_UltimatePlan","SYS_NoCoreParking","GM_HAGS","NET_ResetWinsock",
    "CLEAN_RemoveBloat","CLEAN_KillBackgroundProcs","CLEAN_DisableLauncherStartup",
    "SYS_PauseUpdates","CLEAN_NoTelemetry","CLEAN_NoWER","CLEAN_NoPrintSpooler",
    "NET_RemoteAssistanceOff","NET_NoAutoRootCertUpdate","NduDisable","NduDisable_WiFi",
    "NET_Ipv6Disable","NET_Ipv6Disable_WiFi","SYS_WidgetsOff","SYS_OneDriveSyncOff",
    "SVC_XboxBackground","TASK_Telemetry","DEF_FiveMExclusions","PRIVACY_AdvertisingId",
    "PRIVACY_ActivityHistory","STARTUP_BackgroundApps","USB_PowerSuspendOff",
    "INPUT_KeyboardRepeat","INPUT_RawMouse","CP_VisualEffects","BLOAT_ProvisionedApps",
    "GPE_GamePolicy","NET_ECN","NET_FastOpen","NET_TaskOffload","NET_TCPParameters",
    "BCD_UsePlatformClockOff","BCD_DisableDynamicTick","BCD_TscSyncPolicy","SYS_MMCSSSystemResponsiveness",
    "NET_NicBuffers","NET_FlowControlStable","FIVEM_HighPerformanceGPU","FIVEM_SessionServices",
    "SSD_NtfsLastAccess","NET_LanJumboFrame","NET_LanInterruptModeration","NET_WifiPowerSaveMode",
    "NET_WifiRoamingAggressiveness","NET_DnsFast","NET_DnsFast_WiFi"
)

foreach($advancedKey in $Global:ExtendedTweakKeys){ if($Global:ReviewTweakKeys -notcontains $advancedKey){ $Global:ReviewTweakKeys += $advancedKey } }
function Get-TweakSafetyProfile {
    param($Tweak)
    $key=[string]$Tweak.Key
    if($Global:ReviewTweakKeys -contains $key){
        $note="Review before apply"
        if($key -in @("CLEAN_RemoveBloat","CLEAN_KillBackgroundProcs","CLEAN_DisableLauncherStartup","BLOAT_ProvisionedApps")){ $note="May change or remove apps" }
        elseif($key -in @("BcdTimer","ADV_HPET","PWR_UltimatePlan","SYS_NoCoreParking","GM_HAGS")){ $note="May require restart" }
        elseif($key -match "PRIVACY|Telemetry|OneDrive|Widgets|PauseUpdates"){ $note="Changes Windows behavior" }
        return @{ Label="REVIEW"; Note=$note; Foreground="#BDBDBD"; Background="#242424"; Border="#8A8A8A" }
    }
    return @{ Label="RECOMMENDED"; Note="Low-risk selection"; Foreground="#FFFFFF"; Background="#D91616"; Border="#FF5A5A" }
}
function Get-LighterRgb($rgb, [double]$amt=0.55) {
    $r=[math]::Round($rgb[0] + (255-$rgb[0])*$amt); $g=[math]::Round($rgb[1] + (255-$rgb[1])*$amt); $b=[math]::Round($rgb[2] + (255-$rgb[2])*$amt)
    return @([byte]$r,[byte]$g,[byte]$b)
}
function New-IconBrush($rgb) {
    $light=Get-LighterRgb $rgb 0.55
    $brush=New-Object System.Windows.Media.LinearGradientBrush
    $brush.StartPoint=New-Object System.Windows.Point(0,0); $brush.EndPoint=New-Object System.Windows.Point(1,1)
    [void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.Color]::FromRgb($light[0],$light[1],$light[2]),0)))
    [void]$brush.GradientStops.Add((New-Object System.Windows.Media.GradientStop([System.Windows.Media.Color]::FromRgb($rgb[0],$rgb[1],$rgb[2]),1)))
    return $brush
}
function New-CategoryIconVisual([string]$GroupName, $AccentRgb, [bool]$IsActive) {
    $fgRgb= if($IsActive){$AccentRgb} else {@(0x9C,0xA3,0xAF)}
    $brush=New-IconBrush $fgRgb
    $canvas=New-Object System.Windows.Controls.Canvas; $canvas.Width=24; $canvas.Height=24
    switch($GroupName){
        "LAN NETWORK" {
            foreach($pt in @(@(12,7,6,16),@(12,7,18,16))){
                $l=New-Object System.Windows.Shapes.Line; $l.X1=$pt[0];$l.Y1=$pt[1];$l.X2=$pt[2];$l.Y2=$pt[3]
                $l.Stroke=$brush; $l.StrokeThickness=1.6; $l.StrokeStartLineCap="Round"; $l.StrokeEndLineCap="Round"
                $canvas.Children.Add($l)|Out-Null
            }
            foreach($n in @(@(9.8,2.8),@(3.8,15.8),@(15.8,15.8))){
                $e=New-Object System.Windows.Shapes.Ellipse; $e.Width=4.4; $e.Height=4.4; $e.Fill=$brush
                [System.Windows.Controls.Canvas]::SetLeft($e,$n[0]); [System.Windows.Controls.Canvas]::SetTop($e,$n[1])
                $canvas.Children.Add($e)|Out-Null
            }
        }
        "WI-FI NETWORK" {
            foreach($bar in @(@(3,14,6),@(10,9,11),@(17,4,16))){
                $r=New-Object System.Windows.Shapes.Rectangle; $r.Width=4; $r.Height=$bar[2]; $r.RadiusX=1; $r.RadiusY=1; $r.Fill=$brush
                [System.Windows.Controls.Canvas]::SetLeft($r,$bar[0]); [System.Windows.Controls.Canvas]::SetTop($r,$bar[1])
                $canvas.Children.Add($r)|Out-Null
            }
        }
        "INPUT LAG" {
            $body=New-Object System.Windows.Shapes.Rectangle; $body.Width=20; $body.Height=13; $body.RadiusX=3; $body.RadiusY=3; $body.Fill=$brush; $body.Opacity=0.28
            [System.Windows.Controls.Canvas]::SetLeft($body,2); [System.Windows.Controls.Canvas]::SetTop($body,6)
            $canvas.Children.Add($body)|Out-Null
            $keys=@(@(4.5,8.5),@(7.7,8.5),@(10.9,8.5),@(14.1,8.5),@(17.3,8.5),@(4.5,11.7),@(7.7,11.7),@(10.9,11.7),@(14.1,11.7),@(17.3,11.7),@(6,14.9),@(9.5,14.9),@(14.5,14.9),@(18,14.9))
            foreach($p in $keys){
                $k=New-Object System.Windows.Shapes.Rectangle; $k.Width=2.2; $k.Height=2.2; $k.RadiusX=0.5; $k.RadiusY=0.5; $k.Fill=$brush
                [System.Windows.Controls.Canvas]::SetLeft($k,$p[0]); [System.Windows.Controls.Canvas]::SetTop($k,$p[1])
                $canvas.Children.Add($k)|Out-Null
            }
        }
        "SYSTEM & TIMING" {
            $arc=New-Object System.Windows.Shapes.Path; $arc.Data=[System.Windows.Media.Geometry]::Parse("M4,17 A8,8 0 1 1 20,17")
            $arc.Stroke=$brush; $arc.StrokeThickness=2; $arc.StrokeStartLineCap="Round"; $arc.StrokeEndLineCap="Round"
            $canvas.Children.Add($arc)|Out-Null
            $needle=New-Object System.Windows.Shapes.Line; $needle.X1=12; $needle.Y1=17; $needle.X2=16; $needle.Y2=10
            $needle.Stroke=$brush; $needle.StrokeThickness=1.8; $needle.StrokeStartLineCap="Round"; $needle.StrokeEndLineCap="Round"
            $canvas.Children.Add($needle)|Out-Null
            $hub=New-Object System.Windows.Shapes.Ellipse; $hub.Width=3; $hub.Height=3; $hub.Fill=$brush
            [System.Windows.Controls.Canvas]::SetLeft($hub,10.5); [System.Windows.Controls.Canvas]::SetTop($hub,15.5)
            $canvas.Children.Add($hub)|Out-Null
        }
        "GAMING & MEMORY" {
            $bodyGeom=[System.Windows.Media.Geometry]::Parse("M6,9 L18,9 A4,4 0 0 1 22,13 L22,15 A3,3 0 0 1 17,17.5 L15,15 L9,15 L7,17.5 A3,3 0 0 1 2,15 L2,13 A4,4 0 0 1 6,9 Z")
            $bodyPath=New-Object System.Windows.Shapes.Path; $bodyPath.Data=$bodyGeom; $bodyPath.Fill=$brush
            $canvas.Children.Add($bodyPath)|Out-Null
            $dpadV=New-Object System.Windows.Shapes.Rectangle; $dpadV.Width=1.6; $dpadV.Height=5; $dpadV.Fill="#111111"
            [System.Windows.Controls.Canvas]::SetLeft($dpadV,7.2); [System.Windows.Controls.Canvas]::SetTop($dpadV,10.5)
            $dpadH=New-Object System.Windows.Shapes.Rectangle; $dpadH.Width=5; $dpadH.Height=1.6; $dpadH.Fill="#111111"
            [System.Windows.Controls.Canvas]::SetLeft($dpadH,5.5); [System.Windows.Controls.Canvas]::SetTop($dpadH,12.2)
            $canvas.Children.Add($dpadV)|Out-Null; $canvas.Children.Add($dpadH)|Out-Null
            foreach($b in @(@(16.5,10.5),@(18.5,12.5))){
                $btn=New-Object System.Windows.Shapes.Ellipse; $btn.Width=2; $btn.Height=2; $btn.Fill="#111111"
                [System.Windows.Controls.Canvas]::SetLeft($btn,$b[0]); [System.Windows.Controls.Canvas]::SetTop($btn,$b[1])
                $canvas.Children.Add($btn)|Out-Null
            }
        }
        "INTERFACE & CLEANUP" {
            $star=New-Object System.Windows.Shapes.Path; $star.Data=[System.Windows.Media.Geometry]::Parse("M12,2 L14,9 L21,11 L14,13 L12,20 L10,13 L3,11 L10,9 Z")
            $star.Fill=$brush
            $canvas.Children.Add($star)|Out-Null
        }
        {$_ -eq "NVIDIA GPU" -or $_ -eq "AMD GPU"} {
            $chip=New-Object System.Windows.Shapes.Rectangle; $chip.Width=16; $chip.Height=12; $chip.RadiusX=2; $chip.RadiusY=2; $chip.Fill=$brush
            [System.Windows.Controls.Canvas]::SetLeft($chip,4); [System.Windows.Controls.Canvas]::SetTop($chip,6)
            $canvas.Children.Add($chip)|Out-Null
            $fan=New-Object System.Windows.Shapes.Ellipse; $fan.Width=6; $fan.Height=6; $fan.Fill="#111111"; $fan.Opacity=0.55
            [System.Windows.Controls.Canvas]::SetLeft($fan,9); [System.Windows.Controls.Canvas]::SetTop($fan,9)
            $canvas.Children.Add($fan)|Out-Null
            foreach($p in @(@(6,3,6,6),@(10,3,10,6),@(14,3,14,6),@(6,18,6,15),@(10,18,10,15),@(14,18,14,15))){
                $pin=New-Object System.Windows.Shapes.Line; $pin.X1=$p[0]; $pin.Y1=$p[1]; $pin.X2=$p[2]; $pin.Y2=$p[3]
                $pin.Stroke=$brush; $pin.StrokeThickness=1.4
                $canvas.Children.Add($pin)|Out-Null
            }
        }
        "GPU & CACHE" {
            $lid=New-Object System.Windows.Shapes.Rectangle; $lid.Width=14; $lid.Height=2; $lid.RadiusX=1; $lid.RadiusY=1; $lid.Fill=$brush
            [System.Windows.Controls.Canvas]::SetLeft($lid,5); [System.Windows.Controls.Canvas]::SetTop($lid,6)
            $canvas.Children.Add($lid)|Out-Null
            $handle=New-Object System.Windows.Shapes.Rectangle; $handle.Width=5; $handle.Height=2.5; $handle.RadiusX=1; $handle.RadiusY=1; $handle.Fill=$brush
            [System.Windows.Controls.Canvas]::SetLeft($handle,9.5); [System.Windows.Controls.Canvas]::SetTop($handle,3.2)
            $canvas.Children.Add($handle)|Out-Null
            $bin=New-Object System.Windows.Shapes.Path; $bin.Data=[System.Windows.Media.Geometry]::Parse("M6.5,9 L17.5,9 L16.5,20 A2,2 0 0 1 14.5,22 L9.5,22 A2,2 0 0 1 7.5,20 Z")
            $bin.Fill=$brush
            $canvas.Children.Add($bin)|Out-Null
        }
        default {
            $dot=New-Object System.Windows.Shapes.Ellipse; $dot.Width=10; $dot.Height=10; $dot.Fill=$brush
            [System.Windows.Controls.Canvas]::SetLeft($dot,7); [System.Windows.Controls.Canvas]::SetTop($dot,7)
            $canvas.Children.Add($dot)|Out-Null
        }
    }
    if($canvas.Children.Count -eq 0){
        $outer=New-Object System.Windows.Shapes.Ellipse; $outer.Width=16; $outer.Height=16; $outer.Stroke=$brush; $outer.StrokeThickness=1.6
        [System.Windows.Controls.Canvas]::SetLeft($outer,4); [System.Windows.Controls.Canvas]::SetTop($outer,4); $canvas.Children.Add($outer)|Out-Null
        $dot=New-Object System.Windows.Shapes.Ellipse; $dot.Width=4; $dot.Height=4; $dot.Fill=$brush
        [System.Windows.Controls.Canvas]::SetLeft($dot,10); [System.Windows.Controls.Canvas]::SetTop($dot,10); $canvas.Children.Add($dot)|Out-Null
    }
    $vb=New-Object System.Windows.Controls.Viewbox; $vb.Width=16; $vb.Height=16; $vb.Stretch="Uniform"; $vb.Child=$canvas
    $shadow=New-Object System.Windows.Media.Effects.DropShadowEffect
    $shadow.Color=[System.Windows.Media.Color]::FromRgb($fgRgb[0],$fgRgb[1],$fgRgb[2]); $shadow.BlurRadius=5; $shadow.ShadowDepth=0; $shadow.Opacity=0.55
    $vb.Effect=$shadow
    return $vb
}
function Build-StageCards {
    param([string]$filter="")
    $StagesPanel.Children.Clear()
    $groupOrder=@("LAN NETWORK","WI-FI NETWORK","INPUT LAG","MOUSE & KEYBOARD","SYSTEM & TIMING","CP OPTIMIZER","GAMING & MEMORY","AUDIO","STORAGE / SSD","SERVICES","SCHEDULED TASKS","DEFENDER","TELEMETRY & PRIVACY","STARTUP OPTIMIZATION","USB & DEVICES","INTERFACE & CLEANUP","BLOATWARE REMOVAL","GPEDIT / GAMING","NVIDIA GPU","AMD GPU","GPU & CACHE")
    if ($Global:DetectedGpuVendor -eq "NVIDIA") { $groupOrder = $groupOrder | Where-Object { $_ -ne "AMD GPU" } }
    elseif ($Global:DetectedGpuVendor -eq "AMD") { $groupOrder = $groupOrder | Where-Object { $_ -ne "NVIDIA GPU" } }
    $number=0
    foreach ($groupName in $groupOrder) {
        $catMeta=$Global:CategoryInfo | Where-Object { $_.Group -eq $groupName }
        $itemsInGroup=@($Global:TweakInfo | Where-Object { $_.Group -eq $groupName })
        $matches= -not $filter -or $groupName -like "*$filter*" -or ($itemsInGroup | Where-Object { $_.Title -like "*$filter*" -or $_.Category -like "*$filter*" })
        if(-not $matches){continue}
        $number++
        $isActive = ($Global:ActiveCategory -eq $groupName)
        $accentColor= if($catMeta.Accent){$catMeta.Accent}else{@(0x9B,0x5D,0xE5)}
        $activeCount=@($itemsInGroup | Where-Object { $Global:TweakToggles[$_.Key] -eq $true }).Count
        $totalCount=$itemsInGroup.Count
        $card=New-Object System.Windows.Controls.Border
        $card.CornerRadius="8"; $card.BorderThickness="1"; $card.Margin="0,0,0,6"; $card.Padding="8,8"; $card.Cursor="Hand"
        if($isActive){$bgColor=@(0x172231,0x1B202D);$borderColor=$accentColor}else{$bgColor=@(0x111722,0x121925);$borderColor=@(0x202A38)}
        $card.Background=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb($bgColor[0],$bgColor[1],$bgColor[2]))
        $card.BorderBrush=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb($borderColor[0],$borderColor[1],$borderColor[2]))
        $grid=New-Object System.Windows.Controls.Grid
        foreach($width in @("Auto","*","Auto","Auto")){ $col=New-Object System.Windows.Controls.ColumnDefinition; $col.Width=$width; [void]$grid.ColumnDefinitions.Add($col) }
        $badge=New-Object System.Windows.Controls.Border; $badge.Width=25; $badge.Height=25; $badge.CornerRadius=7; $badge.Margin="0,0,9,0"; $badge.VerticalAlignment="Center"; $badge.Background=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0x1C,0x1C,0x1C)); $badge.BorderBrush=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb($accentColor[0],$accentColor[1],$accentColor[2])); $badge.BorderThickness=1
        $badgeText=New-Object System.Windows.Controls.TextBlock; $badgeText.Text=("{0:00}" -f $number); $badgeText.Foreground=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb($accentColor[0],$accentColor[1],$accentColor[2])); $badgeText.FontSize=7.5; $badgeText.FontWeight="Bold"; $badgeText.HorizontalAlignment="Center"; $badgeText.VerticalAlignment="Center"; $badge.Child=$badgeText; [System.Windows.Controls.Grid]::SetColumn($badge,0)
        $sp=New-Object System.Windows.Controls.StackPanel; [System.Windows.Controls.Grid]::SetColumn($sp,1)
        $title=New-Object System.Windows.Controls.TextBlock; $title.Text=$groupName; $title.FontSize=9.2; $title.FontWeight="SemiBold"; $title.Foreground=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0xF1,0xF1,0xF1)); $title.TextTrimming="CharacterEllipsis"
        $desc=New-Object System.Windows.Controls.TextBlock; $desc.Text=$catMeta.Desc; $desc.FontSize=7.2; $desc.TextWrapping="Wrap"; $desc.MaxHeight=22; $desc.Margin="0,2,0,0"; $desc.Foreground=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0x7B,0x7B,0x7B))
        [void]$sp.Children.Add($title); [void]$sp.Children.Add($desc)
        $countBd=New-Object System.Windows.Controls.Border; $countBd.CornerRadius=6; $countBd.Padding="6,3"; $countBd.Margin="6,0,6,0"; $countBd.VerticalAlignment="Center"; $countBd.Background=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0x20,0x20,0x20)); $countBd.BorderBrush=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0x2A,0x2A,0x2A)); $countBd.BorderThickness=1
        $countColor=if($activeCount -gt 0){"#FFFFFF"}else{"#858585"}; $countText=New-Object System.Windows.Controls.TextBlock; $countText.Text=("{0}/{1}" -f $activeCount,$totalCount); $countText.FontSize=7.5; $countText.FontWeight="Bold"; $countText.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($countColor); $countBd.Child=$countText; [System.Windows.Controls.Grid]::SetColumn($countBd,2)
        $arrowColor=if($isActive){"#FFFFFF"}else{"#858585"}; $arrow=New-Object System.Windows.Controls.TextBlock; $arrow.Text="›"; $arrow.FontSize=16; $arrow.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString($arrowColor); $arrow.VerticalAlignment="Center"; [System.Windows.Controls.Grid]::SetColumn($arrow,3)
        [void]$grid.Children.Add($badge); [void]$grid.Children.Add($sp); [void]$grid.Children.Add($countBd); [void]$grid.Children.Add($arrow); $card.Child=$grid
        $capturedGroup=$groupName
        $card.Add_MouseLeftButtonUp({ Show-CategoryDetail $capturedGroup }.GetNewClosure())
        $StagesPanel.Children.Add($card)|Out-Null
    }
}
function Get-ViewGroups {
    param([string]$ViewName)
    switch($ViewName){
        "__NETWORK__" { return @("LAN NETWORK","WI-FI NETWORK","NETWORK TOOLS") }
        "__NET__"     { return @("LAN NETWORK") }
        "__LAN__"     { return @("LAN NETWORK") }
        "__WIFI__"    { return @("WI-FI NETWORK") }
        "__FIVEM__"      { return @("FIVEM PROFILE","GAMING & MEMORY") }
        "__TOOLS_ALL__"  { return @("LAN NETWORK","WI-FI NETWORK","NETWORK TOOLS","INPUT LAG","MOUSE & KEYBOARD","SYSTEM & TIMING","CP OPTIMIZER","AUDIO","STORAGE / SSD","SERVICES","SCHEDULED TASKS","DEFENDER","TELEMETRY & PRIVACY","STARTUP OPTIMIZATION","USB & DEVICES","INTERFACE & CLEANUP","BLOATWARE REMOVAL","GPEDIT / GAMING") }
        "__TOOLS__"      { return @("LAN NETWORK","WI-FI NETWORK","NETWORK TOOLS","INPUT LAG","MOUSE & KEYBOARD","SYSTEM & TIMING","CP OPTIMIZER","AUDIO","STORAGE / SSD","SERVICES","SCHEDULED TASKS","DEFENDER","TELEMETRY & PRIVACY","STARTUP OPTIMIZATION","USB & DEVICES","INTERFACE & CLEANUP","BLOATWARE REMOVAL","GPEDIT / GAMING") }
        "__RESHADE__" { return @("GPU & CACHE") }
        "__SETTINGS__" { return @() }
        "__INPUT__"   { return @("INPUT LAG","MOUSE & KEYBOARD") }
        "__SYSTEM__"  { return @("SYSTEM & TIMING","CP OPTIMIZER","SERVICES","SCHEDULED TASKS","INTERFACE & CLEANUP","TELEMETRY & PRIVACY","STARTUP OPTIMIZATION") }
        "__ALL__"     {
            $groups = New-Object System.Collections.Generic.List[string]
            foreach($entry in @($Global:TweakInfo)){
                $group = [string]$entry.Group
                if($group -and -not $groups.Contains($group)){ [void]$groups.Add($group) }
            }
            return @($groups)
        }
        default       { return @($ViewName) }
    }
}
function Get-ViewTitle {
    param([string]$ViewName)
    switch($ViewName){
        "__NETWORK__" { return "NET TWEAKS  /  LAN + WI-FI" }
        "__NET__"     { return "LAN SETTINGS" }
        "__LAN__"     { return "LAN SETTINGS" }
        "__WIFI__"    { return "WI-FI SETTINGS" }
        "__FIVEM__"      { return "FIVEM SETTINGS" }
        "__TOOLS_ALL__"  { return "ALL TOOLS" }
        "__TOOLS__"      { return "ALL TOOLS" }
        "__RESHADE__" { return "RESHADE / SHADERS" }
        "__SETTINGS__" { return "SETTINGS / PREFERENCES" }
        "__INPUT__"   { return "INPUT SETTINGS" }
        "__SYSTEM__"  { return "SYSTEM SETTINGS" }
        "__ALL__"     { return "ALL SETTINGS" }
        default       { return $ViewName }
    }
}
function Get-ViewDescription {
    param([string]$ViewName)
    switch($ViewName){
        "__NETWORK__" { return "LAN, Wi-Fi and Network Adapter Optimizer controls in one place." }
        "__NET__"     { return "Legacy alias for LAN settings." }
        "__LAN__"     { return "Wired Ethernet and LAN-specific controls." }
        "__WIFI__"    { return "Wireless adapter and Wi-Fi-specific controls." }
        "__FIVEM__"      { return "FiveM process, priority, affinity and gaming performance controls." }
        "__TOOLS_ALL__"  { return "All TOOLS categories except the standalone FIVEM and RESHADE modules." }
        "__TOOLS__"      { return "All TOOLS categories except the standalone FIVEM and RESHADE modules." }
        "__RESHADE__" { return "ReShade and shader-cache controls for a cleaner visual profile." }
        "__SETTINGS__" { return "Visual preferences, motion, safe defaults, and window behavior." }
        "__INPUT__"   { return "Mouse and keyboard controls for consistent response while playing." }
        "__SYSTEM__"  { return "System, services, cleanup, and timing controls kept in one simple view." }
        "__ALL__"     { return "Review the available switches, then enable only the changes you understand." }
        default       { return "Tune the selected module." }
    }
}
function Update-ActiveTweakCounts {
    param([string]$GroupName=$Global:ActiveCategory)
    try {
        $all=@($Global:TweakInfo)
        $active=@($all | Where-Object { $Global:TweakToggles[$_.Key] -eq $true })
        if($ActiveTweakCount){ $ActiveTweakCount.Text=("{0} ACTIVE" -f $active.Count) }
        if($GroupName -and $CatOverlayCount){
            $viewGroups=@(Get-ViewGroups $GroupName)
            $groupItems=@($all | Where-Object { $_.Group -in $viewGroups })
            $groupActive=@($groupItems | Where-Object { $Global:TweakToggles[$_.Key] -eq $true })
            $CatOverlayCount.Text=("{0} / {1} ACTIVE" -f $groupActive.Count,$groupItems.Count)
        }
    } catch {}
}
function Set-CategoryToggles {
    param([string]$GroupName,[bool]$Enabled)
    try {
        $viewGroups=@(Get-ViewGroups $GroupName)
        foreach($t in @($Global:TweakInfo | Where-Object { $_.Group -in $viewGroups })) { $Global:TweakToggles[$t.Key]=$Enabled }
        $label=if($Enabled){"enabled"}else{"disabled"}
        $color=if($Enabled){"#FFFFFF"}else{"#A1A1A1"}
        Add-Log ((Get-ViewTitle $GroupName) + ": all switches " + $label) $color
        Save-TweakState
        Update-ActiveTweakCounts -GroupName $GroupName
        Show-CategoryDetail $GroupName
    } catch {}
}



