            $targetCardSubtitle.FontSize=7
            $targetCardSubtitle.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#A8A8A8")
            $targetCardSubtitle.HorizontalAlignment="Center"
            [void]$targetCardContent.Children.Add($targetCardTitle)
            [void]$targetCardContent.Children.Add($targetCardSubtitle)
            $targetCard.Content=$targetCardContent
            [void]$targetCards.Add($targetCard)
            $mode=$targetOption.Mode
            $targetCard.Add_Click({$targetMode.Value=$mode;foreach($card in $targetCards){if($card.Tag -eq $targetMode.Value){$card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#2A2A2A");$card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#E0E0E0")}else{$card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#151515");$card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#555555")}}}.GetNewClosure())
            [System.Windows.Controls.Grid]::SetColumn($targetCard,($(if($mode -eq "LAN"){0}else{2})))
            [void]$targetGrid.Children.Add($targetCard)
        }
        foreach($card in $targetCards){if($card.Tag -eq $targetMode.Value){$card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#2A2A2A");$card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#E0E0E0")}else{$card.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#151515");$card.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#555555")}}
        [void]$stack.Children.Add($targetGrid)

        $providerLabel=New-Object System.Windows.Controls.TextBlock
        $providerLabel.Text="DNS PROVIDER PRESETS"
        $providerLabel.FontSize=8
        $providerLabel.FontWeight="Black"
        $providerLabel.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#BDBDBD")
        [void]$stack.Children.Add($providerLabel)
        $providerGrid=New-Object System.Windows.Controls.Grid
        $providerGrid.Margin="0,5,0,14"
        foreach($i in 0..4){$c=New-Object System.Windows.Controls.ColumnDefinition;if($i -in @(1,3)){$c.Width=[System.Windows.GridLength]::new(8)}else{$c.Width=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)};[void]$providerGrid.ColumnDefinitions.Add($c)}
        $primaryBox=New-Object System.Windows.Controls.TextBox
        $primaryBox.Height=40; $primaryBox.Margin="0,0,0,0"; $primaryBox.FontFamily="Consolas"; $primaryBox.FontSize=16; $primaryBox.FontWeight="SemiBold"; $primaryBox.HorizontalContentAlignment="Center"; $primaryBox.VerticalContentAlignment="Center"; $primaryBox.TextAlignment="Center"; $primaryBox.Padding="0"; $primaryBox.MaxLength=15; $primaryBox.Foreground=[System.Windows.Media.Brushes]::White; $primaryBox.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#191919"); $primaryBox.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#606060")
        $secondaryBox=New-Object System.Windows.Controls.TextBox
        $secondaryBox.Height=40; $secondaryBox.FontFamily="Consolas"; $secondaryBox.FontSize=16; $secondaryBox.FontWeight="SemiBold"; $secondaryBox.HorizontalContentAlignment="Center"; $secondaryBox.VerticalContentAlignment="Center"; $secondaryBox.TextAlignment="Center"; $secondaryBox.Padding="0"; $secondaryBox.MaxLength=15; $secondaryBox.Foreground=[System.Windows.Media.Brushes]::White; $secondaryBox.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#191919"); $secondaryBox.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#606060")
        $presets=@(
            [pscustomobject]@{Name="GOOGLE";Primary="8.8.8.8";Secondary="8.8.4.4"},
            [pscustomobject]@{Name="CLOUDFLARE";Primary="1.1.1.1";Secondary="1.0.0.1"},
            [pscustomobject]@{Name="QUAD9";Primary="9.9.9.9";Secondary="149.112.112.112"}
        )
        for($presetIndex=0;$presetIndex -lt $presets.Count;$presetIndex++){
            $preset=$presets[$presetIndex]
            $presetButton=New-Object System.Windows.Controls.Button
            $presetButton.Content=$preset.Name
            $presetButton.Height=34
            $presetButton.Style=$window.Resources["QuietButton"]
            $presetButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#1B1B1B")
            $presetButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#666666")
            $presetButton.Foreground=[System.Windows.Media.Brushes]::White
            $presetButton.FontSize=8
            $presetButton.FontWeight="Black"
            $presetButton.Cursor="Hand"
            $p=[string]$preset.Primary; $s=[string]$preset.Secondary
            $presetButton.Add_Click({$primaryBox.Text=$p;$secondaryBox.Text=$s}.GetNewClosure())
            [System.Windows.Controls.Grid]::SetColumn($presetButton,$presetIndex*2)
            [void]$providerGrid.Children.Add($presetButton)
        }
        [void]$stack.Children.Add($providerGrid)
        $customGrid=New-Object System.Windows.Controls.Grid
        foreach($i in 0..2){$c=New-Object System.Windows.Controls.ColumnDefinition;if($i -eq 1){$c.Width=[System.Windows.GridLength]::new(10)}else{$c.Width=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)};[void]$customGrid.ColumnDefinitions.Add($c)}
        [System.Windows.Controls.Grid]::SetColumn($primaryBox,0);[System.Windows.Controls.Grid]::SetColumn($secondaryBox,2)
        [void]$customGrid.Children.Add($primaryBox);[void]$customGrid.Children.Add($secondaryBox)
        [void]$stack.Children.Add($customGrid)
        $dnsLabelsGrid=New-Object System.Windows.Controls.Grid
        $dnsLabelsGrid.Margin="0,6,0,18"
        foreach($i in 0..2){$c=New-Object System.Windows.Controls.ColumnDefinition;if($i -eq 1){$c.Width=[System.Windows.GridLength]::new(10)}else{$c.Width=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)};[void]$dnsLabelsGrid.ColumnDefinitions.Add($c)}
        $primaryLabel=New-Object System.Windows.Controls.TextBlock
        $primaryLabel.Text="PRIMARY DNS"
        $primaryLabel.FontFamily="Segoe UI"
        $primaryLabel.FontSize=8
        $primaryLabel.FontWeight="Black"
        $primaryLabel.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#BDBDBD")
        $primaryLabel.HorizontalAlignment="Center"
        $secondaryLabel=New-Object System.Windows.Controls.TextBlock
        $secondaryLabel.Text="SECONDARY DNS"
        $secondaryLabel.FontFamily="Segoe UI"
        $secondaryLabel.FontSize=8
        $secondaryLabel.FontWeight="Black"
        $secondaryLabel.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#BDBDBD")
        $secondaryLabel.HorizontalAlignment="Center"
        [System.Windows.Controls.Grid]::SetColumn($primaryLabel,0);[System.Windows.Controls.Grid]::SetColumn($secondaryLabel,2)
        [void]$dnsLabelsGrid.Children.Add($primaryLabel);[void]$dnsLabelsGrid.Children.Add($secondaryLabel)
        [void]$stack.Children.Add($dnsLabelsGrid)
        $actionGrid=New-Object System.Windows.Controls.Grid
        foreach($i in 0..2){$c=New-Object System.Windows.Controls.ColumnDefinition;if($i -eq 1){$c.Width=[System.Windows.GridLength]::new(10)}else{$c.Width=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)};[void]$actionGrid.ColumnDefinitions.Add($c)}
        $apply=New-Object System.Windows.Controls.Button
        $apply.Content="APPLY DNS"
        $apply.Height=42
        $apply.Style=$window.Resources["QuietButton"]
        $apply.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#254D3A")
        $apply.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#7AD6A4")
        $apply.Foreground=[System.Windows.Media.Brushes]::White
        $apply.FontWeight="Black"
        $apply.Cursor="Hand"
        $apply.Add_Click({
            try{
                $p=$primaryBox.Text.Trim();$s=$secondaryBox.Text.Trim()
                if(-not (Test-IsAdministrator)){throw "ต้องเปิดโปรแกรมด้วย Run as Administrator ก่อนจึงจะเปลี่ยนค่า DNS ได้"}
                if(-not (Get-Command Get-NetAdapter -ErrorAction SilentlyContinue)){throw "ไม่พบคำสั่ง Get-NetAdapter กรุณาใช้ Windows PowerShell/ระบบ Windows ที่รองรับ NetTCPIP"}
                try{$parsedPrimary=[System.Net.IPAddress]::Parse($p);$parsedSecondary=[System.Net.IPAddress]::Parse($s)}catch{throw "กรุณากรอก IPv4 DNS ให้ถูกต้อง เช่น 8.8.8.8"}
                if($parsedPrimary.AddressFamily -ne [System.Net.Sockets.AddressFamily]::InterNetwork -or $parsedSecondary.AddressFamily -ne [System.Net.Sockets.AddressFamily]::InterNetwork){throw "กรุณากรอก IPv4 DNS เท่านั้น เช่น 1.1.1.1"}
                $isWifi=([string]$targetMode.Value -eq "WI-FI")
                $wifiPattern="Wi[ -]?Fi|Wireless|802\.11"
                $adapters=@(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object {
                    if($_.Status -ne "Up"){return $false}
                    $identity=((([string]$_.Name)+" "+([string]$_.InterfaceDescription)))
                    if($isWifi){return ($identity -match $wifiPattern)}
                    return ($identity -notmatch $wifiPattern)
                })
                if($adapters.Count -eq 0){throw ("ไม่พบอะแดปเตอร์ {0} ที่กำลังเชื่อมต่ออยู่ กรุณาตรวจสอบสาย LAN/Wi‑Fi และเปิดโปรแกรมด้วยสิทธิ์ Administrator" -f $(if($isWifi){"Wi‑Fi"}else{"LAN"}))}
                foreach($adapter in $adapters){
                    $applied=$false
                    try{Set-DnsClientServerAddress -InterfaceIndex ([int]$adapter.IfIndex) -ServerAddresses @($p,$s) -ErrorAction Stop;$applied=$true}
                    catch{
                        Add-Log ("PowerShell DNS cmdlet failed on {0}; trying netsh fallback: {1}" -f $adapter.Name,$_.Exception.Message) "#A0A0A0"
                        $setPrimary=@(netsh interface ip set dns name="$($adapter.Name)" static $p primary 2>&1)
                        $primaryCode=[int]$LASTEXITCODE
                        $setSecondary=@(netsh interface ip add dns name="$($adapter.Name)" $s index=2 2>&1)
                        $secondaryCode=[int]$LASTEXITCODE
                        if($primaryCode -eq 0 -and $secondaryCode -eq 0){$applied=$true}
                        foreach($line in @($setPrimary+$setSecondary)){if(-not [string]::IsNullOrWhiteSpace([string]$line)){Add-Log ("[Custom DNS] " + [string]$line) "#A0A0A0"}}
                    }
                    if(-not $applied){throw ("ตั้งค่า DNS ให้ {0} ไม่สำเร็จ กรุณารันโปรแกรมแบบ Administrator" -f $adapter.Name)}
                    Add-Log ("Custom DNS applied to {0}: {1}, {2}" -f $adapter.Name,$p,$s) "#FFFFFF"
                }
                Set-CurrentTask ("Custom DNS applied: {0} / {1}" -f $p,$s)
                Show-TweakToast -Label "CUSTOM DNS" -Enabled $true -OverrideText ("CUSTOM DNS  /  {0} + {1}" -f $p,$s) -DurationMs 3200
                $dnsWindow.Close()
            }catch{[System.Windows.MessageBox]::Show(("ไม่สามารถใช้ Custom DNS ได้`n`n" + $_.Exception.Message),"CUSTOM DNS ERROR",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning)|Out-Null}
        }.GetNewClosure())
        $cancel=New-Object System.Windows.Controls.Button
        $cancel.Content="CANCEL";$cancel.Height=42;$cancel.Style=$window.Resources["QuietButton"];$cancel.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#161616");$cancel.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#555555");$cancel.Foreground=[System.Windows.Media.Brushes]::White;$cancel.FontWeight="Black";$cancel.Cursor="Hand";$cancel.Add_Click({$dnsWindow.Close()}.GetNewClosure())
        [System.Windows.Controls.Grid]::SetColumn($apply,0);[System.Windows.Controls.Grid]::SetColumn($cancel,2);[void]$actionGrid.Children.Add($apply);[void]$actionGrid.Children.Add($cancel);[void]$stack.Children.Add($actionGrid)
        $outer.Child=$stack;$dnsWindow.Content=$outer
        [void]$dnsWindow.ShowDialog()
    }catch{[System.Windows.MessageBox]::Show($_.Exception.Message,"CUSTOM DNS",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Error)|Out-Null}
}
function Show-CategoryDetail {
    param([string]$groupName,[string]$Filter="")
    $Global:ActiveCategory=$groupName
    
    
    
    if($Global:PowerPlanStatusTimer){ try{$Global:PowerPlanStatusTimer.Stop()}catch{}; $Global:PowerPlanStatusTimer=$null }
    if($Global:PowerPlanActivationPoller){ try{$Global:PowerPlanActivationPoller.Stop()}catch{}; $Global:PowerPlanActivationPoller=$null }
    if($Global:PowerPlanActivationJob){ try{if($Global:PowerPlanActivationJob.State -eq 'Running'){Stop-Job $Global:PowerPlanActivationJob -ErrorAction SilentlyContinue}; Remove-Job $Global:PowerPlanActivationJob -Force -ErrorAction SilentlyContinue}catch{}; $Global:PowerPlanActivationJob=$null }
    $Global:PowerPlanActionBusy=$false
    $CatOverlayTitle.Text=Get-ViewTitle $groupName
    $CatOverlayDesc.Text=Get-ViewDescription $groupName
    $viewGroups=@(Get-ViewGroups $groupName)
    if($groupName -eq "__ALL__"){
        $itemsInGroup=@($Global:TweakInfo)
    } else {
        $itemsBuffer=New-Object System.Collections.ArrayList
        foreach($viewGroup in $viewGroups){
            $bucket=$Global:TweakInfoByGroup[[string]$viewGroup]
            if($bucket){ foreach($item in $bucket){ [void]$itemsBuffer.Add($item) } }
        }
        $itemsInGroup=@($itemsBuffer)
    }
    if($Filter){ $itemsInGroup=@($itemsInGroup | Where-Object { $_.Title -like "*$Filter*" -or $_.Category -like "*$Filter*" -or $_.Desc -like "*$Filter*" }) }
    Update-ActiveTweakCounts -GroupName $groupName
    $CatOverlayItems.Children.Clear()
    if($CatOverlayActionsRow){$CatOverlayActionsRow.Visibility="Visible"}
    if($CatOverlayCount){$CatOverlayCount.Visibility="Visible"}
    if($CatOverlayEnableAll){$CatOverlayEnableAll.Visibility="Visible"}
    if($CatOverlayItemsScroll){$CatOverlayItemsScroll.VerticalContentAlignment="Top"}
    if($groupName -in @("__LAN__","__WIFI__")){
        if($CatOverlayItemsScroll){$CatOverlayItemsScroll.VerticalContentAlignment="Center";$CatOverlayItemsScroll.MinHeight=420}
        if($CatOverlayItems){$CatOverlayItems.HorizontalAlignment="Center";$CatOverlayItems.VerticalAlignment="Center"}
    } elseif($CatOverlayItems){$CatOverlayItems.HorizontalAlignment="Stretch";$CatOverlayItems.VerticalAlignment="Top"}

    
    if($groupName -eq "__NETWORK__"){
        if($CatOverlayItemsScroll){
            $CatOverlayItemsScroll.VerticalContentAlignment="Center"
            $CatOverlayItemsScroll.MinHeight=420
        }
        $CatOverlayDesc.Margin="14,0,0,8"
        if($CatOverlayActionsRow){$CatOverlayActionsRow.Visibility="Collapsed"}
        if($CatOverlayCount){$CatOverlayCount.Visibility="Collapsed"}
        if($CatOverlayEnableAll){$CatOverlayEnableAll.Visibility="Collapsed"}
        if($CatOverlayDisableAll){$CatOverlayDisableAll.Visibility="Collapsed"}

        $netPicker=New-Object System.Windows.Controls.StackPanel
        $netPicker.Orientation="Vertical"
        $netPicker.Width=640
        $netPicker.HorizontalAlignment="Center"
        $netPicker.VerticalAlignment="Center"
        $netPicker.Margin="0,0,0,0"
        $netPickerHint=New-Object System.Windows.Controls.TextBlock
        $netPickerHint.Text="SELECT CONNECTION TYPE"
        $netPickerHint.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#BDBDBD")
        $netPickerHint.FontSize=9
        $netPickerHint.FontWeight="Black"
        $netPickerHint.HorizontalAlignment="Center"
        $netPickerHint.Margin="0,0,0,6"
        [void]$netPicker.Children.Add($netPickerHint)

        $netPickerGrid=New-Object System.Windows.Controls.Grid
        $netPickerGrid.Width=640
        $netPickerGrid.HorizontalAlignment="Center"
        foreach($columnIndex in 0..2){
            $columnDefinition=New-Object System.Windows.Controls.ColumnDefinition
            if($columnIndex -eq 1){$columnDefinition.Width=[System.Windows.GridLength]::new(10)}else{$columnDefinition.Width=New-Object System.Windows.GridLength(1,[System.Windows.GridUnitType]::Star)}
            [void]$netPickerGrid.ColumnDefinitions.Add($columnDefinition)
        }

        $netButtons=@(
            [pscustomobject]@{Label="LAN"; View="__LAN__"; Hint="WIRED ETHERNET SETTINGS"},
            [pscustomobject]@{Label="WI-FI"; View="__WIFI__"; Hint="WIRELESS ADAPTER SETTINGS"}
        )
        for($netIndex=0;$netIndex -lt $netButtons.Count;$netIndex++){
            $netOption=$netButtons[$netIndex]
            $netButton=New-Object System.Windows.Controls.Button
            $netButton.Width=315
            $netButton.Height=126
            $netButton.Margin="0,0,0,6"
            $netButton.Padding="18,12"
            $netButton.Style=$window.Resources["QuietButton"]
            $netButton.Background=[System.Windows.Media.BrushConverter]::new().ConvertFromString((if($netOption.Label -eq "LAN"){"#1C1C1C"}else{"#151515"}))
            $netButton.BorderBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString((if($netOption.Label -eq "LAN"){"#C8C8C8"}else{"#8D8D8D"}))
            $netShadow=New-Object System.Windows.Media.Effects.DropShadowEffect
            $netShadow.Color=[System.Windows.Media.Color]::FromRgb(0xFF,0xFF,0xFF)
            $netShadow.BlurRadius=14
            $netShadow.ShadowDepth=0
            $netShadow.Opacity=0.10
            $netButton.Effect=$netShadow
            $netButton.BorderThickness=1.2
            $netButton.Foreground=[System.Windows.Media.Brushes]::White
            $netButton.HorizontalContentAlignment="Center"
            $netButton.VerticalContentAlignment="Center"
