                    if($confirm -ne [System.Windows.MessageBoxResult]::Yes){return}
                    switch($cacheAction){"Flush"{$ok=[bool](Run-FlushDns)};"Winsock"{$ok=[bool](Run-ResetWinsock)};"TcpIp"{$ok=[bool](Run-ResetTcpIp)};"Renew"{$ok=[bool](Run-ReleaseRenewIp)}}
