  <Border x:Name="PlanBorder" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="{TemplateBinding BorderThickness}" CornerRadius="8" Padding="10,0">
    <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
  </Border>
  <ControlTemplate.Triggers>
    <Trigger Property="IsMouseOver" Value="True">
      <Setter TargetName="PlanBorder" Property="Background" Value="#303030"/>
      <Setter TargetName="PlanBorder" Property="BorderBrush" Value="#E8E8E8"/>
