    <Trigger Property="IsPressed" Value="True">
      <Setter TargetName="PlanBorder" Property="Background" Value="#4A4A4A"/>
      <Setter TargetName="PlanBorder" Property="BorderBrush" Value="#FFFFFF"/>
    </Trigger>
    <Trigger Property="IsEnabled" Value="False"><Setter TargetName="PlanBorder" Property="Opacity" Value="0.42"/></Trigger>
  </ControlTemplate.Triggers>
</ControlTemplate>
'@
        $uncPlanButtonTemplate=[System.Windows.Markup.XamlReader]::Parse($uncPlanButtonTemplateXaml)
