function Set-PresetGlow {
    param($Border,[bool]$Selected,[string]$AccentColor,[string]$DefaultColor="#232323")
    if(-not $Border){ return }
    $bc = New-Object System.Windows.Media.BrushConverter
    if($Selected){
        $accent = $bc.ConvertFromString($AccentColor)
        $Border.BorderBrush = $accent
        $Border.BorderThickness = [System.Windows.Thickness]::new(1.6)
        if(-not ($Border.Effect -is [System.Windows.Media.Effects.DropShadowEffect])){
            $glow = New-Object System.Windows.Media.Effects.DropShadowEffect
            $glow.Color = $accent.Color; $glow.BlurRadius = 16; $glow.ShadowDepth = 0; $glow.Opacity = 0
            $Border.Effect = $glow
        }
        $Border.Effect.Color = $accent.Color
        $anim = New-Object System.Windows.Media.Animation.DoubleAnimation
        $anim.To = 0.85; $anim.Duration = [TimeSpan]::FromMilliseconds(200)
        $Border.Effect.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::OpacityProperty,$anim)
    } else {
        $Border.BorderBrush = $bc.ConvertFromString($DefaultColor)
        $Border.BorderThickness = [System.Windows.Thickness]::new(1)
        if($Border.Effect -is [System.Windows.Media.Effects.DropShadowEffect]){
            $glowEffect = $Border.Effect
            $anim = New-Object System.Windows.Media.Animation.DoubleAnimation
            $anim.To = 0; $anim.Duration = [TimeSpan]::FromMilliseconds(160)
            $capturedBorder = $Border
            $anim.Add_Completed({ $capturedBorder.Effect = $null }.GetNewClosure())
            $glowEffect.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::OpacityProperty,$anim)
        }
    }
}
function Set-NetPresetGlow {
    param([string]$Selected)
    if(-not $NetPresetLan -or -not $NetPresetWifi){ return }
    [void]$NetPresetLan.ApplyTemplate(); [void]$NetPresetWifi.ApplyTemplate()
    $lanBd = $NetPresetLan.Template.FindName("buttonBorder",$NetPresetLan)
    $wifiBd = $NetPresetWifi.Template.FindName("buttonBorder",$NetPresetWifi)
    Set-PresetGlow -Border $lanBd  -Selected ($Selected -eq "LAN NETWORK")   -AccentColor "#E0E0E0" -DefaultColor "#777777"
    Set-PresetGlow -Border $wifiBd -Selected ($Selected -eq "WI-FI NETWORK") -AccentColor "#BDBDBD" -DefaultColor "#777777"
}
function Set-ButtonSelectionGlow{
    param($Button,[bool]$Selected,[string]$AccentColor,[string]$DefaultColor="#515151",[string]$SelectedBackgroundColor="#303030")
    if(-not $Button){ return }
    $bc=New-Object System.Windows.Media.BrushConverter
    if($Selected){
        $accent=$bc.ConvertFromString($AccentColor)
        $Button.Background=$bc.ConvertFromString($SelectedBackgroundColor)
        $Button.Foreground=$bc.ConvertFromString("#FFFFFF")
        $Button.BorderBrush=$accent
        $Button.BorderThickness=[System.Windows.Thickness]::new(1.6)
        $glow=New-Object System.Windows.Media.Effects.DropShadowEffect
        $glow.Color=$accent.Color; $glow.BlurRadius=16; $glow.ShadowDepth=0; $glow.Opacity=0.72
        $Button.Effect=$glow
        $pulse=New-Object System.Windows.Media.Animation.DoubleAnimation
        $pulse.From=0.52; $pulse.To=0.90; $pulse.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(620))
        $pulse.AutoReverse=$true; $pulse.RepeatBehavior=[System.Windows.Media.Animation.RepeatBehavior]::Forever
        $glow.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::OpacityProperty,$pulse)
    } else {
        $Button.Background=$bc.ConvertFromString("#161616")
        $Button.Foreground=$bc.ConvertFromString("#F2F2F2")
        $Button.BorderBrush=$bc.ConvertFromString($DefaultColor)
        $Button.BorderThickness=[System.Windows.Thickness]::new(1)
        $Button.Effect=$null
    }
}
