function Update-PresetGlowConsistency {
    
    
    
    if($Global:ActiveNetPreset){
        $type=$Global:ActiveNetPreset
        $other="WI-FI NETWORK"; if($type -eq "WI-FI NETWORK"){ $other="LAN NETWORK" }
        $match=$true
        foreach($t in $Global:TweakInfo){
            
            
            if($t.Group -eq $type -and -not $Global:TweakToggles[$t.Key]){ $match=$false; break }
        }
        if($match){ Set-NetPresetGlow -Selected $type } else { Set-NetPresetGlow -Selected $null }
    } else { Set-NetPresetGlow -Selected $null }
    if($Global:ActiveGpuPreset){
        $vendor=$Global:ActiveGpuPreset
        $mine="AMD GPU"; $other="NVIDIA GPU"; if($vendor -eq "NVIDIA"){ $mine="NVIDIA GPU"; $other="AMD GPU" }
        $match=$true
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $mine -and -not $Global:TweakToggles[$t.Key]){ $match=$false }
            elseif($t.Group -eq $other -and $Global:TweakToggles[$t.Key]){ $match=$false }
        }
        if($match){ Set-GpuPresetGlow -Selected $vendor } else { Set-GpuPresetGlow -Selected $null }
    } else { Set-GpuPresetGlow -Selected $null }
    
    $oneClickKeys=@(Get-OneClickLessKeys)
    $match=($oneClickKeys.Count -gt 0)
    foreach($key in $oneClickKeys){
        if(-not $Global:TweakToggles[$key]){ $match=$false; break }
    }
    Set-OneClickLessButtonState -Active $match
}
function Set-NetPreset {
    param([ValidateSet("LAN NETWORK","WI-FI NETWORK")][string]$Type)
    $other= if($Type -eq "LAN NETWORK"){"WI-FI NETWORK"}else{"LAN NETWORK"}
    
    
    if($Global:ActiveNetPreset -eq $Type){
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $Type){ $Global:TweakToggles[$t.Key]=$false }
        }
        $Global:ActiveNetPreset = $null
        Add-Log "Network preset: Deselected" "#FFFFFF"
    } else {
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $Type){ $Global:TweakToggles[$t.Key]=$true }
            elseif($t.Group -eq $other){ 
                
                if($Global:RecommendedFiveMBalancedKeys -notcontains $t.Key){
                    $Global:TweakToggles[$t.Key]=$false 
                }
            }
        }
        $Global:ActiveNetPreset = $Type
        $label= if($Type -eq "LAN NETWORK"){"LAN (wired)"}else{"Wi-Fi"}
        Add-Log "Network preset: $label tweaks enabled" "#FFFFFF"
    }
    
    Update-PresetGlowConsistency
    
    
    $targetView=if($Type -eq "LAN NETWORK"){"__LAN__"}else{"__WIFI__"}
    $targetTab=if($Type -eq "LAN NETWORK"){$BtnTabLan}else{$BtnTabWifi}
    if(Get-Command Set-ToolsSubTabActive -ErrorAction SilentlyContinue){
        Set-MainMenuActive "NETTWEAKS"
        $Global:ActiveToolsView=$targetView
        Set-ToolsSubTabActive $targetTab
    }
    Show-CategoryDetail $targetView
    Save-TweakState
}
function Set-GpuPreset {
    param([ValidateSet("AMD","NVIDIA")][string]$Vendor)
    
    
    
    $mine= if($Vendor -eq "AMD"){"AMD GPU"}else{"NVIDIA GPU"}
    $other= if($Vendor -eq "AMD"){"NVIDIA GPU"}else{"AMD GPU"}

    
    if($Global:ActiveGpuPreset -eq $Vendor){
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $mine){ $Global:TweakToggles[$t.Key]=$false }
        }
        $Global:ActiveGpuPreset = $null
        Add-Log "GPU preset: Deselected" "#FFFFFF"
    } else {
        $Global:DetectedGpuVendor=$Vendor
        foreach($t in $Global:TweakInfo){
            if($t.Group -eq $mine){ $Global:TweakToggles[$t.Key]=$true }
            elseif($t.Group -eq $other){ $Global:TweakToggles[$t.Key]=$false }
        }
        $Global:ActiveGpuPreset = $Vendor
        Add-Log "GPU preset: $Vendor tweaks enabled" "#FFFFFF"
    }

    Update-PresetGlowConsistency
    
    
    
    $Global:ActiveCategory=$mine
    Show-CategoryDetail $mine
    Save-TweakState
}
$GpuPresetAmd.Add_Click({ Play-UiBeep; Set-GpuPreset -Vendor "AMD" })
$GpuPresetNvidia.Add_Click({ Play-UiBeep; Set-GpuPreset -Vendor "NVIDIA" })



$Global:OneClickRequiredNetworkKeys = @("LanOptimize","NET_NoNagle","NET_PowerSaving")
function Get-OneClickLessKeys {
    
    
    
    $excludedGroups=@("NVIDIA GPU","AMD GPU")
    $excludedKeys=@(
        "FIVEM_HighPerformanceGPU","GPU_ClearShaderCache","BLOAT_ProvisionedApps","CLEAN_RemoveBloat",
        
        
        
        "WifiOptimize",
        "NET_LanJumboFrame","NET_LanInterruptModeration","NET_DnsFast","NET_DnsFast_WiFi",
        "NET_Ipv6Disable","NET_Ipv6Disable_WiFi","NET_RssEnable","NET_FlowControlOff",
        "NET_WifiPowerSaveMode","NET_WifiRoamingAggressiveness","NET_NicBuffers",
        "NET_TaskOffload","NET_FlowControlStable","NIC_EnergyEfficientEthernet"
    )
    
    
    
    $safetyRecommended=@(
        foreach($meta in @($Global:TweakInfo)){
            try { if((Get-TweakSafetyProfile -Tweak $meta).Label -eq "RECOMMENDED"){ [string]$meta.Key } } catch {}
        }
    )
    
    
    
    $candidates=@($Global:RecommendedFiveMBalancedKeys + $safetyRecommended + $Global:ExtendedTweakKeys + $Global:OneClickRequiredNetworkKeys + @("CLEAN_KillBackgroundProcs")) | Select-Object -Unique
    return @(
        foreach($key in $candidates){
            $t=$Global:TweakInfoByKey[[string]$key]
            if($t -and $excludedGroups -notcontains [string]$t.Group -and $excludedKeys -notcontains [string]$key -and [string]$key -notmatch "GPU"){
                [string]$key
            }
        }
    ) | Select-Object -Unique
}
function Set-OneClickLessButtonState {
    param([bool]$Active)
    if(-not $BtnPresetAllExceptGpuLan){ return }
    $Global:OneClickLessSelected = $Active
    try {
        if($Active){
            $BtnPresetAllExceptGpuLan.Content = "ONE CLICK LESS  /  ON"
            $BtnPresetAllExceptGpuLan.ToolTip = "ONE CLICK LESS เปิดอยู่ — Recommended, LAN profile, Nagle และ Adapter Power Saving ถูกเลือกแล้ว; NIC ขั้นสูงและ GPU ยังเลือกเอง"
        } else {
            $BtnPresetAllExceptGpuLan.Content = "ONE CLICK LESS  /  OFF"
            $BtnPresetAllExceptGpuLan.ToolTip = "ONE CLICK LESS ปิดอยู่ — กดเพื่อเลือก Recommended, LAN profile, Nagle และ Advanced ที่รองรับ"
        }
    } catch {}
    Set-SelectAllGlow -Active $Active
}
function Set-PresetAllExceptGpuLan {
    param([bool]$Enabled = $true)
    
    
    $keys=@(Get-OneClickLessKeys)
    
    
    foreach($requiredKey in @($Global:OneClickRequiredNetworkKeys)){
        if($Global:TweakToggles.ContainsKey($requiredKey) -and $keys -notcontains $requiredKey){ $keys += $requiredKey }
    }
    $keys=@($keys | Select-Object -Unique)
    foreach($key in $keys){ $Global:TweakToggles[$key]=[bool]$Enabled }
    Set-OneClickLessButtonState -Active $Enabled
    if($Enabled){
        $requiredOn=@($Global:OneClickRequiredNetworkKeys | Where-Object { [bool]$Global:TweakToggles[$_] })
        Add-Log ("ONE CLICK LESS ON: {0} Recommended + normal + Advanced + curated cleanup selected. Required network cards ON: {1}. Advanced NIC/GPU choices remain manual." -f $keys.Count,($requiredOn -join ", ")) "#FFFFFF"
        Set-CurrentTask "ONE CLICK LESS ON — Recommended + normal + Advanced selected. Choose advanced NIC tuning and NVIDIA/AMD GPU manually, then press START LESS PROJECT."
        Show-TweakToast -Label "ONE CLICK LESS" -Enabled $true -OverrideText "ONE CLICK LESS  /  ON" -DurationMs 2200
    } else {
        Add-Log ("ONE CLICK LESS OFF: {0} owned selections cleared, including the required Recommended network cards. Advanced manual profiles were left unchanged." -f $keys.Count) "#D8D8D8"
        Set-CurrentTask "ONE CLICK LESS OFF — no normal or Advanced values from this preset are selected."
        Show-TweakToast -Label "ONE CLICK LESS" -Enabled $false -OverrideText "ONE CLICK LESS  /  OFF" -DurationMs 2200
    }
    Update-PresetGlowConsistency
    if($Global:ActiveCategory){ Show-CategoryDetail $Global:ActiveCategory }
    Save-TweakState
}
function Invoke-OneClickSoftPowerplan {
    if(-not $IsAdmin){
        [System.Windows.MessageBox]::Show("ONE CLICK LESS needs Administrator permission to activate SOFTPOWERPLAN. Run the PS1 as Administrator.","ONE CLICK LESS",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
        return
    }
    try{
        $r=Activate-SoftPowerplan
        if(-not $r -or -not $r.Guid){ throw "SOFTPOWERPLAN activation could not be verified." }
        $Global:SoftPowerplanLocked=$true
        $Global:PowerPlanSelectedLabel="SOFTPOWERPLAN"
        $Global:PowerPlanExpectedGuid=[string]$r.Guid
        $Global:PowerPlanStatusUiLock=$true
        Add-Log ("SOFTPOWERPLAN activated and locked: {0}" -f $r.Guid) "#FFFFFF"
        Show-TweakToast -Label "POWERPLAN" -Enabled $true -OverrideText "SOFTPOWERPLAN  /  LOCKED" -DurationMs 2800
        Set-CurrentTask "ONE CLICK LESS ready. SOFTPOWERPLAN is active and locked."
    } catch {
        $Global:SoftPowerplanLocked=$false
        Add-Log ("SOFTPOWERPLAN activation failed: {0}" -f $_.Exception.Message) "#D8D8D8"
        Show-TweakToast -Label "POWERPLAN" -Enabled $false -OverrideText "SOFTPOWERPLAN  /  FAILED" -DurationMs 3200
    }
}
$BtnPresetAllExceptGpuLan.Add_Click({
    Play-OneClickToggleSound -Type "Click"
    $enableOneClick = (-not [bool]$Global:OneClickLessSelected)
    Set-PresetAllExceptGpuLan -Enabled $enableOneClick
    Play-OneClickToggleSound -Type (if($enableOneClick){"On"}else{"Off"})
    if($enableOneClick){
        Invoke-OneClickSoftPowerplan
    } else {
        
        $Global:SoftPowerplanLocked = $false
        $Global:PowerPlanStatusUiLock = $false
        Add-Log "ONE CLICK LESS OFF: SOFTPOWERPLAN lock released; choose another plan if needed." "#D8D8D8"
        Set-CurrentTask "ONE CLICK LESS OFF — SOFTPOWERPLAN is unlocked."
    }
})
