function Set-ToolsSubTabActive {
    param($Active)
    $activeBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#303030")
    $idleBrush=[System.Windows.Media.Brushes]::Transparent
    $activeText=[System.Windows.Media.Brushes]::White
    $idleText=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B5B5B5")
    foreach($tab in @($BtnTabAll,$BtnTabLan,$BtnTabWifi,$BtnTabInput,$BtnTabSystem)){
        if($tab){
            $tab.Background=if($tab -eq $Active){$activeBrush}else{$idleBrush}
            $tab.Foreground=if($tab -eq $Active){$activeText}else{$idleText}
        }
    }
}
function Set-MainMenuActive {
    param([ValidateSet("TOOLS","FIVEM","RESHADE","POWERPLAN","WIN32","NETTWEAKS","FIVEMOPTIMIZE","KAIPRIME")][string]$Menu)
    $Global:ActiveMainMenu=$Menu
    $activeBrush=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#303030")
    $idleBrush=[System.Windows.Media.Brushes]::Transparent
    $activeText=[System.Windows.Media.Brushes]::White
    $idleText=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B5B5B5")
    foreach($entry in @(
        @{Button=$BtnTabTools; Menu="TOOLS"},
        @{Button=$BtnTabFiveM; Menu="FIVEM"},
        @{Button=$BtnTabReshade; Menu="RESHADE"},
        @{Button=$BtnTabSettings; Menu="POWERPLAN"},
        @{Button=$BtnTabWin32; Menu="WIN32"},
        @{Button=$BtnTabNetTweaks; Menu="NETTWEAKS"},
         @{Button=$BtnTabFiveMOptimize; Menu="FIVEMOPTIMIZE"},
         @{Button=$BtnTabKaiPrime; Menu="KAIPRIME"}
     )){
        if($entry.Button){
            $entry.Button.Background=if($entry.Menu -eq $Menu){$activeBrush}else{$idleBrush}
            $entry.Button.Foreground=if($entry.Menu -eq $Menu){$activeText}else{$idleText}
        }
    }
    if($ToolsSubNav){
        $ToolsSubNav.Visibility=if($Menu -eq "TOOLS"){[System.Windows.Visibility]::Visible}else{[System.Windows.Visibility]::Collapsed}
    }
    if($Menu -ne "TOOLS"){ Set-ToolsSubTabActive $null }
}
