function Start-AutoFiveMCacheAsync {
    if($Global:AutoFiveMCacheJob -and $Global:AutoFiveMCacheJob.State -eq "Running"){ return }
    $BtnClearCaches.IsEnabled=$false
    Set-CurrentTask "Detecting and clearing safe FiveM cache folders..."
    Show-TweakToast -Label "FIVEM CACHE" -Enabled $true -OverrideText "FIVEM CACHE  /  AUTO SCAN" -DurationMs 1400
    $cacheScript = {
        $ErrorActionPreference="SilentlyContinue"
        $result=[ordered]@{FoldersFound=0;FoldersCleared=0;ItemsRemoved=0;BytesRemoved=0;Skipped=0;Errors=0;FiveMRunning=$false}
        foreach($procName in @("FiveM","FiveM_GTAProcess","CitizenFX")){
            if(Get-Process -Name $procName -ErrorAction SilentlyContinue){$result.FiveMRunning=$true;break}
        }
        $roots=@()
        if($env:LOCALAPPDATA){$roots += (Join-Path $env:LOCALAPPDATA "FiveM\FiveM.app")}
        if($env:USERPROFILE){$roots += (Join-Path $env:USERPROFILE "AppData\Local\FiveM\FiveM.app")}
        $roots=@($roots | Where-Object {$_} | Select-Object -Unique)
        
        
        $relativeCachePaths=@("data\cache","data\server-cache","data\server-cache-priv")
        foreach($root in $roots){
            foreach($relativePath in $relativeCachePaths){
                $path=Join-Path $root $relativePath
                if(-not (Test-Path -LiteralPath $path -PathType Container)){continue}
                $result.FoldersFound++
                try{
                    $children=@(Get-ChildItem -LiteralPath $path -Force -ErrorAction SilentlyContinue)
                    foreach($item in $children){
                        $size=0L
                        if(-not $item.PSIsContainer -and $item.Length -ne $null){$size=[int64]$item.Length}
                        try{
                            Remove-Item -LiteralPath $item.FullName -Force -Recurse -ErrorAction Stop
                            if(-not (Test-Path -LiteralPath $item.FullName)){
                                $result.ItemsRemoved++
                                $result.BytesRemoved += $size
                            } else {$result.Skipped++}
                        }catch{$result.Skipped++}
                    }
                    $result.FoldersCleared++
                }catch{$result.Errors++}
            }
        }
        [pscustomobject]$result
    }
    try {
        $Global:AutoFiveMCacheJob=Start-Job -ScriptBlock $cacheScript -ErrorAction Stop
    } catch {
        $BtnClearCaches.IsEnabled=$true
        Show-TweakToast -Label "FIVEM CACHE" -Enabled $false -OverrideText "FIVEM CACHE  /  COULD NOT START" -DurationMs 2600
        Set-CurrentTask "FiveM cache cleaner could not start."
        Play-IssueTone
        return
    }
    $Global:AutoFiveMCacheStartedUtc=[DateTime]::UtcNow
    $Global:AutoFiveMCachePoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:AutoFiveMCachePoller.Interval=[TimeSpan]::FromMilliseconds(250)
    $Global:AutoFiveMCachePoller.Add_Tick({
        if(-not $Global:AutoFiveMCacheJob){return}
        $age=([DateTime]::UtcNow-$Global:AutoFiveMCacheStartedUtc).TotalSeconds
        if($Global:AutoFiveMCacheJob.State -eq "Running" -and $age -lt 90){return}
        $Global:AutoFiveMCachePoller.Stop()
        if($Global:AutoFiveMCacheJob.State -eq "Running"){
            Stop-Job $Global:AutoFiveMCacheJob -EA SilentlyContinue
            Show-TweakToast -Label "FIVEM CACHE" -Enabled $false -OverrideText "FIVEM CACHE  /  TIMEOUT" -DurationMs 2600
            Set-CurrentTask "FiveM cache scan timed out."
            Play-IssueTone
        } else {
            $result=@(Receive-Job $Global:AutoFiveMCacheJob -Wait -AutoRemoveJob -EA SilentlyContinue | Select-Object -Last 1)
            $r=$result | Select-Object -First 1
            if($r){
                $mb=[math]::Round(([double]$r.BytesRemoved/1MB),1)
                $processState=if($r.FiveMRunning){"FIVEM OPEN"}else{"FIVEM CLOSED"}
                if([int]$r.FoldersFound -eq 0){
                    Show-TweakToast -Label "FIVEM CACHE" -Enabled $false -OverrideText "FIVEM CACHE  /  NO FOLDERS FOUND" -DurationMs 2800
                    Set-CurrentTask "No FiveM cache folders were found."
                    Play-IssueTone
                } elseif([int]$r.Errors -eq 0 -and [int]$r.Skipped -eq 0){
                    $summary="FIVEM CACHE  /  $($r.ItemsRemoved) ITEMS  /  $mb MB  /  $processState"
                    Show-TweakToast -Label "FIVEM CACHE" -Enabled $true -OverrideText $summary -DurationMs 3600
                    Set-CurrentTask "FiveM cache cleanup completed."
                    Add-Log ("FiveM auto cache cleanup: folders={0}; items={1}; freed={2} MB; state={3}" -f $r.FoldersCleared,$r.ItemsRemoved,$mb,$processState) "#FFFFFF"
                    Play-CompletionChime
                } else {
                    $summary="FIVEM CACHE  /  $($r.ItemsRemoved) REMOVED  /  $($r.Skipped) SKIPPED"
                    Show-TweakToast -Label "FIVEM CACHE" -Enabled $false -OverrideText $summary -DurationMs 3600
                    Set-CurrentTask "FiveM cache cleanup completed with locked files skipped."
                    Add-Log ("FiveM auto cache cleanup completed with skips: folders={0}; items={1}; skipped={2}; errors={3}" -f $r.FoldersCleared,$r.ItemsRemoved,$r.Skipped,$r.Errors) "#FFFFFF"
                    Play-IssueTone
                }
            } else {
                Show-TweakToast -Label "FIVEM CACHE" -Enabled $false -OverrideText "FIVEM CACHE  /  NO RESULT" -DurationMs 2600
                Set-CurrentTask "FiveM cache cleaner returned no result."
                Play-IssueTone
            }
        }
        Remove-Job $Global:AutoFiveMCacheJob -Force -EA SilentlyContinue
        $Global:AutoFiveMCacheJob=$null
        $BtnClearCaches.IsEnabled=$true
    }.GetNewClosure())
    $Global:AutoFiveMCachePoller.Start()
}
function Start-ClearCachesAsync {
    if($Global:CacheClearJob -and $Global:CacheClearJob.State -eq "Running"){ return }
    $BtnClearCaches.IsEnabled=$false
    Set-CurrentTask "Clearing DNS, shader and FiveM caches..."
    Show-TweakToast -Label "CACHE CLEANER" -Enabled $true -OverrideText "CACHE CLEANER  /  STARTING" -DurationMs 1200
    $cacheScript = {
        $ErrorActionPreference="Continue"
        $result=[ordered]@{DnsFlushed=$false;ShaderFolders=0;FiveMFolders=0;Errors=0}
        try { & ipconfig.exe /flushdns 2>&1 | Out-Null; if($LASTEXITCODE -eq 0){$result.DnsFlushed=$true} } catch { $result.Errors++ }
        $shaderPaths=@(
            "$env:LOCALAPPDATA\D3DSCache",
            "$env:LOCALAPPDATA\NVIDIA\DXCache",
            "$env:LOCALAPPDATA\NVIDIA\GLCache",
            "$env:LOCALAPPDATA\NVIDIA Corporation\NV_Cache",
            "$env:LOCALAPPDATA\AMD\DxCache",
            "$env:LOCALAPPDATA\AMD\DxcCache",
            "$env:LOCALAPPDATA\AMD\GLCache",
            "$env:LOCALAPPDATA\AMD\VkCache"
        )
        foreach($path in $shaderPaths){
            if(Test-Path -LiteralPath $path){
                try { Remove-Item -Path (Join-Path $path "*") -Force -Recurse -ErrorAction SilentlyContinue; $result.ShaderFolders++ } catch { $result.Errors++ }
            }
        }
        
        $fiveMPaths=@(
            "$env:LOCALAPPDATA\FiveM\FiveM.app\data\cache",
            "$env:LOCALAPPDATA\FiveM\FiveM.app\data\server-cache",
            "$env:LOCALAPPDATA\FiveM\FiveM.app\data\server-cache-priv",
            "$env:LOCALAPPDATA\FiveM\FiveM.app\data\nui-storage"
        )
        foreach($path in $fiveMPaths){
            if(Test-Path -LiteralPath $path){
                try { Remove-Item -Path (Join-Path $path "*") -Force -Recurse -ErrorAction SilentlyContinue; $result.FiveMFolders++ } catch { $result.Errors++ }
            }
        }
        [pscustomobject]$result
    }
    try {
        $Global:CacheClearJob=Start-Job -ScriptBlock $cacheScript -ErrorAction Stop
    } catch {
        $BtnClearCaches.IsEnabled=$true
        Show-TweakToast -Label "CACHE CLEANER" -Enabled $false -OverrideText "CACHE CLEANER  /  COULD NOT START" -DurationMs 2600
        Set-CurrentTask "Cache cleaner could not start."
        Play-IssueTone
        return
    }
    $Global:CacheClearStartedUtc=[DateTime]::UtcNow
    $Global:CacheClearPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:CacheClearPoller.Interval=[TimeSpan]::FromMilliseconds(350)
    $Global:CacheClearPoller.Add_Tick({
        if(-not $Global:CacheClearJob){ return }
        $age=([DateTime]::UtcNow-$Global:CacheClearStartedUtc).TotalSeconds
        if($Global:CacheClearJob.State -eq "Running" -and $age -lt 120){ return }
        $Global:CacheClearPoller.Stop()
        if($Global:CacheClearJob.State -eq "Running"){
            Stop-Job $Global:CacheClearJob -EA SilentlyContinue
            Show-TweakToast -Label "CACHE CLEANER" -Enabled $false -OverrideText "CACHE CLEANER  /  TIMEOUT" -DurationMs 2600
            Set-CurrentTask "Cache cleaner timed out. Check locked files."
            Play-IssueTone
        } else {
            $result=@(Receive-Job $Global:CacheClearJob -Wait -AutoRemoveJob -EA SilentlyContinue | Select-Object -Last 1)
            $r=$result | Select-Object -First 1
            $dns=if($r -and $r.DnsFlushed){"DNS OK"}else{"DNS SKIP"}
            $shader=if($r){[int]$r.ShaderFolders}else{0}
            $fivem=if($r){[int]$r.FiveMFolders}else{0}
            $errors=if($r){[int]$r.Errors}else{1}
            if($r -and $errors -eq 0){
                $summary="CACHE CLEAR  /  $dns  /  SHADER $shader  /  FIVEM $fivem"
                Show-TweakToast -Label "CACHE CLEANER" -Enabled $true -OverrideText $summary -DurationMs 3200
                Set-CurrentTask "DNS, shader and FiveM cache cleanup completed."
                Play-CompletionChime
            } else {
                Show-TweakToast -Label "CACHE CLEANER" -Enabled $false -OverrideText "CACHE CLEAR  /  COMPLETED WITH SKIPS" -DurationMs 3000
                Set-CurrentTask "Cache cleanup completed with locked or unavailable paths."
                Play-IssueTone
            }
        }
        Remove-Job $Global:CacheClearJob -Force -EA SilentlyContinue
        $Global:CacheClearJob=$null
        $BtnClearCaches.IsEnabled=$true
    }.GetNewClosure())
    $Global:CacheClearPoller.Start()
}
function Start-CleanJunkFilesAsync {
    if($Global:JunkCleanJob -and $Global:JunkCleanJob.State -eq "Running"){ return }
    $answer=[System.Windows.MessageBox]::Show("Delete temporary junk from the current user TEMP folder and Windows TEMP folder?`n`nLocked or active files will be skipped. FiveM, shader and DNS caches use the separate CLEAR ALL CACHE button.","LESS PROJECT - Clean Junk Files",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Question)
    if($answer -ne [System.Windows.MessageBoxResult]::Yes){ return }
    $BtnJunkCleaner.IsEnabled=$false
    Set-CurrentTask "Cleaning temporary junk files..."
    Show-TweakToast -Label "JUNK CLEANER" -Enabled $true -OverrideText "JUNK CLEANER  /  SCANNING" -DurationMs 1200
    $junkScript={
        $ErrorActionPreference="SilentlyContinue"
        $deletedFiles=0; $deletedBytes=[int64]0; $lockedEntries=0; $locations=0
        $roots=@()
        if($env:TEMP){ $roots += $env:TEMP }
        if($env:WINDIR){ $roots += (Join-Path $env:WINDIR "Temp") }
        $roots=@($roots | Where-Object {$_ -and (Test-Path -LiteralPath $_ -PathType Container)} | ForEach-Object {[IO.Path]::GetFullPath($_)} | Sort-Object -Unique)
        foreach($root in $roots){
            $locations++
            $items=@(Get-ChildItem -LiteralPath $root -Force -ErrorAction SilentlyContinue)
            foreach($item in $items){
                try{
                    if($item.PSIsContainer){
                        $files=@(Get-ChildItem -LiteralPath $item.FullName -File -Force -Recurse -ErrorAction SilentlyContinue)
                        $deletedFiles += [int]$files.Count
                        if($files.Count -gt 0){ $deletedBytes += [int64](($files | Measure-Object -Property Length -Sum).Sum) }
                    } else {
                        $deletedFiles++
                        $deletedBytes += [int64]$item.Length
                    }
                    Remove-Item -LiteralPath $item.FullName -Force -Recurse -ErrorAction Stop
                } catch { $lockedEntries++ }
            }
        }
        [pscustomobject]@{DeletedFiles=$deletedFiles;DeletedBytes=$deletedBytes;LockedEntries=$lockedEntries;Locations=$locations}
    }
    try { $Global:JunkCleanJob=Start-Job -ScriptBlock $junkScript -ErrorAction Stop } catch {
        $BtnJunkCleaner.IsEnabled=$true
        Show-TweakToast -Label "JUNK CLEANER" -Enabled $false -OverrideText "JUNK CLEANER  /  COULD NOT START" -DurationMs 2600
        Set-CurrentTask "Junk cleaner could not start."
        Play-IssueTone
        return
    }
    $Global:JunkCleanStartedUtc=[DateTime]::UtcNow
    $Global:JunkCleanPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:JunkCleanPoller.Interval=[TimeSpan]::FromMilliseconds(350)
    $Global:JunkCleanPoller.Add_Tick({
        if(-not $Global:JunkCleanJob){ return }
        $age=([DateTime]::UtcNow-$Global:JunkCleanStartedUtc).TotalSeconds
        if($Global:JunkCleanJob.State -eq "Running" -and $age -lt 180){ return }
        $Global:JunkCleanPoller.Stop()
        if($Global:JunkCleanJob.State -eq "Running"){
            Stop-Job $Global:JunkCleanJob -EA SilentlyContinue
            Show-TweakToast -Label "JUNK CLEANER" -Enabled $false -OverrideText "JUNK CLEANER  /  TIMEOUT" -DurationMs 2600
            Set-CurrentTask "Junk cleaner timed out."
            Play-IssueTone
        } else {
            $result=@(Receive-Job $Global:JunkCleanJob -Wait -AutoRemoveJob -EA SilentlyContinue | Select-Object -Last 1)
            $r=$result | Select-Object -First 1
            if($r){
                $bytes=[int64]$r.DeletedBytes
                if($bytes -ge 1GB){$sizeText=("{0:N2} GB" -f ($bytes/1GB))} elseif($bytes -ge 1MB){$sizeText=("{0:N1} MB" -f ($bytes/1MB))} elseif($bytes -ge 1KB){$sizeText=("{0:N1} KB" -f ($bytes/1KB))} else {$sizeText=("{0} B" -f $bytes)}
                if([int]$r.LockedEntries -gt 0){
                    Show-TweakToast -Label "JUNK CLEANER" -Enabled $true -OverrideText ("JUNK CLEANED  /  {0} FILES  /  {1}  /  {2} SKIPPED" -f [int]$r.DeletedFiles,$sizeText,[int]$r.LockedEntries) -DurationMs 3800
                    Set-CurrentTask "Junk cleanup complete; locked files were skipped."
                } else {
                    Show-TweakToast -Label "JUNK CLEANER" -Enabled $true -OverrideText ("JUNK CLEANED  /  {0} FILES  /  {1}" -f [int]$r.DeletedFiles,$sizeText) -DurationMs 3200
                    Set-CurrentTask "Temporary junk cleanup completed."
                }
                Play-CompletionChime
            } else {
                Show-TweakToast -Label "JUNK CLEANER" -Enabled $false -OverrideText "JUNK CLEANER  /  NO RESULT" -DurationMs 2600
                Set-CurrentTask "Junk cleaner returned no result."
                Play-IssueTone
            }
        }
        Remove-Job $Global:JunkCleanJob -Force -EA SilentlyContinue
        $Global:JunkCleanJob=$null
        $BtnJunkCleaner.IsEnabled=$true
    }.GetNewClosure())
    $Global:JunkCleanPoller.Start()
}
function Start-NetworkStabilityTestAsync {
    if($Global:NetTestJob -and $Global:NetTestJob.State -eq "Running"){ return }
    $BtnCitizenFX.IsEnabled=$false
    Set-CurrentTask "Network stability test running..."
    Show-TweakToast -Label "NETWORK TEST" -Enabled $true -OverrideText "NETWORK TEST  /  PING + NIC STATS" -DurationMs 1400
    $stateDir=$Global:StateDir
    $netScript={
        param([string]$StateDir)
        $ErrorActionPreference="SilentlyContinue"
        $targets=New-Object System.Collections.Generic.List[string]
        try{
            $route=Get-NetRoute -DestinationPrefix "0.0.0.0/0" -ErrorAction SilentlyContinue | Sort-Object RouteMetric,InterfaceMetric | Select-Object -First 1
            if($route -and $route.NextHop -and $route.NextHop -ne "0.0.0.0"){[void]$targets.Add([string]$route.NextHop)}
        }catch{}
        foreach($target in @("1.1.1.1","8.8.8.8")){if(-not $targets.Contains($target)){[void]$targets.Add($target)}}
        $rows=New-Object System.Collections.Generic.List[object]
        foreach($target in @($targets)){
            $sent=20
            $samples=@(Test-Connection -ComputerName $target -Count $sent -ErrorAction SilentlyContinue)
            $valid=@($samples | Where-Object { $_.ResponseTime -ge 0 })
            $times=@($valid | ForEach-Object {[double]$_.ResponseTime})
            $received=[int]$times.Count
            $loss=[math]::Round((($sent-$received)*100.0)/$sent,1)
            $avg=if($received -gt 0){[math]::Round((($times | Measure-Object -Average).Average),1)}else{-1}
            $min=if($received -gt 0){[math]::Round((($times | Measure-Object -Minimum).Minimum),1)}else{-1}
            $max=if($received -gt 0){[math]::Round((($times | Measure-Object -Maximum).Maximum),1)}else{-1}
            [void]$rows.Add([pscustomobject]@{Target=$target;Sent=$sent;Received=$received;LossPct=$loss;AvgMs=$avg;MinMs=$min;MaxMs=$max})
        }
        $adapterRows=New-Object System.Collections.Generic.List[object]
        foreach($adapter in @(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object {$_.Status -eq "Up"})){
            try{
                $stat=Get-NetAdapterStatistics -Name $adapter.Name -ErrorAction Stop
                [void]$adapterRows.Add([pscustomobject]@{Adapter=$adapter.Name;InErrors=$stat.ReceivedPacketErrors;OutErrors=$stat.OutboundPacketErrors;InDrops=$stat.ReceivedDiscardedPackets;OutDrops=$stat.OutboundDiscardedPackets})
            }catch{}
        }
        try{
            if(-not (Test-Path -LiteralPath $StateDir)){New-Item -ItemType Directory -Path $StateDir -Force | Out-Null}
            $report=Join-Path $StateDir ("Network-Stability-{0}.txt" -f (Get-Date -Format "yyyyMMdd-HHmmss"))
            $lines=New-Object System.Collections.Generic.List[string]
            [void]$lines.Add("LESS PROJECT NETWORK STABILITY TEST")
            [void]$lines.Add((Get-Date).ToString("yyyy-MM-dd HH:mm:ss"))
            [void]$lines.Add("")
            [void]$lines.Add("Target | Sent | Received | Loss | Avg ms | Min ms | Max ms")
            foreach($row in $rows){[void]$lines.Add(("{0} | {1} | {2} | {3}% | {4} | {5} | {6}" -f $row.Target,$row.Sent,$row.Received,$row.LossPct,$row.AvgMs,$row.MinMs,$row.MaxMs))}
            [void]$lines.Add("")
            [void]$lines.Add("Physical adapter counters (cumulative since adapter start)")
            foreach($row in $adapterRows){[void]$lines.Add(("{0} | InErrors={1} | OutErrors={2} | InDrops={3} | OutDrops={4}" -f $row.Adapter,$row.InErrors,$row.OutErrors,$row.InDrops,$row.OutDrops))}
            Set-Content -LiteralPath $report -Value @($lines) -Encoding UTF8
        }catch{$report=$null}
        [pscustomobject]@{Rows=@($rows);AdapterRows=@($adapterRows);Report=$report}
    }
    try{$Global:NetTestJob=Start-Job -ScriptBlock $netScript -ArgumentList $stateDir -ErrorAction Stop}catch{
        $BtnCitizenFX.IsEnabled=$true
        Show-TweakToast -Label "NETWORK TEST" -Enabled $false -OverrideText "NETWORK TEST  /  COULD NOT START" -DurationMs 2600
        Set-CurrentTask "Network test could not start."; Play-IssueTone; return
    }
    $Global:NetTestStartedUtc=[DateTime]::UtcNow
    $Global:NetTestPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:NetTestPoller.Interval=[TimeSpan]::FromMilliseconds(350)
    $Global:NetTestPoller.Add_Tick({
        $age=([DateTime]::UtcNow-$Global:NetTestStartedUtc).TotalSeconds
        if($Global:NetTestJob.State -eq "Running" -and $age -lt 120){return}
        $Global:NetTestPoller.Stop()
        if($Global:NetTestJob.State -eq "Running"){
            Stop-Job $Global:NetTestJob -EA SilentlyContinue
            Show-TweakToast -Label "NETWORK TEST" -Enabled $false -OverrideText "NETWORK TEST  /  TIMEOUT" -DurationMs 2600
            Set-CurrentTask "Network test timed out."; Play-IssueTone
        }else{
            $result=@(Receive-Job $Global:NetTestJob -Wait -AutoRemoveJob -EA SilentlyContinue | Select-Object -Last 1)
            $r=$result | Select-Object -First 1
            if($r -and $r.Rows){
                $gw=$r.Rows | Select-Object -First 1
                $dns=$r.Rows | Select-Object -Skip 1 -First 1
                $gwText=("GW {0}%" -f $gw.LossPct); $dnsText=("DNS {0}%" -f $dns.LossPct)
                $reportText=if($r.Report){"REPORT SAVED"}else{"REPORT FAILED"}
                Show-TweakToast -Label "NETWORK TEST" -Enabled (($gw.LossPct -eq 0) -and ($dns.LossPct -eq 0)) -OverrideText ("NETWORK TEST  /  {0}  /  {1}  /  {2}" -f $gwText,$dnsText,$reportText) -DurationMs 4200
                Add-Log ("Network test: {0}; {1}; report={2}" -f $gwText,$dnsText,$r.Report) "#FFFFFF"
                Set-CurrentTask "Network stability test completed."
                if(($gw.LossPct -gt 0) -or ($dns.LossPct -gt 0)){Play-IssueTone}else{Play-CompletionChime}
            }else{
                Show-TweakToast -Label "NETWORK TEST" -Enabled $false -OverrideText "NETWORK TEST  /  NO RESULT" -DurationMs 2600
                Set-CurrentTask "Network test returned no result."; Play-IssueTone
            }
        }
        Remove-Job $Global:NetTestJob -Force -EA SilentlyContinue
        $Global:NetTestJob=$null; $BtnCitizenFX.IsEnabled=$true
    }.GetNewClosure())
    $Global:NetTestPoller.Start()
}
$BtnClearCaches.Add_Click({ Play-UiBeep; Start-AutoFiveMCacheAsync })
$BtnJunkCleaner.Add_Click({ Play-UiBeep; Start-CleanJunkFilesAsync })
function Update-CitizenFXIni {
    
    
    $targetPath = "C:\Users\Administrator\AppData\Local\FiveM\FiveM.app\CitizenFX.ini"
    $citizenFxConfig = @'
cl_forceStreamingLegacy=false
enable_cloth=1
disable_ambient_occlusion=0
disable_fog=0
NV_disableShaderDiskCache=false

UseHighPriorityThreads=1
UseAudioThread=1

ClearInvalidPoolCache=1
IgnoreDifferentVideoCard=1

DisableResourceTimeouts=1

[Addon]
net_maxMtu 1200
vid_budgetScale 0
ui_maxQueriesPerMinute 15
disable_vsync 1
disable_fog 1
disable_ambient_occlusion 1

[Input]
UseRawInput=1
DisableMouseSmoothing=1
DisableControllerDeadzone=1
LockMouseToWindow=1
RawInputBufferSize=512
RawInputBufferFlush=1
EnableLowLatencyInput=1
DisableKeyboardDebounce=1

[Renderer]
DisableVSync=1
ForceRenderAheadLimit=0
SwapChainUseWaitableSwapChain=1
EnableFramePacing=0
EnableTripleBuffering=0
DisableLatencyLimiter=1
WaitForVBlank=0
ReduceInputLatency=1
ImmediatePresent=1
DisableOcclusionQueries=1

[Streaming]
MaxStreamingRequests=50
MaxStreamingMemory=2000
'@
    
    
    $sourceConfigPath = $null
    if($PSScriptRoot){ $sourceConfigPath = Join-Path $PSScriptRoot "NewTextDocument.txt" }
    elseif($PSCommandPath){ $sourceConfigPath = Join-Path (Split-Path -Parent $PSCommandPath) "NewTextDocument.txt" }
    if($sourceConfigPath -and (Test-Path -LiteralPath $sourceConfigPath -PathType Leaf)){
        try {
            $externalConfig = [System.IO.File]::ReadAllText($sourceConfigPath)
            if(-not [string]::IsNullOrWhiteSpace($externalConfig)){ $citizenFxConfig = $externalConfig.TrimEnd() + "`r`n" }
        } catch {}
    }
    try {
        if(-not (Test-Path -LiteralPath $targetPath -PathType Leaf)) {
            [System.Windows.MessageBox]::Show("ไม่พบไฟล์ CitizenFX.ini ที่:`n$targetPath`n`nกรุณาตรวจสอบว่า FiveM ติดตั้งอยู่ในโฟลเดอร์นี้แล้ว","CITIZENFX",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Warning) | Out-Null
            Set-CurrentTask "CitizenFX.ini was not found."
            Show-TweakToast -Label "CITIZENFX" -Enabled $false -OverrideText "CITIZENFX  /  FILE NOT FOUND" -DurationMs 2600
            return
        }
        $originalText = [System.IO.File]::ReadAllText($targetPath)
        $lineBreak = if($originalText.Contains("`r`n")){"`r`n"}else{"`n"}
        $hadTrailingBreak = $originalText.EndsWith("`r`n") -or $originalText.EndsWith("`n")
        $originalLines = [regex]::Split($originalText, "\r?\n")
        $sectionSeen=@{}
        $sectionDisplayNames=@{}
        foreach($existingLine in $originalLines){
            $headerMatch=[regex]::Match($existingLine.Trim(), '^\[([^\]]+)\]\s*$')
            if($headerMatch.Success){
                $sectionKey=$headerMatch.Groups[1].Value.Trim().ToLowerInvariant()
                $sectionSeen[$sectionKey]=$true
                $sectionDisplayNames[$sectionKey]=$headerMatch.Groups[1].Value.Trim()
            }
        }
        
        
        $rootTarget=if($sectionSeen.ContainsKey("game")){"game"}else{""}
        $patchBySection=@{}
        $patchDisplayNames=@{}
        $patchSection=""
        foreach($patchLine in [regex]::Split($citizenFxConfig.Trim(), "\r?\n")){
            $trimmed=$patchLine.Trim()
            if([string]::IsNullOrWhiteSpace($trimmed) -or $trimmed.StartsWith(";") -or $trimmed.StartsWith("#")){continue}
            $patchHeader=[regex]::Match($trimmed, '^\[([^\]]+)\]\s*$')
            if($patchHeader.Success){
                $patchSection=$patchHeader.Groups[1].Value.Trim().ToLowerInvariant()
                $patchDisplayNames[$patchSection]=$patchHeader.Groups[1].Value.Trim()
                continue
            }
            $entryMatch=[regex]::Match($trimmed, '^(?<key>[A-Za-z0-9_.-]+)\s*(?<separator>=|\s+)\s*(?<value>.*)$')
            if(-not $entryMatch.Success){continue}
            $effectiveSection=$patchSection
            if($effectiveSection -eq "" -and $rootTarget){$effectiveSection=$rootTarget}
            if(-not $patchBySection.ContainsKey($effectiveSection)){$patchBySection[$effectiveSection]=@()}
            $separator=if($entryMatch.Groups["separator"].Value -eq "="){"="}else{" "}
            $entry=[pscustomobject]@{
                Key=$entryMatch.Groups["key"].Value
                Value=$entryMatch.Groups["value"].Value
                Separator=$separator
                Lookup=("{0}|{1}" -f $effectiveSection,$entryMatch.Groups["key"].Value).ToLowerInvariant()
            }
            $patchBySection[$effectiveSection] += $entry
        }
        $found=@{}
        $inserted=@{}
        $stats=[ordered]@{Updated=0;Added=0}
        $merged=New-Object 'System.Collections.Generic.List[string]'
        $addMissing = {
            param([string]$section)
            $normalized=if($null -eq $section){""}else{$section.ToLowerInvariant()}
            if($inserted.ContainsKey($normalized) -or -not $patchBySection.ContainsKey($normalized)){return}
            foreach($entry in @($patchBySection[$normalized])){
                if(-not $found.ContainsKey($entry.Lookup)){
                    if($merged.Count -gt 0 -and $merged[$merged.Count-1].Trim() -ne ""){$merged.Add("")}
                    $merged.Add("$($entry.Key)$($entry.Separator)$($entry.Value)")
                    $stats.Added++
                }
            }
            $inserted[$normalized]=$true
        }
        $currentSection=""
        foreach($existingLine in $originalLines){
            $trimmed=$existingLine.Trim()
            $headerMatch=[regex]::Match($trimmed, '^\[([^\]]+)\]\s*$')
            if($headerMatch.Success){
                & $addMissing $currentSection
                $currentSection=$headerMatch.Groups[1].Value.Trim().ToLowerInvariant()
                $sectionSeen[$currentSection]=$true
                if(-not $sectionDisplayNames.ContainsKey($currentSection)){$sectionDisplayNames[$currentSection]=$headerMatch.Groups[1].Value.Trim()}
                $merged.Add($existingLine)
                continue
            }
            if(-not $trimmed.StartsWith(";") -and -not $trimmed.StartsWith("#") -and $patchBySection.ContainsKey($currentSection)){
                $existingMatch=[regex]::Match($trimmed, '^(?<key>[A-Za-z0-9_.-]+)\s*(?<separator>=|\s+)\s*(?<value>.*)$')
                if($existingMatch.Success){
                    $existingKey=$existingMatch.Groups["key"].Value
                    foreach($entry in @($patchBySection[$currentSection])){
                        if($existingKey.Equals($entry.Key,[System.StringComparison]::OrdinalIgnoreCase)){
                            $indentMatch=[regex]::Match($existingLine, '^(?<indent>\s*)')
                            $indent=$indentMatch.Groups["indent"].Value
                            $existingSeparator=if($existingMatch.Groups["separator"].Value -eq "="){"="}else{" "}
                            $existingLine="$indent$($entry.Key)$existingSeparator$($entry.Value)"
                            $found[$entry.Lookup]=$true
                            $stats.Updated++
                        }
                    }
                }
            }
            $merged.Add($existingLine)
        }
        & $addMissing $currentSection
        
        foreach($sectionKey in @($patchBySection.Keys)){
            if($inserted.ContainsKey($sectionKey)){continue}
            if($merged.Count -gt 0 -and $merged[$merged.Count-1].Trim() -ne ""){$merged.Add("")}
            if($sectionKey -ne ""){
                $display=if($patchDisplayNames.ContainsKey($sectionKey)){$patchDisplayNames[$sectionKey]}else{$sectionKey}
                $merged.Add("[$display]")
            }
            foreach($entry in @($patchBySection[$sectionKey])){
                if(-not $found.ContainsKey($entry.Lookup)){
                    $merged.Add("$($entry.Key)$($entry.Separator)$($entry.Value)")
                    $stats.Added++
                }
            }
            $inserted[$sectionKey]=$true
        }
        $mergedText=[string]::Join($lineBreak,[string[]]$merged)
        if($hadTrailingBreak){$mergedText += $lineBreak}
        if($mergedText -ne $originalText){
            $backupPath = "$targetPath.bak.$(Get-Date -Format 'yyyyMMdd-HHmmss')"
            Copy-Item -LiteralPath $targetPath -Destination $backupPath -Force -ErrorAction Stop
            [System.IO.File]::WriteAllText($targetPath, $mergedText, [System.Text.UTF8Encoding]::new($false))
            Set-CurrentTask "CitizenFX.ini merged safely; existing FiveM settings preserved."
            Add-Log ("CitizenFX.ini merged safely: {0} updated, {1} added. Backup: {2}" -f $stats.Updated,$stats.Added,$backupPath) "#FFFFFF"
            Show-TweakToast -Label "CITIZENFX" -Enabled $true -OverrideText "CITIZENFX  /  SAFE MERGE COMPLETE" -DurationMs 3000
        } else {
            Set-CurrentTask "CitizenFX.ini is already up to date; no overwrite was needed."
            Add-Log "CitizenFX.ini already contains the requested settings; no overwrite performed." "#FFFFFF"
            Show-TweakToast -Label "CITIZENFX" -Enabled $true -OverrideText "CITIZENFX  /  ALREADY UP TO DATE" -DurationMs 2800
        }
        Start-Process -FilePath "notepad.exe" -ArgumentList @("`"$targetPath`"") -ErrorAction Stop
    } catch {
        $detail = $_.Exception.Message
        Set-CurrentTask "CitizenFX.ini update failed."
        Add-Log "CitizenFX.ini update failed: $detail" "#B8B8B8"
        Show-TweakToast -Label "CITIZENFX" -Enabled $false -OverrideText "CITIZENFX  /  UPDATE FAILED" -DurationMs 2800
        [System.Windows.MessageBox]::Show("ไม่สามารถเขียน CitizenFX.ini ได้:`n$detail","CITIZENFX",[System.Windows.MessageBoxButton]::OK,[System.Windows.MessageBoxImage]::Error) | Out-Null
    }
}
$BtnCitizenFX.Add_Click({ Play-UiBeep; Update-CitizenFXIni })
$BtnRamCleaner.Add_Click({
    Play-UiBeep
    $BtnRamCleaner.IsEnabled=$false
    try {
        $cleaned=[bool](Run-StandbyClean)
        if($CurrentTask){ if($cleaned){ $CurrentTask.Text="RAMMAP CLEAN COMPLETED" } else { $CurrentTask.Text="RAMMAP CLEAN FAILED" } }
        Show-RamCleanerToast -Success $cleaned
