function Set-TweakResult {
    param([string]$Key,[string]$Status,[string]$Message="",[bool]$Changed=$false,[bool]$RequiresReboot=$false)
    if(-not $Global:TweakResults){ $Global:TweakResults=@{} }
    $Global:TweakResults[$Key]=[ordered]@{Key=$Key;Status=$Status;Message=$Message;Changed=$Changed;RequiresReboot=$RequiresReboot;Utc=([DateTime]::UtcNow.ToString("o"))}
    return $Global:TweakResults[$Key]
}
function Invoke-CheckedNativeCommand {
    param([string]$Key,[string]$FilePath,[string[]]$ArgumentList)
    try {
        $output=& $FilePath @ArgumentList 2>&1
        $code=[int]$LASTEXITCODE
        if($code -ne 0){
            $detail=([string]($output -join " ")).Trim()
            if($detail.Length -gt 260){ $detail=$detail.Substring(0,260) }
            Set-TweakResult $Key "Failed" "$FilePath exited with code $code. $detail" | Out-Null
            return $false
        }
        return $true
    } catch {
        Set-TweakResult $Key "Failed" "$FilePath failed: $($_.Exception.Message)" | Out-Null
        return $false
    }
}

function Set-RegValue{
    param($Path,$Name,$Value,$Type="DWord")
    try{
        if(-not(Test-Path -LiteralPath $Path)){New-Item -Path $Path -Force -EA Stop|Out-Null}
        
        
        
        $current = Get-ItemProperty -LiteralPath $Path -Name $Name -EA SilentlyContinue
        if($null -eq $current -or $null -eq $current.PSObject.Properties[$Name]){
            New-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -PropertyType $Type -Force -EA Stop|Out-Null
        } else {
            Set-ItemProperty -LiteralPath $Path -Name $Name -Value $Value -Force -EA Stop|Out-Null
        }
        
        $check = (Get-ItemProperty -LiteralPath $Path -Name $Name -EA SilentlyContinue).$Name
        if($null -ne $check -and $check.ToString() -eq $Value.ToString()){ return $true }
        throw "Registry write verification failed: $Path\$Name"
    } catch {
        throw "Registry write failed [$Path\$Name]: $($_.Exception.Message)"
    }
}
function Get-RegValue{param($Path,$Name);try{return(Get-ItemProperty -Path $Path -Name $Name -EA Stop).$Name}catch{return $null}}
function Save-Orig{param($key,$path,$name);if(-not $Global:Orig.ContainsKey($key)){$Global:Orig[$key]=@{Path=$path;Name=$name;Value=(Get-RegValue $path $name)}}}





function Invoke-DedupedGlobalTweak{
    param([string]$BaseKey, $ToggleKey, [scriptblock]$Action)
    if(-not $Global:AppliedKeys[$BaseKey]){
        & $Action
        $Global:AppliedKeys[$BaseKey]=$true
    } else {
        Add-Log "Already applied via the other toggle sharing this setting - skipped duplicate write" "#A0A0A0"
    }
    if($ToggleKey -and $ToggleKey -ne $BaseKey){ $Global:AppliedKeys[$ToggleKey]=$true }
}
function Save-OrigService{
    param($key,[string]$serviceName)
    if($Global:OrigServices.ContainsKey($key)){return}
    
    foreach($saved in @($Global:OrigServices.Values)){
        if($saved.ServiceName -and ([string]$saved.ServiceName).Equals($serviceName,[System.StringComparison]::OrdinalIgnoreCase)){ return }
    }
    try{
        $svc=Get-Service -Name $serviceName -EA Stop
        $startType=(Get-CimInstance Win32_Service -Filter "Name='$serviceName'" -EA SilentlyContinue).StartMode
        $Global:OrigServices[$key]=@{ServiceName=$serviceName;Status=$svc.Status.ToString();StartType=$startType}
    } catch { $Global:OrigServices[$key]=@{ServiceName=$serviceName;Status=$null;StartType=$null} }
}
function Restore-OrigService{
    param($info)
    try{
        $name=$info.ServiceName
        if(-not $name){return}
        $st=$info.StartType
        $wasRunning=($info.Status -eq "Running")
        if($st){
            $mapped = switch($st){"Auto"{"Automatic"};"Manual"{"Manual"};"Disabled"{"Disabled"};default{"Manual"}}
            Set-Service -Name $name -StartupType $mapped -EA SilentlyContinue
        }
        if($wasRunning){ Start-Service -Name $name -EA SilentlyContinue }
    } catch {}
}
$Global:IsCancelled=$false
function Update-Progress{
    param([int]$done,[int]$total)
    $window.Dispatcher.Invoke([Action]{
        if($total -gt 0){
            $pct=[math]::Round(($done/$total)*100)
            $ProgressPct.Text="$pct%"
            $maxW=$ProgressFill.Parent.ActualWidth; if($maxW -le 0){$maxW=242}
            $ProgressFill.Width=[math]::Max(0,($pct/100.0)*$maxW)
        }
    })
    
    $window.Dispatcher.Invoke([Action]{}, [System.Windows.Threading.DispatcherPriority]::Background) | Out-Null
}
function Set-StatusRunning{$Global:TweakRunBusy=$true;$window.Dispatcher.Invoke([Action]{$StatusText.Text="RUNNING";$StatusDotE.Fill=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0xA8,0xA8,0xA8));$BtnRun.IsEnabled=$false})}
function Set-StatusDone{$Global:TweakRunBusy=$false;$window.Dispatcher.Invoke([Action]{$StatusText.Text="DONE";$StatusDotE.Fill=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0xD0,0xD0,0xD0));$BtnRun.IsEnabled=$true}); Play-CompletionChime}
function Set-StatusIssues{$Global:TweakRunBusy=$false;$window.Dispatcher.Invoke([Action]{$StatusText.Text="ISSUES";$StatusDotE.Fill=[System.Windows.Media.SolidColorBrush]::new([System.Windows.Media.Color]::FromRgb(0xB8,0xB8,0xB8));$BtnRun.IsEnabled=$true}); Play-IssueTone}
function Set-CurrentTask {
    param([string]$msg)
    $window.Dispatcher.Invoke([Action]{
        if($CurrentTask){ $CurrentTask.Text=$msg }
        if($FooterNoticeText){ $FooterNoticeText.Text=$msg }
    })
}

function Run-NetThrottle{
    param($ToggleKey)
    Set-CurrentTask "Network Throttling -> Absolute Max"
    Invoke-DedupedGlobalTweak "NetThrottle" $ToggleKey {
        $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
        Save-Orig "NetThrottle" $p "NetworkThrottlingIndex"
        $s1 = Set-RegValue $p "NetworkThrottlingIndex" 0xFFFFFFFF
        $s2 = Set-RegValue $p "SystemResponsiveness" 0
        if($s1 -and $s2){ Add-Log "Network throttling disabled" "#FFFFFF" }
        else { Add-Log "Network throttling tweak partially failed" "#D8D8D8" }
    }
}
function Run-BcdTimer{Set-CurrentTask "BCD Timer Tweaks";try{Save-OrigBcd "BcdTimer" "useplatformtick";Save-OrigBcd "BcdTimer" "disabledynamictick";$null=bcdedit /set useplatformtick yes 2>&1;$e1=$LASTEXITCODE;$null=bcdedit /set disabledynamictick yes 2>&1;$e2=$LASTEXITCODE;if($e1 -ne 0 -or $e2 -ne 0){throw "bcdedit failed (useplatformtick=$e1, disabledynamictick=$e2)"};Add-Log "BCD timer tweaks applied (reboot)" "#FFFFFF";$Global:AppliedKeys["BcdTimer"]=$true}catch{Add-Log "BCD tweaks skipped: $_" "#D8D8D8"}}
function Run-TcpGlobal{
    param($ToggleKey)
    Set-CurrentTask "TCP Global Stack Overhaul -> Aggressive"
    try{
        $ecnMode=if($Global:TweakToggles["NET_ECN"]){"disabled"}else{"enabled"}
        Invoke-DedupedGlobalTweak "TcpGlobal" $ToggleKey {
            
            $baseOutput=& netsh int tcp set global autotuninglevel=normal rss=enabled ecncapability=$ecnMode fastopen=enabled fastopenfallback=enabled congestionprovider=ctcp 2>&1
            if($LASTEXITCODE -ne 0){ throw "netsh returned exit code $LASTEXITCODE" }
            
            
            $rscOutput=& netsh int tcp set global rsc=enabled 2>&1
            if($LASTEXITCODE -ne 0){ Add-Log "RSC enable not supported by this Windows/NIC build - kept system default" "#A0A0A0" }
            
            
            $optionalOutput=& netsh int tcp set global maxsynretransmissions=3 hystart=enabled prr=enabled 2>&1
            if($LASTEXITCODE -ne 0){ Add-Log "Optional TCP loss-recovery knobs unavailable - base profile applied" "#A0A0A0" }
            Add-Log "Aggressive TCP profile applied: RSS + autotuning + Fast Open + CTCP (ECN: $ecnMode)" "#FFFFFF"
        }
    } catch { Add-Log "TCP global failed: $_" "#D8D8D8" }
}
function Run-KbQueue{Set-CurrentTask "Keyboard Queue Size -> 10";$p="HKLM:\SYSTEM\CurrentControlSet\Services\kbdclass\Parameters";Save-Orig "KbQueue" $p "KeyboardDataQueueSize";Set-RegValue $p "KeyboardDataQueueSize" 10|Out-Null;Add-Log "Keyboard queue -> 10" "#FFFFFF";$Global:AppliedKeys["KbQueue"]=$true}
function Run-NduDisable{param($ToggleKey);Set-CurrentTask "Ndu Driver -> Disabled";Invoke-DedupedGlobalTweak "NduDisable" $ToggleKey {$p="HKLM:\SYSTEM\CurrentControlSet\Services\Ndu";Save-Orig "NduDisable" $p "Start";Set-RegValue $p "Start" 4|Out-Null;Add-Log "Ndu driver disabled" "#FFFFFF"}}
function Run-GamingMemory{Set-CurrentTask "Gaming Memory Mode";try{Save-OrigService "GamingMemory" "SysMain";Stop-Service SysMain -Force -EA SilentlyContinue;Set-Service SysMain -StartupType Disabled -EA SilentlyContinue;Add-Log "Gaming memory mode enabled" "#FFFFFF";$Global:AppliedKeys["GamingMemory"]=$true}catch{Add-Log "Gaming memory partial" "#FFFFFF"}}
function Run-FiveMBooster{Set-CurrentTask "FiveM Booster";$p=Get-Process -Name "FiveM*" -EA Ignore|Select -First 1;if($p){$p.PriorityClass="High";Add-Log "FiveM boosted to High priority" "#FFFFFF"}else{Add-Log "FiveM not running - skipped" "#FFFFFF"};$Global:AppliedKeys["FiveMBooster"]=$true}

function Run-FiveMPerfOptions{
    Set-CurrentTask "FiveM_GTAProcess.exe -> CpuPriorityClass 3 (IFEO)"
    $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Image File Execution Options\FiveM_GTAProcess.exe\PerfOptions"
    Save-Orig "GM_FiveMPerfOptions" $p "CpuPriorityClass"
    Set-RegValue $p "CpuPriorityClass" 3|Out-Null
    Add-Log "FiveM_GTAProcess.exe CpuPriorityClass set to 3 (Normal) via IFEO" "#FFFFFF"
    $Global:AppliedKeys["GM_FiveMPerfOptions"]=$true
}
function Run-FiveMCoreAffinity{
    Set-CurrentTask "FiveM Core Affinity -> Auto-Optimized"
    try{
        $logical=[Environment]::ProcessorCount
        if($logical -le 2){
            Add-Log "Only $logical logical cores detected - skipping affinity change (not enough cores to spare)" "#FFFFFF"
            $Global:AppliedKeys["GM_FiveMCoreAffinity"]=$true
            return
        }
        
        $maxCores=[Math]::Min($logical-1,6)
        $mask=0
        for($i=1;$i -le $maxCores;$i++){ $mask=$mask -bor (1 -shl $i) }
        $procs=Get-Process -Name "FiveM_GTAProcess","FiveM" -EA Ignore
        if($procs){
            foreach($proc in $procs){
                try{ $proc.ProcessorAffinity=[IntPtr]$mask; Add-Log "$($proc.ProcessName) affinity set to cores 1-$maxCores (mask 0x$($mask.ToString('X')))" "#FFFFFF" }catch{ Add-Log "Could not set affinity for $($proc.ProcessName): $_" "#D8D8D8" }
            }
        } else {
            Add-Log "FiveM not running yet - will auto-apply as soon as it starts (watching for 10 min)" "#FFFFFF"
            $affinityJob = Start-Job -ScriptBlock {
                param($mask)
                $deadline=(Get-Date).AddMinutes(10)
                while((Get-Date) -lt $deadline){
                    $proc=Get-Process -Name "FiveM_GTAProcess","FiveM" -EA Ignore|Select -First 1
                    if($proc){ try{ $proc.ProcessorAffinity=[IntPtr]$mask }catch{}; break }
                    Start-Sleep -Seconds 5
                }
            } -ArgumentList $mask
            
            if(-not $Global:BackgroundJobs){ $Global:BackgroundJobs=[System.Collections.ArrayList]::new() }
            [void]$Global:BackgroundJobs.Add($affinityJob)
        }
        $Global:AppliedKeys["GM_FiveMCoreAffinity"]=$true
    } catch { Add-Log "FiveM core affinity error: $_" "#D8D8D8" }
}
function Run-KillerFix{
    Set-CurrentTask "Killer NIC Traffic Analysis -> Disabled"
    try{
        
        
        
        $killerSvcs=Get-CimInstance Win32_Service -Filter "Name LIKE '%Killer%'" -EA SilentlyContinue | Where-Object { $_.ServiceType -notmatch "Kernel|FileSystem" }
        if($killerSvcs){
            foreach($svc in $killerSvcs){
                Save-OrigService "NET_KillerFix_$($svc.Name)" $svc.Name
                Stop-Service -Name $svc.Name -Force -EA SilentlyContinue
                Set-Service -Name $svc.Name -StartupType Disabled -EA SilentlyContinue
                Add-Log "Killer service disabled: $($svc.DisplayName)" "#FFFFFF"
            }
        } else {
            Add-Log "No Killer NIC detected - skipped" "#A0A0A0"
        }
        $Global:AppliedKeys["NET_KillerFix"]=$true
    } catch { Add-Log "Killer NIC check failed: $_" "#D8D8D8" }
}
function Run-FiveMQos{
    Set-CurrentTask "FiveM Traffic -> QoS Priority Tag"
    try{
        
        
        $p="HKLM:\SOFTWARE\Policies\Microsoft\Windows\QoS"
        Save-Orig "NET_FiveMQos_NLA" $p "DoNotUseNLA"
        Set-RegValue $p "DoNotUseNLA" 1|Out-Null

        $created=@()
        foreach($procName in @("FiveM.exe","FiveM_GTAProcess.exe")){
            $polName="LessProject FiveM Priority - $procName"
            try{
                Get-NetQosPolicy -Name $polName -EA SilentlyContinue | Remove-NetQosPolicy -Confirm:$false -EA SilentlyContinue
                New-NetQosPolicy -Name $polName -AppPathNameMatchCondition $procName -DSCPAction 46 -NetworkProfile All -EA Stop | Out-Null
                $created+=$polName
                Add-Log "QoS priority tag applied: $procName" "#FFFFFF"
            } catch { Add-Log "QoS policy for $procName skipped: $_" "#FFFFFF" }
        }
        if($created.Count -gt 0){ $Global:OrigMisc["NET_FiveMQos_Policies"]=@{Type="NetQosPolicy";Names=@($created)} }
        $Global:AppliedKeys["NET_FiveMQos"]=$true
    } catch { Add-Log "FiveM QoS setup failed: $_" "#D8D8D8" }
}
function Run-FiveMFirewall{
    Set-CurrentTask "FiveM -> Explicit Firewall Allow Rule"
    try{
        $procs=Get-Process -Name "FiveM","FiveM_GTAProcess" -EA Ignore | Where-Object { $_.Path }
        if(-not $procs){
            Add-Log "FiveM not running - firewall rule skipped" "#FFFFFF"
            $Global:AppliedKeys["NET_FiveMFirewall"]=$true
            return
        }
        $created=@()
        $seenPaths=@{}
        foreach($proc in $procs){
            $path=$proc.Path
            if(-not $path -or $seenPaths.ContainsKey($path)){ continue }
            $seenPaths[$path]=$true
            $ruleName="LessProject - FiveM Allow ($($proc.ProcessName))"
            if(-not (Get-NetFirewallRule -DisplayName $ruleName -EA SilentlyContinue)){
                try{
                    New-NetFirewallRule -DisplayName $ruleName -Direction Inbound -Action Allow -Program $path -Profile Any -EA Stop | Out-Null
                    New-NetFirewallRule -DisplayName "$ruleName (Out)" -Direction Outbound -Action Allow -Program $path -Profile Any -EA Stop | Out-Null
                    $created+=$ruleName; $created+="$ruleName (Out)"
                    Add-Log "Firewall allow rule added: $($proc.ProcessName)" "#FFFFFF"
                } catch { Add-Log "Firewall rule for $($proc.ProcessName) skipped: $_" "#FFFFFF" }
            }
        }
        if($created.Count -gt 0){ $Global:OrigMisc["NET_FiveMFirewall_Rules"]=@{Type="FirewallRule";Names=@($created)} }
        $Global:AppliedKeys["NET_FiveMFirewall"]=$true
    } catch { Add-Log "FiveM firewall rule failed: $_" "#D8D8D8" }
}
function Run-DriverHealth{Set-CurrentTask "Driver Health Check";try{$bad=Get-CimInstance Win32_PnPEntity -EA SilentlyContinue|Where-Object{$_.ConfigManagerErrorCode -ne 0};if($bad){foreach($d in $bad){Add-Log "Problem: $($d.Name)" "#D8D8D8"}}else{Add-Log "All drivers OK" "#FFFFFF"};$Global:AppliedKeys["DriverHealth"]=$true}catch{Add-Log "Driver check skipped" "#FFFFFF"}}
function Get-AdapterNumericMaximum {
    param([object]$Property)
    $numbers=@()
    foreach($v in @($Property.DisplayValueTable)){
        $s=[string]$v
        if($s -match "(?<![0-9])(\d+)(?![0-9])"){
            try{ $numbers += [int64]$matches[1] }catch{}
        }
    }
    if($numbers.Count -gt 0){ return [string](($numbers | Measure-Object -Maximum).Maximum) }
    return $null
}
function Run-NicBuffers{
    Set-CurrentTask "NIC Receive/Transmit Buffers -> Maximum"
    try{
        $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up"})
        $changed=0
        foreach($adapter in $adapters){
            $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Receive Buffers|Transmit Buffers|Receive Buffer|Transmit Buffer"})
            foreach($prop in $props){
                $maxValue=Get-AdapterNumericMaximum $prop
                $values=@()
                if($maxValue){ $values+=$maxValue }
                $values+="Maximum"; $values+="Max"
                if(Set-ExtendedAdapterProperty "NET_NicBuffers" $adapter $prop $values){ $changed++ }
            }
        }
        Add-Log "NIC buffer maximum requested on $changed adapter setting(s) (unsupported values skipped)" "#FFFFFF"
        $Global:AppliedKeys["NET_NicBuffers"]=$true
    } catch { Add-Log "NIC buffer profile skipped: $($_.Exception.Message)" "#D8D8D8" }
}
function Run-NetworkSpeedTest{
    Set-CurrentTask "Network Speed Test -> Ping / Download / Upload"
    try{
        $pingMs=$null
        try{
            $reply=Test-Connection -ComputerName "1.1.1.1" -Count 3 -ErrorAction Stop | Measure-Object -Property ResponseTime -Average
            if($reply.Average){$pingMs=[math]::Round([double]$reply.Average,1)}
        }catch{}
        $downloadMbps=$null
        try{
            $uri="https://speed.cloudflare.com/__down?bytes=10000000"
            $sw=[Diagnostics.Stopwatch]::StartNew()
            $response=Invoke-WebRequest -Uri $uri -UseBasicParsing -TimeoutSec 30 -ErrorAction Stop
            $sw.Stop()
            $bytes=if($response.RawContentLength -gt 0){[double]$response.RawContentLength}else{[double]([Text.Encoding]::UTF8.GetByteCount([string]$response.Content))}
            if($sw.Elapsed.TotalSeconds -gt 0){$downloadMbps=[math]::Round(($bytes*8/1MB)/$sw.Elapsed.TotalSeconds,2)}
        }catch{}
        $uploadMbps=$null
        try{
            $payload=New-Object byte[] (2MB)
            (New-Object System.Random).NextBytes($payload)
            $sw=[Diagnostics.Stopwatch]::StartNew()
            Invoke-WebRequest -Uri "https://speed.cloudflare.com/__up" -Method Post -Body $payload -ContentType "application/octet-stream" -TimeoutSec 30 -UseBasicParsing -ErrorAction Stop | Out-Null
            $sw.Stop()
            if($sw.Elapsed.TotalSeconds -gt 0){$uploadMbps=[math]::Round(($payload.Length*8/1MB)/$sw.Elapsed.TotalSeconds,2)}
        }catch{}
        $pingText=if($null -ne $pingMs){"{0} ms" -f $pingMs}else{"N/A"}
        $downText=if($null -ne $downloadMbps){"{0} Mbps" -f $downloadMbps}else{"N/A"}
        $upText=if($null -ne $uploadMbps){"{0} Mbps" -f $uploadMbps}else{"N/A"}
        Add-Log ("SPEED TEST RESULT: Ping={0}; Download={1}; Upload={2}" -f $pingText,$downText,$upText) "#FFFFFF"
        $Global:AppliedKeys["NET_SpeedTest"]=$true
    } catch { Add-Log "Speed Test failed: $($_.Exception.Message)" "#D8D8D8" }
}
function Run-ReleaseRenewIp{
    Set-CurrentTask "Release / Renew IP Address"
    try{
        $release=@(ipconfig /release 2>&1);$releaseCode=[int]$LASTEXITCODE
        foreach($line in $release){if(-not [string]::IsNullOrWhiteSpace([string]$line)){Add-Log ("[Release IP] " + [string]$line) "#A0A0A0"}}
        $renew=@(ipconfig /renew 2>&1);$renewCode=[int]$LASTEXITCODE
        foreach($line in $renew){if(-not [string]::IsNullOrWhiteSpace([string]$line)){Add-Log ("[Renew IP] " + [string]$line) "#A0A0A0"}}
        if($releaseCode -eq 0 -and $renewCode -eq 0){Add-Log "IP address released and renewed successfully" "#FFFFFF";return $true}
        Add-Log ("IP release/renew completed with errors (release={0}, renew={1})" -f $releaseCode,$renewCode) "#D8D8D8";return $false
    }catch{Add-Log ("IP release/renew failed: " + $_.Exception.Message) "#D8D8D8";return $false}
}
