function Get-BestDnsPair{
    $providers=@(
        [pscustomobject]@{Name="Cloudflare";Primary="1.1.1.1";Secondary="1.0.0.1"},
        [pscustomobject]@{Name="Google";Primary="8.8.8.8";Secondary="8.8.4.4"},
        [pscustomobject]@{Name="Quad9";Primary="9.9.9.9";Secondary="149.112.112.112"}
    )
    $best=$null; $bestMs=[double]::PositiveInfinity
    foreach($provider in $providers){
        try{
            $elapsed=Measure-Command { Resolve-DnsName -Name "example.com" -Server $provider.Primary -Type A -DnsOnly -QuickTimeout -EA Stop | Select-Object -First 1 | Out-Null }
            if($elapsed.TotalMilliseconds -lt $bestMs){ $bestMs=$elapsed.TotalMilliseconds; $best=$provider }
        } catch { }
    }
    if(-not $best){ $best=$providers[0]; $bestMs=-1 }
    return [pscustomobject]@{Name=$best.Name;Primary=$best.Primary;Secondary=$best.Secondary;Milliseconds=[math]::Round($bestMs,1)}
}
function Run-NetworkMtu{
    param([ValidateSet("LAN","WI-FI")][string]$Target)
    Set-CurrentTask ("{0} MTU -> 1500 Bytes" -f $Target)
    try{
        $adapters=@(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object {$_.Status -eq "Up" -and (if($Target -eq "LAN"){$_.InterfaceDescription -notmatch "Wi-Fi|Wireless"}else{$_.InterfaceDescription -match "Wi-Fi|Wireless"})})
        $changed=0
        foreach($adapter in $adapters){
            $interfaces=@(Get-NetIPInterface -InterfaceIndex $adapter.IfIndex -AddressFamily IPv4 -ErrorAction SilentlyContinue)
            foreach($iface in $interfaces){
                $id="IPInterfaceMtu::$($iface.InterfaceIndex)::$($iface.AddressFamily)"
                if(-not $Global:OrigMisc.ContainsKey($id)){$Global:OrigMisc[$id]=@{Type="IPInterfaceMtu";InterfaceIndex=[int]$iface.InterfaceIndex;AddressFamily=[int]$iface.AddressFamily;NlMtuBytes=[int]$iface.NlMtuBytes}}
                try{Set-NetIPInterface -InterfaceIndex $iface.InterfaceIndex -AddressFamily IPv4 -NlMtuBytes 1500 -ErrorAction Stop;$changed++}catch{Add-Log ("MTU skipped on {0}: {1}" -f $adapter.Name,$_.Exception.Message) "#A0A0A0"}
            }
        }
        if($changed -gt 0){Add-Log ("{0} MTU set to 1500 bytes on {1} IPv4 interface(s)" -f $Target,$changed) "#FFFFFF"}else{Add-Log ("No active {0} adapter/interface available for MTU" -f $Target) "#A0A0A0"}
        $Global:AppliedKeys[(if($Target -eq "LAN"){"NET_LanMtu"}else{"NET_WifiMtu"})]=$true
    }catch{Add-Log ("{0} MTU tweak failed: {1}" -f $Target,$_.Exception.Message) "#D8D8D8"}
}
function Run-NetworkSpeedDuplex{
    param([ValidateSet("LAN","WI-FI")][string]$Target)
    Set-CurrentTask ("{0} Speed & Duplex -> Auto Negotiation" -f $Target)
    try{
        $adapters=@(Get-NetAdapter -Physical -ErrorAction SilentlyContinue | Where-Object {$_.Status -eq "Up" -and (if($Target -eq "LAN"){$_.InterfaceDescription -notmatch "Wi-Fi|Wireless"}else{$_.InterfaceDescription -match "Wi-Fi|Wireless"})})
        $changed=0
        $key=if($Target -eq "LAN"){"NET_LanSpeedDuplex"}else{"NET_WifiSpeedDuplex"}
        foreach($adapter in $adapters){
            $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -ErrorAction SilentlyContinue | Where-Object {$_.DisplayName -match "Speed.*Duplex|Duplex.*Speed"})
            foreach($prop in $props){if(Set-ExtendedAdapterProperty $key $adapter $prop @("Auto Negotiation","Auto","0")){$changed++}}
        }
        if($changed -gt 0){Add-Log ("{0} Speed & Duplex set to Auto Negotiation on {1} setting(s)" -f $Target,$changed) "#FFFFFF"}else{Add-Log ("{0} Speed & Duplex is not exposed by the active driver - skipped" -f $Target) "#A0A0A0"}
        $Global:AppliedKeys[$key]=$true
    }catch{Add-Log ("{0} Speed & Duplex tweak failed: {1}" -f $Target,$_.Exception.Message) "#D8D8D8"}
}
