        $pair=Get-BestDnsPair
        if($wa){
            $old=@(Get-DnsClientServerAddress -InterfaceIndex $wa.IfIndex -AddressFamily IPv4 -EA SilentlyContinue | Select-Object -ExpandProperty ServerAddresses)
            $Global:OrigMisc["DNS::WIFI::$($wa.IfIndex)"]=@{Type="DnsServerAddresses";InterfaceIndex=[int]$wa.IfIndex;AddressFamily=2;ServerAddresses=@($old);Reset=($old.Count -eq 0)}
            Set-DnsClientServerAddress -InterfaceIndex $wa.IfIndex -AddressFamily IPv4 -ServerAddresses @($pair.Primary,$pair.Secondary) -EA Stop
            Add-Log "Wi-Fi DNS auto-selected $($pair.Name): $($pair.Primary) / $($pair.Secondary)" "#FFFFFF"
        } else { Add-Log "No Wi-Fi adapter detected - skipped" "#A0A0A0" }
        $Global:AppliedKeys["NET_DnsFast_WiFi"]=$true
    } catch { Add-Log "DNS tweak (Wi-Fi) skipped" "#FFFFFF" }
}
