            if($s1 -and $s2 -and $s3 -and $s4){ $applied++ }
        }
        if($applied -gt 0){
            Add-Log "NVIDIA power mode set to Prefer Max Performance ($applied instance(s))" "#FFFFFF"
        } else {
            Add-Log "NVIDIA power mode could not be applied to any instance" "#D8D8D8"
        }
