function Run-StandbyClean{
    Set-CurrentTask "RAMMAP CLEAN: Purging Standby Memory"
    $successCount=0
    $failedNames=New-Object System.Collections.Generic.List[string]
    try{
        if(-not ("Win32MemPurgeNS.Win32MemPurge" -as [type])){
            Add-Type -Namespace Win32MemPurgeNS -Name Win32MemPurge -MemberDefinition @"
[DllImport("ntdll.dll")] public static extern int NtSetSystemInformation(int InfoClass, IntPtr Info, int Length);
"@
        }
        
        
        foreach($entry in @(@{Code=5;Name="Low-priority standby"},@{Code=4;Name="Standby"})){
            $ptr=[System.IntPtr]::Zero
            try{
                $ptr=[System.Runtime.InteropServices.Marshal]::AllocHGlobal(4)
                [System.Runtime.InteropServices.Marshal]::WriteInt32($ptr,[int]$entry.Code)
                $rc=[Win32MemPurgeNS.Win32MemPurge]::NtSetSystemInformation(80,$ptr,4)
                if($rc -ne 0){ throw ("NtSetSystemInformation returned 0x{0:X8}" -f ([uint32]$rc)) }
                $successCount++
                Add-Log ("RAMMAP CLEAN: {0} list cleared" -f $entry.Name) "#FFFFFF"
            } catch {
                [void]$failedNames.Add([string]$entry.Name)
                Add-Log ("RAMMAP CLEAN: {0} list skipped - {1}" -f $entry.Name,$_.Exception.Message) "#D8D8D8"
            } finally {
                if($ptr -ne [System.IntPtr]::Zero){ [System.Runtime.InteropServices.Marshal]::FreeHGlobal($ptr) }
            }
        }
        if($successCount -eq 0){ throw "No memory list could be purged. Run as Administrator." }
        $Global:AppliedKeys["GM_StandbyClean"]=$true
        if($failedNames.Count -gt 0){ Set-CurrentTask ("RAMMAP CLEAN completed partially: {0}/2 lists cleared" -f $successCount) }
        else { Set-CurrentTask "RAMMAP CLEAN completed: low-priority and standby lists cleared" }
        return $true
    } catch { Add-Log "RAMMAP CLEAN failed (needs admin): $($_.Exception.Message)" "#D8D8D8"; return $false }
}
