    Add-Log "SmartScreen app reputation check turned off" "#FFFFFF"
    $Global:AppliedKeys["SYS_NoSmartScreenCheck"]=$true
}
function Run-NoWER{
    Set-CurrentTask "Windows Error Reporting -> Disabled"
    try{
        Save-OrigService "CLEAN_NoWER" "WerSvc"
        Stop-Service WerSvc -Force -EA SilentlyContinue
        Set-Service WerSvc -StartupType Disabled -EA SilentlyContinue
        Add-Log "Windows Error Reporting service disabled" "#FFFFFF"
        $Global:AppliedKeys["CLEAN_NoWER"]=$true
    } catch { Add-Log "WER disable skipped" "#FFFFFF" }
}
function Run-NoPrintSpooler{
    Set-CurrentTask "Print Spooler -> Disabled"
    try{
        Save-OrigService "CLEAN_NoPrintSpooler" "Spooler"
        Stop-Service Spooler -Force -EA SilentlyContinue
        Set-Service Spooler -StartupType Disabled -EA SilentlyContinue
        Add-Log "Print Spooler disabled (printing will not work)" "#FFFFFF"
        $Global:AppliedKeys["CLEAN_NoPrintSpooler"]=$true
    } catch { Add-Log "Print Spooler disable skipped" "#FFFFFF" }
}
$Global:RecoverySelected = "restore"
$Global:RecoveryJob = $null
$Global:RecoveryPoller = $null
$Global:RestorePointCreated = $false
function Set-RecoverySelection {
    param([string]$Key)
    if([string]::IsNullOrWhiteSpace($Key)){ return }
    $Global:RecoverySelected=$Key
    $RecoveryRun.IsEnabled=$true
    $RecoveryRun.Content = switch($Key){
        "restore" { "RESTORE SAVED SETTINGS" }
        "network" { "RUN NETWORK REPAIR" }
        "windows" { "RUN WINDOWS FILE REPAIR" }
        "services" { "RESTORE SERVICES & TASKS" }
        "power" { "RESTORE POWER / BCD" }
        "diagnostics" { "EXPORT DIAGNOSTICS" }
        default { "RUN SELECTED" }
    }
}
function Show-RecoveryCenter {
    if(-not $RecoveryOverlay){ return }
    $hasSnapshot = (($Global:Orig.Count + $Global:OrigServices.Count + $Global:OrigMisc.Count) -gt 0)
    $RecoverySnapshotText.Text = if($hasSnapshot){ "READY" } else { "EMPTY" }
    $RecoverySnapshotText.Foreground = if($hasSnapshot){ [System.Windows.Media.BrushConverter]::new().ConvertFromString("#D0D0D0") } else { [System.Windows.Media.BrushConverter]::new().ConvertFromString("#B8B8B8") }
    if($Global:RestorePointCreated){ $RecoveryRestorePointText.Text="READY"; $RecoveryRestorePointText.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#D0D0D0") }
    else { $RecoveryRestorePointText.Text="SKIPPED"; $RecoveryRestorePointText.Foreground=[System.Windows.Media.BrushConverter]::new().ConvertFromString("#B8B8B8") }
    $RecoveryOverlay.Visibility="Visible"
    Set-RecoverySelection "restore"
    Set-CurrentTask "Recovery Center ready. Select a repair tool."
}
function Close-RecoveryCenter {
    if($RecoveryOverlay){ $RecoveryOverlay.Visibility="Collapsed" }
}
function Start-RecoveryJobAsync {
    param([string]$Title,[scriptblock]$Script,[object[]]$ArgumentList=@(),[int]$TimeoutSeconds=900)
    if($Global:RecoveryJob -and $Global:RecoveryJob.State -eq 'Running'){ Add-Log "A recovery task is already running." "#FFFFFF"; return }
    $RecoveryRun.IsEnabled=$false; $RecoveryClose.IsEnabled=$false; $RecoveryCloseX.IsEnabled=$false
    Set-StatusRunning; Set-CurrentTask "Running recovery: $Title..."; Add-Log "[RUNNING] Recovery: $Title" "#FFFFFF"
    if($ArgumentList -and $ArgumentList.Count -gt 0){ $Global:RecoveryJob=Start-Job -ArgumentList $ArgumentList -ScriptBlock $Script }
    else { $Global:RecoveryJob=Start-Job -ScriptBlock $Script }
    $Global:RecoveryStartedUtc=[DateTime]::UtcNow
    $Global:RecoveryPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:RecoveryPoller.Interval=[TimeSpan]::FromMilliseconds(350)
    $Global:RecoveryPoller.Add_Tick({
        if(-not $Global:RecoveryJob){ return }
        $age=([DateTime]::UtcNow-$Global:RecoveryStartedUtc).TotalSeconds
        if($Global:RecoveryJob.State -eq 'Running' -and $age -lt $Global:RecoveryTimeoutSeconds){ return }
        $Global:RecoveryPoller.Stop()
        $timedOut=($Global:RecoveryJob.State -eq 'Running')
        if($timedOut){ Stop-Job $Global:RecoveryJob -EA SilentlyContinue; Add-Log "[TIMEOUT] Recovery: $Title exceeded $($Global:RecoveryTimeoutSeconds)s." "#D8D8D8"; Set-CurrentTask "Recovery timed out. Check Live Log."; Set-StatusIssues }
        else {
            $result=@(Receive-Job $Global:RecoveryJob -Wait -AutoRemoveJob -EA SilentlyContinue)
            foreach($line in $result){ if($null -ne $line -and -not [string]::IsNullOrWhiteSpace([string]$line)){ Add-Log ([string]$line) "#D2D2D2" } }
            $failed=($Global:RecoveryJob.ChildJobs[0].JobStateInfo.State -eq 'Failed')
            if($failed){ Add-Log "[FAILED] Recovery: $Title" "#D8D8D8"; Set-CurrentTask "Recovery failed. Check Live Log."; Set-StatusIssues }
            else { Add-Log "[APPLIED] Recovery: $Title" "#FFFFFF"; Set-CurrentTask "Recovery complete. Restart Windows if requested."; Set-StatusDone }
        }
        Remove-Job $Global:RecoveryJob -Force -EA SilentlyContinue; $Global:RecoveryJob=$null
        $RecoveryRun.IsEnabled=$true; $RecoveryClose.IsEnabled=$true; $RecoveryCloseX.IsEnabled=$true
    }.GetNewClosure())
    $Global:RecoveryTimeoutSeconds=$TimeoutSeconds
    $Global:RecoveryPoller.Start()
}
function Export-RecoveryDiagnosticsAsync {
    $snapshot=@($Global:LogLines | ForEach-Object { [string]$_ })
    $diagScript={
        param($stateDir,$logLines,$os,$cpu,$gpu,$adapter)
        try {
            $reportDir=Join-Path $stateDir "Reports"; New-Item -ItemType Directory -Path $reportDir -Force | Out-Null
            $file=Join-Path $reportDir ("LessProject-Diagnostics-{0}.txt" -f (Get-Date -Format "yyyyMMdd-HHmmss"))
            $lines=@("LESS PROJECT DIAGNOSTICS","Generated: $(Get-Date -Format o)","OS: $os","CPU: $cpu","GPU: $gpu","Adapter: $adapter","","LIVE LOG") + @($logLines)
            $lines | Set-Content -LiteralPath $file -Encoding UTF8
            "Diagnostics report saved: $file"
        } catch { "Diagnostics export failed: $($_.Exception.Message)" }
    }
    Start-RecoveryJobAsync "Export diagnostics" $diagScript @($Global:StateDir,(,$snapshot),$Global:SysInfo.OS,$Global:SysInfo.CPU,$Global:SysInfo.GPU,$Global:SysInfo.Adapter) 60
}
function Invoke-RecoverySelection {
    switch([string]$Global:RecoverySelected){
        "restore" { Close-RecoveryCenter; Start-RestoreDefaultsAsync; return }
        "services" { Close-RecoveryCenter; Add-Log "Restoring tracked services and scheduled tasks..." "#FFFFFF"; Start-RestoreDefaultsAsync; return }
        "power" { Close-RecoveryCenter; Add-Log "Restoring tracked power and boot values..." "#FFFFFF"; Start-RestoreDefaultsAsync; return }
        "network" {
            $networkScript={
                $ErrorActionPreference="Continue"
                "Resetting Winsock..."; & netsh.exe winsock reset 2>&1 | ForEach-Object { [string]$_ }
                "Resetting TCP/IP..."; & netsh.exe int ip reset 2>&1 | ForEach-Object { [string]$_ }
                "Flushing DNS cache..."; & ipconfig.exe /flushdns 2>&1 | ForEach-Object { [string]$_ }
                "Network repair finished. A restart may be required."
            }
            Start-RecoveryJobAsync "Network repair" $networkScript @() 180; return
        }
        "windows" {
            $windowsScript={
                $ErrorActionPreference="Continue"
                "Checking Windows component store (DISM)..."; & DISM.exe /Online /Cleanup-Image /RestoreHealth 2>&1 | ForEach-Object { [string]$_ }
                "Checking protected system files (SFC)..."; & sfc.exe /scannow 2>&1 | ForEach-Object { [string]$_ }
                "Windows file repair finished. Review the output above."
            }
            Start-RecoveryJobAsync "Windows file repair" $windowsScript @() 1800; return
        }
        "diagnostics" { Export-RecoveryDiagnosticsAsync; return }
    }
}
foreach($recoveryButton in @($RecoveryRestore,$RecoveryNetwork,$RecoveryWindows,$RecoveryServices,$RecoveryPower,$RecoveryDiagnostics)){
    if($recoveryButton){ $recoveryButton.Add_Click({ param($sender,$args); Set-RecoverySelection ([string]$sender.Tag) }.GetNewClosure()) }
}
$RecoveryCloseX.Add_Click({ Close-RecoveryCenter })
$RecoveryClose.Add_Click({ Close-RecoveryCenter })
$RecoveryRun.Add_Click({ Invoke-RecoverySelection })

function Start-CreateRestorePointAsync {
    if($Global:RestorePointJob -and $Global:RestorePointJob.State -eq 'Running'){ return }
    $BtnCreateRestore.IsEnabled=$false; Set-CurrentTask "Creating a Windows restore point..."
    Add-Log "Creating System Restore Point in the background..." "#C2C2C2"
    $Global:RestorePointJob=Start-Job -ScriptBlock {
        try {
            Enable-ComputerRestore -Drive "$env:SystemDrive\" -EA SilentlyContinue
            Checkpoint-Computer -Description "LESS PROJECT - manual restore point" -RestorePointType "MODIFY_SETTINGS" -EA Stop
            'Restore point created successfully.'
        } catch { "Restore point failed: $_" }
    }
    $Global:RestorePointPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:RestorePointPoller.Interval=[TimeSpan]::FromMilliseconds(300)
    $Global:RestorePointPoller.Add_Tick({
        if($Global:RestorePointJob.State -eq 'Running'){ return }
        $Global:RestorePointPoller.Stop(); $result=Receive-Job $Global:RestorePointJob -Wait -AutoRemoveJob -EA SilentlyContinue
        $restoreText=($result -join ' '); Add-Log $restoreText "#FFFFFF"; if($restoreText -notmatch 'failed|error'){ $Global:RestorePointCreated=$true }; Set-CurrentTask "Restore point task finished."; $BtnCreateRestore.IsEnabled=$true
    }.GetNewClosure())
    $Global:RestorePointPoller.Start()
}
function Start-RestoreDefaultsAsync {
    if($Global:RestoreDefaultsJob -and $Global:RestoreDefaultsJob.State -eq 'Running'){ return }
    if($Global:Orig.Count -eq 0 -and $Global:OrigServices.Count -eq 0 -and $Global:OrigMisc.Count -eq 0){ Add-Log "No saved settings are available to restore." "#C5C5C5"; return }
    $answer=[System.Windows.MessageBox]::Show("Restore the saved registry and service settings from the last profile run?`n`nApp removals and cache cleanup cannot be undone.","LESS PROJECT - Restore Defaults",[System.Windows.MessageBoxButton]::YesNo,[System.Windows.MessageBoxImage]::Warning)
    if($answer -ne [System.Windows.MessageBoxResult]::Yes){ return }
    $BtnRestore.IsEnabled=$false; Set-CurrentTask "Restoring saved defaults in the background..."
    $savedRegistry=@($Global:Orig.Values); $savedServices=@($Global:OrigServices.Values); $savedMisc=@($Global:OrigMisc.Values)
    $Global:RestoreDefaultsJob=Start-Job -ArgumentList @(,$savedRegistry),(,$savedServices),(,$savedMisc) -ScriptBlock {
        param($registry,$services,$misc)
        $restored=0; $failed=0
        foreach($item in $registry){
            try { if($null -eq $item.Value){ Remove-ItemProperty -LiteralPath $item.Path -Name $item.Name -Force -EA SilentlyContinue } else { Set-ItemProperty -LiteralPath $item.Path -Name $item.Name -Value $item.Value -Force -EA Stop }; $restored++ } catch { $failed++ }
        }
        foreach($svc in $services){
            try { if($svc.StartType){ $type=switch($svc.StartType){'Auto'{'Automatic'};'Manual'{'Manual'};'Disabled'{'Disabled'};default{'Manual'}}; Set-Service -Name $svc.ServiceName -StartupType $type -EA SilentlyContinue }; if($svc.Status -eq 'Running'){Start-Service -Name $svc.ServiceName -EA SilentlyContinue}; $restored++ } catch { $failed++ }
        }
        foreach($item in $misc){
            
            
            $entries = @($item)
            foreach($entry in $entries){
                try {
                    if($entry.Type -eq 'PowerCfg'){
                        if($null -ne $entry.AC){ & powercfg /setacvalueindex SCHEME_CURRENT $entry.SubGroup $entry.Setting ([int]$entry.AC) 2>$null | Out-Null }
                        if($null -ne $entry.DC){ & powercfg /setdcvalueindex SCHEME_CURRENT $entry.SubGroup $entry.Setting ([int]$entry.DC) 2>$null | Out-Null }
                        & powercfg /setactive SCHEME_CURRENT 2>$null | Out-Null
                        $restored++
                    } elseif($entry.Type -eq 'BCD'){
                        if([bool]$entry.Exists -and $entry.Value){ & bcdedit /set $entry.Identifier $entry.Name $entry.Value 2>$null | Out-Null }
                        else { & bcdedit /deletevalue $entry.Identifier $entry.Name 2>$null | Out-Null }
                        $restored++
                    } elseif($entry.Type -eq 'AdapterProperty'){
                        Set-NetAdapterAdvancedProperty -Name $entry.AdapterName -DisplayName $entry.DisplayName -DisplayValue $entry.DisplayValue -EA Stop | Out-Null; $restored++
                    } elseif($entry.Type -eq 'IPInterfaceMtu'){
                        Set-NetIPInterface -InterfaceIndex $entry.InterfaceIndex -AddressFamily $entry.AddressFamily -NlMtuBytes ([int]$entry.NlMtuBytes) -EA Stop | Out-Null; $restored++
                    } elseif($entry.Type -eq 'ProcessPriorityBoost'){
                        $proc=Get-Process -Id ([int]$entry.ProcessId) -EA Stop
                        $proc.PriorityBoostEnabled=[bool]$entry.Enabled
                        $restored++
                    } elseif($entry.Type -eq 'DnsServerAddresses'){
                        if([bool]$entry.Reset){ Set-DnsClientServerAddress -InterfaceIndex $entry.InterfaceIndex -AddressFamily $entry.AddressFamily -ResetServerAddresses -EA Stop }
                        else { Set-DnsClientServerAddress -InterfaceIndex $entry.InterfaceIndex -AddressFamily $entry.AddressFamily -ServerAddresses @($entry.ServerAddresses) -EA Stop }
                        $restored++
                    } elseif($entry.Type -eq 'AdapterBinding'){
                        if([bool]$entry.Enabled){ Enable-NetAdapterBinding -Name $entry.AdapterName -ComponentID $entry.ComponentID -EA Stop | Out-Null }
                        else { Disable-NetAdapterBinding -Name $entry.AdapterName -ComponentID $entry.ComponentID -EA Stop | Out-Null }
                        $restored++
                    } elseif($entry.Type -eq 'PageFileMode'){
                        $cs=Get-CimInstance -ClassName Win32_ComputerSystem -EA Stop
                        Set-CimInstance -InputObject $cs -Property @{AutomaticManagedPagefile=[bool]$entry.AutomaticManagedPagefile} -EA Stop | Out-Null
                        $restored++
                    } elseif($entry.Type -eq 'ScheduledTask'){
                        if([bool]$entry.Enabled){ Enable-ScheduledTask -TaskPath $entry.TaskPath -TaskName $entry.TaskName -EA Stop | Out-Null } else { Disable-ScheduledTask -TaskPath $entry.TaskPath -TaskName $entry.TaskName -EA Stop | Out-Null }; $restored++
                    } elseif($entry.Type -eq 'NetQosPolicy'){
                        foreach($name in @($entry.Names)){ Remove-NetQosPolicy -Name $name -Confirm:$false -EA Stop | Out-Null; $restored++ }
                    } elseif($entry.Type -eq 'FirewallRule'){
                        foreach($name in @($entry.Names)){ Remove-NetFirewallRule -DisplayName $name -Confirm:$false -EA Stop | Out-Null; $restored++ }
                    } elseif($entry.Type -eq 'DefenderExclusion'){
                        foreach($path in @($entry.Paths)){ Remove-MpPreference -ExclusionPath $path -EA Stop; $restored++ }
                    } elseif($entry.Type -eq 'StartupEntries'){
                        foreach($startup in @($entry.Entries)){
                            if($null -eq $startup.Value){ Remove-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -Force -EA SilentlyContinue }
                            else {
                                $current=Get-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -EA SilentlyContinue
                                if($null -eq $current -or $null -eq $current.PSObject.Properties[$startup.Name]){ New-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -Value $startup.Value -PropertyType String -Force -EA Stop | Out-Null }
                                else { Set-ItemProperty -LiteralPath $startup.Path -Name $startup.Name -Value $startup.Value -Force -EA Stop }
                            }
                            $restored++
                        }
                    } elseif($entry.Path -and $entry.Name){
                        
                        if($null -eq $entry.Value){ Remove-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -Force -EA SilentlyContinue }
                        else { New-ItemProperty -LiteralPath $entry.Path -Name $entry.Name -Value $entry.Value -PropertyType String -Force -EA Stop | Out-Null }
                        $restored++
                    }
                } catch { $failed++ }
            }
        }
        "Restored $restored saved settings; skipped/failed $failed."
    }
    $Global:RestoreDefaultsPoller=New-Object System.Windows.Threading.DispatcherTimer
    $Global:RestoreDefaultsPoller.Interval=[TimeSpan]::FromMilliseconds(300)
    $Global:RestoreDefaultsPoller.Add_Tick({
        if($Global:RestoreDefaultsJob.State -eq 'Running'){ return }
        $Global:RestoreDefaultsPoller.Stop(); $result=Receive-Job $Global:RestoreDefaultsJob -Wait -AutoRemoveJob -EA SilentlyContinue
        Add-Log ($result -join ' ') "#FFFFFF"; Set-CurrentTask "Restore complete. Restart Windows if a restored setting requires it."; $BtnRestore.IsEnabled=$true
    }.GetNewClosure())
    $Global:RestoreDefaultsPoller.Start()
}
$BtnCreateRestore.Add_Click({ Start-CreateRestorePointAsync })
$BtnRestore.Add_Click({ Show-RecoveryCenter })

function Save-OrigAdapterProperty {
    param([string]$Key,[string]$AdapterName,[string]$DisplayName,[string]$DisplayValue)
    $id = "Adapter::$Key::$AdapterName::$DisplayName"
    if($Global:OrigMisc.ContainsKey($id)){ return }
    $Global:OrigMisc[$id] = @{ Type="AdapterProperty"; AdapterName=$AdapterName; DisplayName=$DisplayName; DisplayValue=$DisplayValue }
}
function Set-ExtendedAdapterProperty {
    param([string]$Key,[object]$Adapter,[object]$Property,[string[]]$Values)
    foreach($value in $Values){
        try {
            Save-OrigAdapterProperty $Key $Adapter.Name $Property.DisplayName $Property.DisplayValue
            Set-NetAdapterAdvancedProperty -Name $Adapter.Name -DisplayName $Property.DisplayName -DisplayValue $value -EA Stop | Out-Null
            return $true
        } catch { }
    }
    return $false
}
function Get-BcdCurrentValue {
    param([string]$Name)
    try {
        $lines=@(bcdedit /enum "{current}" 2>$null)
        foreach($line in $lines){
            if([string]$line -match "^\s*$([regex]::Escape($Name))\s+(.+?)\s*$"){ return [string]$matches[1] }
        }
    } catch {}
    return $null
}
function Save-OrigBcd {
    param([string]$Key,[string]$Name)
    $id="BCD::$Name"
    if(-not $Global:OrigMisc.ContainsKey($id)){
        $value=Get-BcdCurrentValue $Name
        $Global:OrigMisc[$id]=@{Type="BCD";Identifier="{current}";Name=$Name;Exists=($null -ne $value);Value=$value;Key=$Key}
    }
}
function Save-OrigPowerCfg {
    param([string]$Key,[string]$SubGroup,[string]$Setting)
    $id="PowerCfg::$SubGroup::$Setting"
    if($Global:OrigMisc.ContainsKey($id)){ return }
    $ac=$null; $dc=$null
    try {
        $lines=@(powercfg /query SCHEME_CURRENT $SubGroup $Setting 2>$null)
        foreach($line in $lines){
            if([string]$line -match "Current AC Power Setting Index:\s+0x([0-9A-Fa-f]+)"){ $ac=[Convert]::ToInt32($matches[1],16) }
            if([string]$line -match "Current DC Power Setting Index:\s+0x([0-9A-Fa-f]+)"){ $dc=[Convert]::ToInt32($matches[1],16) }
        }
    } catch {}
    $Global:OrigMisc[$id]=@{Type="PowerCfg";Key=$Key;SubGroup=$SubGroup;Setting=$Setting;AC=$ac;DC=$dc}
}
function Run-ExtendedGamingTweak {
    param([string]$ToggleKey)
    try {
        switch($ToggleKey){
            "BCD_UsePlatformClockOff" {
                Set-CurrentTask "BCDEdit -> Platform Clock Off"
                Save-OrigBcd $ToggleKey "useplatformclock"
                $null=bcdedit /set "{current}" useplatformclock false 2>&1
                if($LASTEXITCODE -ne 0){ throw "bcdedit failed for useplatformclock (exit $LASTEXITCODE)" }
                Add-Log "BCDEdit useplatformclock=false applied (reboot required; Advanced)" "#FFFFFF"
            }
            "BCD_DisableDynamicTick" {
                Set-CurrentTask "BCDEdit -> Dynamic Tick Off"
                Save-OrigBcd $ToggleKey "disabledynamictick"
                $null=bcdedit /set "{current}" disabledynamictick yes 2>&1
                if($LASTEXITCODE -ne 0){ throw "bcdedit failed for disabledynamictick (exit $LASTEXITCODE)" }
                Add-Log "BCDEdit disabledynamictick=yes applied (reboot required; Advanced)" "#FFFFFF"
            }
            "BCD_TscSyncPolicy" {
                Set-CurrentTask "BCDEdit -> TSC Sync Enhanced"
                Save-OrigBcd $ToggleKey "tscsyncpolicy"
                $null=bcdedit /set "{current}" tscsyncpolicy Enhanced 2>&1
                if($LASTEXITCODE -ne 0){ throw "bcdedit failed for tscsyncpolicy (exit $LASTEXITCODE)" }
                Add-Log "BCDEdit tscsyncpolicy=Enhanced applied (reboot required; Advanced)" "#FFFFFF"
            }
            "SYS_MMCSSSystemResponsiveness" {
                Set-CurrentTask "MMCSS System Responsiveness -> 0"
                $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile"
                Save-Orig "SYS_MMCSSSystemResponsiveness" $p "SystemResponsiveness"
                Set-RegValue $p "SystemResponsiveness" 0 | Out-Null
                Add-Log "MMCSS SystemResponsiveness set to 0 (Advanced; restorable)" "#FFFFFF"
            }
            "NET_RSC" {
                Set-CurrentTask "RSC Packet Coalescing -> Disabled"
                netsh int tcp set global rsc=disabled 2>&1 | Out-Null
                Add-Log "RSC disabled to reduce packet batching latency (reboot/network reset may be required)" "#FFFFFF"
            }
            "NET_ECN" {
                Set-CurrentTask "ECN -> Disabled"
                netsh int tcp set global ecncapability=disabled 2>&1 | Out-Null
                Add-Log "ECN disabled for router compatibility" "#FFFFFF"
            }
            "NET_FastOpen" {
                Set-CurrentTask "TCP Fast Open -> Enabled"
                netsh int tcp set global fastopen=enabled fastopenfallback=enabled 2>&1 | Out-Null
                Add-Log "TCP Fast Open and fallback enabled" "#FFFFFF"
            }
            "NET_TaskOffload" {
                Set-CurrentTask "TCP Task Offload / LSO -> Disabled"
                $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up"})
                $changed=0
                foreach($adapter in $adapters){
                    $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Large Send Offload.*(IPv4|IPv6)|LSO"})
                    foreach($prop in $props){ if(Set-ExtendedAdapterProperty $ToggleKey $adapter $prop @("Disabled","Off")){ $changed++ } }
                }
                Add-Log "Large Send Offload disabled on $changed NIC setting(s)" "#FFFFFF"
            }
            "NET_TCPParameters" {
                Set-CurrentTask "TCP Parameters -> Low-Latency Profile"
                $p="HKLM:\SYSTEM\CurrentControlSet\Services\Tcpip\Parameters"
                Save-Orig "NET_TCPParameters_Timestamps" $p "Tcp1323Opts"
                Save-Orig "NET_TCPParameters_PMTU" $p "EnablePMTUDiscovery"
                Set-RegValue $p "Tcp1323Opts" 1 | Out-Null
                Set-RegValue $p "EnablePMTUDiscovery" 1 | Out-Null
                Add-Log "TCP timestamps and path-MTU discovery enabled" "#FFFFFF"
            }
            "NET_FlowControlStable" {
                Set-CurrentTask "LAN Flow Control -> Driver Default/Enabled"
                $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up" -and $_.InterfaceDescription -notmatch "Wi-Fi|Wireless"})
                $changed=0
                foreach($adapter in $adapters){
                    $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Flow Control"})
                    foreach($prop in $props){
                        if(Set-ExtendedAdapterProperty $ToggleKey $adapter $prop @("Rx & Tx Enabled","Enabled","Auto")){ $changed++ }
                    }
                }
                Add-Log "LAN flow-control stability profile requested on $changed setting(s) (unsupported values skipped)" "#FFFFFF"
            }
            "FIVEM_SessionServices" {
                Set-CurrentTask "FiveM Session -> Pause Optional Services"
                $services=@("WSearch","DiagTrack","WerSvc","DoSvc")
                $changed=0
                foreach($name in $services){
                    try{
                        $svc=Get-Service -Name $name -EA Stop
                        if($svc.Status -eq "Running"){
                            Save-OrigService "FIVEM_SessionServices::$name" $name
                            Stop-Service -Name $name -Force -EA Stop
                            $changed++
                        } else { Add-Log "$name already stopped - skipped" "#A0A0A0" }
                    } catch { Add-Log "$name unavailable or protected - skipped" "#A0A0A0" }
                }
                Add-Log "FiveM session profile paused $changed optional service(s); startup types were not changed" "#FFFFFF"
            }
            "NIC_EnergyEfficientEthernet" {
                Set-CurrentTask "NIC Energy Efficient Ethernet -> Off"
                $adapters=@(Get-NetAdapter -Physical -EA SilentlyContinue | Where-Object {$_.Status -eq "Up"})
                $changed=0
                foreach($adapter in $adapters){
                    $props=@(Get-NetAdapterAdvancedProperty -Name $adapter.Name -EA SilentlyContinue | Where-Object {$_.DisplayName -match "Energy Efficient Ethernet|Green Ethernet|Power Saving Mode"})
                    foreach($prop in $props){ if(Set-ExtendedAdapterProperty $ToggleKey $adapter $prop @("Disabled","Off")){ $changed++ } }
                }
                Add-Log "Energy-saving NIC options disabled on $changed setting(s)" "#FFFFFF"
            }
            "AUDIO_MMCSS" {
                Set-CurrentTask "Audio MMCSS -> High Priority"
                $p="HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion\Multimedia\SystemProfile\Tasks\Audio"
                Save-Orig "AUDIO_MMCSS_Category" $p "Scheduling Category"; Save-Orig "AUDIO_MMCSS_Priority" $p "Priority"; Save-Orig "AUDIO_MMCSS_SFIO" $p "SFIO Priority"
                Set-RegValue $p "Scheduling Category" "High" "String" | Out-Null
                Set-RegValue $p "Priority" 6 | Out-Null
                Set-RegValue $p "SFIO Priority" "High" "String" | Out-Null
                Add-Log "Windows Audio MMCSS profile set to High" "#FFFFFF"
            }
            "SSD_ReTrim" {
                Set-CurrentTask "SSD ReTrim -> Run Once"
                $volumes=@(Get-Volume -EA SilentlyContinue | Where-Object {$_.DriveType -eq "Fixed" -and $_.DriveLetter})
                $trimmed=0
                foreach($volume in $volumes){ try { Optimize-Volume -DriveLetter $volume.DriveLetter -ReTrim -EA Stop | Out-Null; $trimmed++ } catch { } }
                Add-Log "ReTrim sent to $trimmed fixed volume(s)" "#FFFFFF"
            }
            "SSD_NtfsLastAccess" {
                Set-CurrentTask "NTFS Last Access Updates -> Off"
                $p="HKLM:\SYSTEM\CurrentControlSet\Control\FileSystem"
                Save-Orig "SSD_NtfsLastAccess" $p "NtfsDisableLastAccessUpdate"
                Set-RegValue $p "NtfsDisableLastAccessUpdate" 1 | Out-Null
                Add-Log "NTFS last-access metadata updates disabled" "#FFFFFF"
            }
            "SVC_XboxBackground" {
                Set-CurrentTask "Xbox Background Services -> Disabled"
                $services=@("XblAuthManager","XblGameSave","XboxNetApiSvc","XboxGipSvc")
                $changed=0
                foreach($name in $services){ try { Save-OrigService "SVC_XboxBackground::$name" $name; Stop-Service $name -Force -EA SilentlyContinue; Set-Service $name -StartupType Disabled -EA Stop; $changed++ } catch { } }
                Add-Log "Xbox background services disabled: $changed" "#FFFFFF"
            }
            "TASK_Telemetry" {
                Set-CurrentTask "Telemetry Scheduled Tasks -> Disabled"
                $tasks=@("\Microsoft\Windows\Application Experience\Microsoft Compatibility Appraiser","\Microsoft\Windows\Application Experience\ProgramDataUpdater","\Microsoft\Windows\Customer Experience Improvement Program\Consolidator","\Microsoft\Windows\Customer Experience Improvement Program\UsbCeip")
                $changed=0
                foreach($taskName in $tasks){
                    try {
                        $task=Get-ScheduledTask -TaskPath (Split-Path $taskName -Parent) -TaskName (Split-Path $taskName -Leaf) -EA Stop
                        $id="Task::$taskName"
                        if(-not $Global:OrigMisc.ContainsKey($id)){ $Global:OrigMisc[$id]=@{Type="ScheduledTask";TaskPath=$task.TaskPath;TaskName=$task.TaskName;Enabled=[bool]$task.Settings.Enabled} }
                        Disable-ScheduledTask -InputObject $task -EA Stop | Out-Null; $changed++
                    } catch { }
                }
                Add-Log "Telemetry scheduled tasks disabled: $changed" "#FFFFFF"
            }
            "DEF_FiveMExclusions" {
                Run-GameExclusion
                Add-Log "Defender remains enabled; only game folder exclusions were added" "#FFFFFF"
            }
            "PRIVACY_AdvertisingId" {
                Set-CurrentTask "Advertising ID -> Disabled"
                $p="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\AdvertisingInfo"
                Save-Orig "PRIVACY_AdvertisingId" $p "Enabled"; Set-RegValue $p "Enabled" 0 | Out-Null
                Add-Log "Windows Advertising ID disabled" "#FFFFFF"
            }
            "PRIVACY_ActivityHistory" {
                Set-CurrentTask "Activity History -> Disabled"
                $p="HKCU:\SOFTWARE\Policies\Microsoft\Windows\System"
                Save-Orig "PRIVACY_ActivityHistory_Publish" $p "PublishUserActivities"; Save-Orig "PRIVACY_ActivityHistory_Upload" $p "UploadUserActivities"
                Set-RegValue $p "PublishUserActivities" 0 | Out-Null; Set-RegValue $p "UploadUserActivities" 0 | Out-Null
                Add-Log "Windows activity history publishing disabled" "#FFFFFF"
            }
            "STARTUP_BackgroundApps" {
                Set-CurrentTask "Background App Startup -> Blocked"
                $p="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\BackgroundAccessApplications"
                Save-Orig "STARTUP_BackgroundApps" $p "GlobalUserDisabled"; Set-RegValue $p "GlobalUserDisabled" 1 | Out-Null
                Add-Log "Store app background startup blocked for current user" "#FFFFFF"
            }
            "USB_PowerSuspendOff" {
                Set-CurrentTask "USB Selective Suspend -> Off"
                powercfg /setacvalueindex SCHEME_CURRENT SUB_USB USBSELECTIVE 0 2>&1 | Out-Null
                powercfg /setactive SCHEME_CURRENT 2>&1 | Out-Null
                Add-Log "USB selective suspend disabled on AC power" "#FFFFFF"
            }
            "INPUT_KeyboardRepeat" {
                Set-CurrentTask "Keyboard Repeat -> Fast"
                $p="HKCU:\Control Panel\Keyboard"
                Save-Orig "INPUT_KeyboardRepeat_Delay" $p "KeyboardDelay"; Save-Orig "INPUT_KeyboardRepeat_Speed" $p "KeyboardSpeed"
                Set-RegValue $p "KeyboardDelay" "0" "String" | Out-Null; Set-RegValue $p "KeyboardSpeed" "31" "String" | Out-Null
                Add-Log "Keyboard repeat set to fastest Windows values" "#FFFFFF"
            }
            "INPUT_RawMouse" {
                Set-CurrentTask "Mouse Input -> Raw 1:1"
                $p="HKCU:\Control Panel\Mouse"
                Save-Orig "INPUT_RawMouse_Speed" $p "MouseSpeed"; Save-Orig "INPUT_RawMouse_T1" $p "MouseThreshold1"; Save-Orig "INPUT_RawMouse_T2" $p "MouseThreshold2"
                Set-RegValue $p "MouseSpeed" "0" "String" | Out-Null; Set-RegValue $p "MouseThreshold1" "0" "String" | Out-Null; Set-RegValue $p "MouseThreshold2" "0" "String" | Out-Null
                Add-Log "Mouse acceleration and thresholds set to raw 1:1" "#FFFFFF"
            }
            "FIVEM_HighPerformanceGPU" {
                Set-CurrentTask "FiveM GPU Preference -> High Performance"
                $gpuPrefPath="HKCU:\SOFTWARE\Microsoft\DirectX\UserGpuPreferences"
                $exePaths=@()
                foreach($proc in @(Get-Process -Name "FiveM_GTAProcess","FiveM" -EA SilentlyContinue)){
                    try{ if($proc.Path){ $exePaths += [string]$proc.Path } }catch{}
                }
                $exePaths += @(
                    "$env:LOCALAPPDATA\FiveM\FiveM.app\FiveM.exe",
                    "$env:LOCALAPPDATA\FiveM\FiveM.app\FiveM_GTAProcess.exe"
                )
                $exePaths=@($exePaths | Where-Object {$_ -and (Test-Path -LiteralPath $_)} | Sort-Object -Unique)
                $changed=0
                foreach($exe in $exePaths){
                    Save-Orig "FIVEM_HighPerformanceGPU::$exe" $gpuPrefPath $exe
                    if(Set-RegValue $gpuPrefPath $exe "GpuPreference=2;" "String") { $changed++ }
                }
                if($changed -gt 0){ Add-Log "Windows high-performance GPU preference set for $changed FiveM executable(s)" "#FFFFFF" }
                else { Add-Log "FiveM executable not found - GPU preference skipped" "#A0A0A0" }
            }
            "FIVEM_PriorityBoost" {
                Set-CurrentTask "FiveM Process -> Priority Boost On"
                $procs=@(Get-Process -Name "FiveM_GTAProcess","FiveM" -EA SilentlyContinue)
                $changed=0
                foreach($proc in $procs){
                    try{
                        $id="ProcessPriorityBoost::$($proc.Id)"
                        if(-not $Global:OrigMisc.ContainsKey($id)){ $Global:OrigMisc[$id]=@{Type="ProcessPriorityBoost";ProcessId=[int]$proc.Id;Enabled=[bool]$proc.PriorityBoostEnabled} }
                        $proc.PriorityBoostEnabled=$true
                        $changed++
                    } catch { }
                }
                if($changed -gt 0){ Add-Log "FiveM priority boost enabled on $changed running process(es)" "#FFFFFF" }
                else { Add-Log "FiveM is not running - priority boost will be skipped" "#A0A0A0" }
            }
            "CP_VisualEffects" {
                Set-CurrentTask "Control Panel Visual Effects -> Performance"
                $p="HKCU:\SOFTWARE\Microsoft\Windows\CurrentVersion\Explorer\VisualEffects"
                Save-Orig "CP_VisualEffects" $p "VisualFXSetting"; Set-RegValue $p "VisualFXSetting" 2 | Out-Null
                Add-Log "Windows visual effects switched to performance profile" "#FFFFFF"
            }
            "BLOAT_ProvisionedApps" {
                Set-CurrentTask "Provisioned Bloatware -> Remove"
                $targets=@("Microsoft.BingWeather","Microsoft.BingNews","Microsoft.GetHelp","Microsoft.Getstarted","Microsoft.MicrosoftOfficeHub","Microsoft.MicrosoftSolitaireCollection","Microsoft.People","Microsoft.WindowsFeedbackHub","Microsoft.XboxApp","Microsoft.Xbox.TCUI","Microsoft.XboxGamingOverlay","Microsoft.ZuneMusic","Microsoft.ZuneVideo")
                $removed=0
                foreach($pkg in @(Get-AppxProvisionedPackage -Online -EA SilentlyContinue | Where-Object {$targets -contains $_.DisplayName})){ try { Remove-AppxProvisionedPackage -Online -PackageName $pkg.PackageName -EA Stop | Out-Null; $removed++ } catch { } }
                Add-Log "Provisioned bloat packages removed: $removed (new profiles only)" "#FFFFFF"
            }
            "GPE_GamePolicy" {
                Set-CurrentTask "Group Policy -> Game Capture Off"
                Run-NoGameDVR
                Add-Log "Game capture policy applied (gpedit equivalent)" "#FFFFFF"
            }
        }
        $Global:AppliedKeys[$ToggleKey]=$true
        Save-TweakState
    } catch { Add-Log "$ToggleKey skipped: $($_.Exception.Message)" "#FFFFFF" }
}

function Get-TweakWorkerScript {
    param([string[]]$FunctionNames)
    $builder = New-Object System.Text.StringBuilder
    [void]$builder.AppendLine('$ErrorActionPreference = "Stop"')
    foreach($name in @($FunctionNames | Sort-Object -Unique)){
        $fn = Get-Command $name -CommandType Function -ErrorAction SilentlyContinue
        if(-not $fn){ continue }
        [void]$builder.AppendLine("function $name {")
        [void]$builder.AppendLine($fn.Definition)
        [void]$builder.AppendLine("}")
    }
    [void]$builder.AppendLine(@'
function Add-Log {
    param([string]$msg,[string]$color="#A0A0A0")
    if($null -ne $WorkerEventQueue){
        $isFailure=([string]$color).ToUpperInvariant() -eq "#D8D8D8"
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Log"; Message=$msg; Color=$color; Failure=$isFailure })
    }
}
function Set-CurrentTask {
    param([string]$msg)
    if($null -ne $WorkerEventQueue){
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Task"; Message=$msg; Color="#D2D2D2" })
    }
}
function Emit-WorkerResult {
    param([string]$Status,[string]$Message,[bool]$Changed=$false)
    if($null -ne $WorkerEventQueue){
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Result"; Key=$WorkerToggleKey; Status=$Status; Message=$Message; Changed=$Changed; Color=if($Status -eq "Failed"){"#D8D8D8"}else{"#A0A0A0"} })
    }
}
try {
    $cmd=Get-Command $WorkerRunFunction -CommandType Function -ErrorAction Stop
    & $cmd.ScriptBlock $WorkerToggleKey
    if($AppliedKeys.ContainsKey($WorkerToggleKey) -and [bool]$AppliedKeys[$WorkerToggleKey]){
        Emit-WorkerResult "Applied" "$WorkerToggleKey completed and was verified by the handler." $true
    } else {
        Emit-WorkerResult "Skipped" "$WorkerToggleKey completed without an applied marker; no supported change was confirmed." $false
    }
} catch {
    $msg=$_.Exception.Message
    $looksUnsupported=($msg -match "not found|not supported|cannot find|does not exist|unsupported")
    if($looksUnsupported){ Emit-WorkerResult "Unsupported" $msg $false } else { Emit-WorkerResult "Failed" $msg $false }
    if($null -ne $WorkerEventQueue){
        [void]$WorkerEventQueue.Enqueue([pscustomobject]@{ LessProjectEvent="Error"; Message=$msg; Color="#D8D8D8"; Failure=$true })
    }
}
'@
)
    return $builder.ToString()
}
function Start-TweakWorker {
    param([string]$FunctionName,[string]$ToggleKey,[string]$WorkerScript)
    $runspace = [System.Management.Automation.Runspaces.RunspaceFactory]::CreateRunspace()
    $runspace.ApartmentState = "MTA"
    $runspace.ThreadOptions = "ReuseThread"
    $runspace.Open()
    
    
    foreach($name in @("Orig","AppliedKeys","OrigServices","OrigMisc","TweakToggles","BloatList","KillProcList","StartupDisableTargets","ExtendedTweakKeys","GpuVendors","DetectedGpuVendor","StateDir","StateFile","BackgroundJobs")){
        try {
            $value = Get-Variable -Name $name -Scope Global -ValueOnly -ErrorAction Stop
            $runspace.SessionStateProxy.SetVariable($name,$value)
        } catch {}
    }
    $runspace.SessionStateProxy.SetVariable("WorkerRunFunction",$FunctionName)
    $runspace.SessionStateProxy.SetVariable("WorkerToggleKey",$ToggleKey)
    $worker = [PowerShell]::Create()
    $worker.Runspace = $runspace
    [void]$worker.AddScript($WorkerScript)
    $eventQueue=New-Object 'System.Collections.Concurrent.ConcurrentQueue[object]'
    $runspace.SessionStateProxy.SetVariable("WorkerEventQueue",$eventQueue)
    $async = $worker.BeginInvoke()
    return @{ PowerShell=$worker; Runspace=$runspace; Async=$async; Key=$ToggleKey; EventQueue=$eventQueue; HadError=$false; ResultStatus=$null; ResultMessage=$null; ResultChanged=$false; StartedUtc=[DateTime]::UtcNow }
}
function Stop-TweakWorker {
    if(-not $Global:TweakWorker){ return }
    $worker = $Global:TweakWorker
    try { if($worker.PowerShell -and $worker.PowerShell.InvocationStateInfo.State -eq "Running"){ $worker.PowerShell.Stop() } } catch {}
    try { if($worker.PowerShell){ $worker.PowerShell.Dispose() } } catch {}
    try { if($worker.Runspace){ $worker.Runspace.Close(); $worker.Runspace.Dispose() } } catch {}
    $Global:TweakWorker = $null
}
function Receive-TweakWorkerEvents {
    param($Worker)
    if(-not $Worker -or -not $Worker.EventQueue){ return $false }
    $hasError=$false
    $eventObj=$null
    while($Worker.EventQueue.TryDequeue([ref]$eventObj)){
        if($eventObj -and $eventObj.PSObject.Properties["LessProjectEvent"]){
            $eventType=[string]$eventObj.LessProjectEvent
            if($eventType -eq "Log"){
                Add-Log ([string]$eventObj.Message) ([string]$eventObj.Color)
                if($eventObj.PSObject.Properties["Failure"] -and [bool]$eventObj.Failure){ $Worker["HadError"]=$true }
            } elseif($eventType -eq "Task"){
                Set-CurrentTask ([string]$eventObj.Message)
            } elseif($eventType -eq "Result"){
                $status=[string]$eventObj.Status
                $Worker["ResultStatus"]=$status
                $Worker["ResultMessage"]=[string]$eventObj.Message
                $Worker["ResultChanged"]=[bool]$eventObj.Changed
                if($status -eq "Failed"){ $hasError=$true; $Worker["HadError"]=$true }
                $color=if($status -eq "Failed"){"#D8D8D8"}elseif($status -eq "Applied"){"#FFFFFF"}else{"#A0A0A0"}
                Add-Log ("[$status] {0}: {1}" -f $Worker.Key,$eventObj.Message) $color
            } elseif($eventType -eq "Error"){
                $hasError=$true; $Worker["HadError"]=$true
                Add-Log ([string]$eventObj.Message) ([string]$eventObj.Color)
            }
        }
        $eventObj=$null
    }
    return ($hasError -or [bool]$Worker["HadError"])
}

function Invoke-ApplyPressFx{
    try {
        if(-not $BtnRun){ return }
        [void]$BtnRun.ApplyTemplate()
        if($BtnRun.RenderTransform -is [System.Windows.Media.ScaleTransform]){
            $pressX=New-Object System.Windows.Media.Animation.DoubleAnimation
            $pressX.From=1.0; $pressX.To=0.965; $pressX.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(95)); $pressX.AutoReverse=$true
            $pressX.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
            $pressY=$pressX.Clone()
            $BtnRun.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleXProperty,$pressX)
            $BtnRun.RenderTransform.BeginAnimation([System.Windows.Media.ScaleTransform]::ScaleYProperty,$pressY)
        }
        $applyBorder=$BtnRun.Template.FindName("ApplyBorder",$BtnRun)
        if($applyBorder){
            $flash=New-Object System.Windows.Media.Animation.ColorAnimation
            $flash.From=[System.Windows.Media.Color]::FromRgb(0xE9,0xE9,0xE9); $flash.To=[System.Windows.Media.Color]::FromRgb(0xD0,0xD0,0xD0); $flash.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(150)); $flash.AutoReverse=$true
            $flash.EasingFunction=New-Object System.Windows.Media.Animation.CubicEase
            $applyBrush=$applyBorder.Background
            if($applyBrush -is [System.Windows.Media.SolidColorBrush]){ $applyBrush.BeginAnimation([System.Windows.Media.SolidColorBrush]::ColorProperty,$flash) }
            $glow=$applyBorder.Effect
            if(-not ($glow -is [System.Windows.Media.Effects.DropShadowEffect])){ $glow=New-Object System.Windows.Media.Effects.DropShadowEffect; $applyBorder.Effect=$glow }
            $glow.Color=[System.Windows.Media.Color]::FromRgb(0xD0,0xD0,0xD0); $glow.BlurRadius=22; $glow.ShadowDepth=0
            $glowPulse=New-Object System.Windows.Media.Animation.DoubleAnimation
            $glowPulse.From=0.28; $glowPulse.To=0.85; $glowPulse.Duration=New-Object System.Windows.Duration ([TimeSpan]::FromMilliseconds(180)); $glowPulse.AutoReverse=$true
            $glowPulse.EasingFunction=New-Object System.Windows.Media.Animation.SineEase
            $glow.BeginAnimation([System.Windows.Media.Effects.DropShadowEffect]::OpacityProperty,$glowPulse)
        }
    } catch {}
}
